window.obtenerIconoCategoriaInsumo = function(categoria) {
  if (!categoria) return '📦';
  const c = String(categoria).toLowerCase();
  if (c.includes('carne') || c.includes('res') || c.includes('cerdo') || c.includes('pollo')) return '🥩';
  if (c.includes('licor') || c.includes('ron') || c.includes('whisky') || c.includes('tequila') || c.includes('vodka')) return '🍾';
  if (c.includes('cerveza') || c.includes('bebida') || c.includes('refresco')) return '🍺';
  if (c.includes('verdura') || c.includes('vegetal') || c.includes('fruta')) return '🥬';
  if (c.includes('lacteo') || c.includes('queso')) return '🧀';
  if (c.includes('pan') || c.includes('panaderia')) return '🍞';
  if (c.includes('marisco') || c.includes('pescado')) return '🦐';
  if (c.includes('salsa') || c.includes('aderezo') || c.includes('especia')) return '🧂';
  return '📦';
};


// ============================================================================
// INTERCEPTOR GLOBAL FETCH CON TOKEN JWT DE SESIÓN
// ============================================================================
(function() {
  const _origFetch = window.fetch;
  window.fetch = async function(resource, init = {}) {
    const token = sessionStorage.getItem('pos_token') || localStorage.getItem('pos_token');
    if (token && (typeof resource === 'string' || (typeof URL !== 'undefined' && resource instanceof URL))) {
      const urlStr = typeof resource === 'string' ? resource : resource.toString();
      if (urlStr.startsWith('/api/') || urlStr.includes('/api/')) {
        init = init ? { ...init } : {};
        if (!init.headers) {
          init.headers = { 'Authorization': 'Bearer ' + token };
        } else if (typeof Headers !== 'undefined' && init.headers instanceof Headers) {
          if (!init.headers.has('Authorization')) {
            init.headers.set('Authorization', 'Bearer ' + token);
          }
        } else if (Array.isArray(init.headers)) {
          const hasAuth = init.headers.some(([k]) => k.toLowerCase() === 'authorization');
          if (!hasAuth) {
            init.headers.push(['Authorization', 'Bearer ' + token]);
          }
        } else {
          if (!init.headers['Authorization'] && !init.headers['authorization']) {
            init.headers['Authorization'] = 'Bearer ' + token;
          }
        }
      }
    }
    return _origFetch.call(this, resource, init);
  };
})();

// ============================================================================
// MODAL MANAGER CENTRALIZADO (CONTROL DE ESTADO ÚNICO Y EXCLUSIVIDAD DE MODALES)
// ============================================================================
window._modalActivoId = null;

window.cerrarTodosLosModales = function(excluirId = null) {
  const modales = document.querySelectorAll('.modal, .modal-backdrop');
  modales.forEach(m => {
    if (m.id === 'modalComandero' && excluirId && ['modalSeleccionBaldeNacional', 'modalSeleccionVariante', 'modalModificadores', 'modalPersonalizarBoton', 'modalCobro', 'modalSplitBill', 'modalConfirmacionAccion'].includes(excluirId)) {
      return;
    }
    if (!excluirId || m.id !== excluirId) {
      m.classList.remove('active');
      m.style.display = 'none';
    }
  });
  if (!excluirId) {
    window._modalActivoId = null;
  }
};

window.abrirModalExclusivo = function(modalId) {
  if (!modalId) return;
  window.cerrarTodosLosModales(modalId);
  const modal = document.getElementById(modalId);
  if (modal) {
    modal.classList.add('active');
    modal.style.display = 'flex';
    window._modalActivoId = modalId;
  }
};

// ============================================================================
// MODAL DE CONFIRMACIÓN PERSONALIZADO — reemplaza confirm() nativo del browser
// ============================================================================
window.confirmarAccion = function(opciones) {
  return new Promise((resolve) => {
    const modal     = document.getElementById('modalConfirmacionAccion');
    const elIcono   = document.getElementById('modalConfirmIcono');
    const elTitulo  = document.getElementById('modalConfirmTitulo');
    const elSubtit  = document.getElementById('modalConfirmSubtitulo');
    const elMensaje = document.getElementById('modalConfirmMensaje');
    const elBtnSi   = document.getElementById('modalConfirmBtnSi');
    const elBtnNo   = document.getElementById('modalConfirmBtnNo');

    if (!modal) { resolve(false); return; }

    // Configurar contenido
    if (elIcono)   elIcono.textContent   = opciones.icono   || '⚠️';
    if (elTitulo)  elTitulo.textContent  = opciones.titulo  || '¿Confirmar acción?';
    if (elSubtit)  elSubtit.textContent  = opciones.subtitulo || 'Esta acción no se puede deshacer';
    if (elMensaje) elMensaje.textContent = opciones.mensaje || '';

    // Color del botón confirmar según peligro
    // Color del botón confirmar según tipo
    if (elBtnSi) {
      const esPeligroso = opciones.tipo === 'peligro' || opciones.tipo === 'danger';
      const esVerde = opciones.tipo === 'exito' || opciones.tipo === 'success' || opciones.tipo === 'verde' || opciones.tipo === 'primario';
      elBtnSi.style.background = esPeligroso
        ? 'linear-gradient(135deg,#ef4444,#dc2626)'
        : (esVerde ? 'linear-gradient(135deg,#10b981,#059669)' : 'linear-gradient(135deg,#6366f1,#4f46e5)');
      elBtnSi.style.boxShadow = esPeligroso
        ? '0 4px 14px rgba(239,68,68,0.45)'
        : (esVerde ? '0 4px 14px rgba(16,185,129,0.45)' : '0 4px 14px rgba(99,102,241,0.45)');
      elBtnSi.textContent = opciones.txtSi || 'Confirmar';
    }
    if (elBtnNo) elBtnNo.textContent = opciones.txtNo || 'Cancelar';

    // Callbacks
    window._confirmarAceptar = () => { modal.style.display = 'none'; resolve(true);  };
    window._confirmarRechazar = () => { modal.style.display = 'none'; resolve(false); };

    // Mostrar modal
    modal.style.display = 'flex';
  });
};

