window.ajustarCapacidadModal = function(delta) {
  const txtInput = document.getElementById('txtCapacidadMesaInput');
  if (!txtInput) return;
  let val = parseInt(txtInput.value, 10) || 4;
  val = Math.max(1, Math.min(100, val + delta));
  txtInput.value = val;
};

