// Milestone 2 Domain Helpers
function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function evaluarEstadoMesaKDS(detalles = []) {
  const cocinaItems = detalles.filter(
    (it) => it.destino === 'cocina' && it.estado_comanda !== 'anulado'
  );

  if (!cocinaItems.length) return 'abierta';

  const listos = cocinaItems.filter((it) => it.estado_comanda === 'listo');
  const pendientes = cocinaItems.filter(
    (it) => it.estado_comanda === 'pendiente' || it.estado_comanda === 'preparando'
  );

  if (pendientes.length === 0 && listos.length > 0) {
    return 'activa';
  } else if (listos.length > 0 && pendientes.length > 0) {
    return 'esperando_parcial';
  } else {
    return 'esperando';
  }
}

function formatearTooltipEspera(primeraComandaHora, itemsPendientes = [], ahora = new Date()) {
  const fechaPedido = new Date(primeraComandaHora);
  const diffMs = Math.max(0, ahora.getTime() - fechaPedido.getTime());
  const minutos = Math.floor(diffMs / 60000);

  const titulo = `⏱️ Esperando hace ${minutos} min`;
  const itemsList = itemsPendientes.map((it) => (typeof it === 'string' ? it : (it.nombre_producto || it.nombre)));

  return {
    minutos,
    titulo,
    items: itemsList,
    tooltipText: `${titulo}\n${itemsList.map((i) => `• ${i}`).join('\n')}`
  };
}

if (typeof window !== 'undefined') {
  window.evaluarEstadoMesaKDS = evaluarEstadoMesaKDS;
  window.formatearTooltipEspera = formatearTooltipEspera;
}

// Formateo de moneda (Colones costarricenses enteros con separación de miles por punto: ₡ 50.000)
function formatCRC(num) {
  const val = Math.round(Number(num) || 0);
  return '₡ ' + val.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

// Inverso de formatCRC: '₡ 1.800' → 1800 (el punto es separador de miles, NO decimal)
function parseCRC(text) {
  if (typeof text === 'number') return Math.round(text);
  if (!text) return 0;
  const digitsOnly = String(text).replace(/[₡\s,\.]/g, '');
  return parseInt(digitsOnly, 10) || 0;
}


// Formateo de montos en mesas sin decimales según requerimiento
function formatCRCSinDecimales(num) {
  return formatCRC(num);
}

function negocioAceptaDolares() {
  if (typeof negocioTieneCaracteristica === 'function') {
    if (!negocioTieneCaracteristica('bimoneda_dolares')) {
      return false;
    }
  }
  const m = estado.negocioActual?.moneda || 'CRC';
  return m === 'CRC_USD' || m === 'USD' || (typeof negocioTieneCaracteristica === 'function' && negocioTieneCaracteristica('bimoneda_dolares'));
}
window.negocioAceptaDolares = negocioAceptaDolares;

window.actualizarBadgeTipoCambioTop = function() {
  const badge = document.getElementById('posTipoCambioBadge');
  const lbl = document.getElementById('lblTipoCambioTop');
  const aceptaUSD = typeof negocioAceptaDolares === 'function' ? negocioAceptaDolares() : false;
  const bccr = window._tipoCambioBCCR;
  const tc = bccr?.venta || parseFloat(localStorage.getItem('pos_tipo_cambio_usd')) || estado?.negocioActual?.tipo_cambio_usd || 450;
  
  if (lbl) {
    lbl.textContent = `₡${Number(tc).toLocaleString('es-CR', { minimumFractionDigits: (tc % 1 === 0 ? 0 : 2), maximumFractionDigits: 2 })}`;
  }
  if (badge) {
    badge.style.display = aceptaUSD ? 'inline-flex' : 'none';
    if (bccr && bccr.venta) {
      badge.title = `Tipo de cambio oficial BCCR (${bccr.fecha || 'Hoy'}): Venta ₡${bccr.venta} | Compra ₡${bccr.compra || bccr.venta} [${bccr.fuente || 'BCCR'}]`;
    }
  }
};

window.actualizarTipoCambioBCCR = async function() {
  try {
    const res = await fetch('/api/tipo-cambio');
    const data = await res.json();
    const tc = Number(data?.venta || data?.tipo_cambio) || 0;
    if (tc > 0) {
      window._tipoCambioBCCR = { ...data, venta: tc, tipo_cambio: tc };
      localStorage.setItem('pos_tipo_cambio_usd', String(tc));
      const txtTC = document.getElementById('txtTipoCambioUSD');
      if (txtTC) {
        txtTC.value = tc;
      }
      actualizarBadgeTipoCambioTop();
      return tc;
    }
  } catch (e) {
    console.warn('No se pudo obtener el tipo de cambio BCCR en vivo:', e);
  }
  actualizarBadgeTipoCambioTop();
  return 450;
};

// Intentar cargar tipo de cambio BCCR en segundo plano al iniciar
setTimeout(() => {
  if (typeof window.actualizarTipoCambioBCCR === 'function') {
    window.actualizarTipoCambioBCCR().catch(() => {});
  }
}, 1000);

window.aplicarConfiguracionMonedaNegocio = function() {
  const aceptaUSD = negocioAceptaDolares();

  actualizarBadgeTipoCambioTop();
  if (aceptaUSD) {
    actualizarTipoCambioBCCR().catch(() => {});
  }

  // Pestaña Dólares en Modal de Cobro
  const tabDol = document.getElementById('tabCobroDolares');
  if (tabDol) tabDol.style.display = aceptaUSD ? '' : 'none';

  // Si no acepta dólares y estaba en pestaña Dólares, volver a Efectivo
  if (!aceptaUSD) {
    const activeTab = document.querySelector('.pay-method-tab.active');
    if (activeTab && activeTab.dataset.method === 'Dolares') {
      const tabEf = document.querySelector('.pay-method-tab[data-method="Efectivo"]');
      if (tabEf) tabEf.click();
    }
  }

  // Fila Dólares en Pago Mixto
  const rowMixtoUSD = document.getElementById('rowMixtoUSD');
  if (rowMixtoUSD) rowMixtoUSD.style.display = aceptaUSD ? '' : 'none';

  // Fila Dólares en Apertura de Caja
  const rowAperturaUSD = document.getElementById('rowAperturaUSD');
  if (rowAperturaUSD) rowAperturaUSD.style.display = aceptaUSD ? 'block' : 'none';

  // Filas Dólares en Cierre Z
  const czRowVentasDolares = document.getElementById('czRowVentasDolares');
  if (czRowVentasDolares) czRowVentasDolares.style.display = aceptaUSD ? '' : 'none';

  const czRowEsperadoDolares = document.getElementById('czRowEsperadoDolares');
  if (czRowEsperadoDolares) czRowEsperadoDolares.style.display = aceptaUSD ? '' : 'none';

  const czRowDolaresReal = document.getElementById('czRowDolaresReal');
  if (czRowDolaresReal) czRowDolaresReal.style.display = aceptaUSD ? '' : 'none';

  const czTipoCambioInfo = document.getElementById('czTipoCambioInfo');
  if (czTipoCambioInfo) czTipoCambioInfo.style.display = aceptaUSD ? '' : 'none';

  const czConteosWrapper = document.getElementById('czConteosWrapper');
  if (czConteosWrapper) {
    czConteosWrapper.style.gridTemplateColumns = aceptaUSD ? '1fr 1fr' : '1fr';
  }

  // Asignar tipo de cambio inicial en txtTipoCambioUSD si no tiene valor
  const txtTC = document.getElementById('txtTipoCambioUSD');
  if (txtTC) {
    const tc = estado.negocioActual?.tipo_cambio_usd || parseFloat(localStorage.getItem('pos_tipo_cambio_usd')) || window._tipoCambioBCCR?.venta || 520;
    if (!txtTC.value) txtTC.value = tc;
  }
};

/**
 * Formateador de Fecha y Hora en zona horaria oficial de Costa Rica (America/Costa_Rica) con formato am/pm 12 horas.
 */
function formatearFechaHoraCR(fechaInput, opciones = {}) {
  if (!fechaInput) return '-';
  try {
    const d = (fechaInput instanceof Date) ? fechaInput : new Date(fechaInput);
    if (isNaN(d.getTime())) return String(fechaInput);

    if (opciones.soloHora) {
      return d.toLocaleTimeString('es-CR', {
        timeZone: 'America/Costa_Rica',
        hour: '2-digit',
        minute: '2-digit',
        second: opciones.segundos ? '2-digit' : undefined,
        hour12: true
      });
    }

    if (opciones.soloFecha) {
      return d.toLocaleDateString('es-CR', {
        timeZone: 'America/Costa_Rica',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      });
    }

    return d.toLocaleString('es-CR', {
      timeZone: 'America/Costa_Rica',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: opciones.segundos ? '2-digit' : undefined,
      hour12: true
    });
  } catch (err) {
    return String(fechaInput);
  }
}
window.formatearFechaHoraCR = formatearFechaHoraCR;

// Control y Alternancia de Pisos (1er Piso y Segundo Piso)
window.cambiarPisoSalon = function(piso) {
  estado.pisoActual = Number(piso) || 1;
  const tabs = document.querySelectorAll('.zone-tab');
  tabs.forEach(t => t.classList.remove('active'));
  if (estado.pisoActual === 2) {
    const tab2 = document.querySelector('.zone-tab[data-zona="segundo"]');
    if (tab2) tab2.classList.add('active');
    else {
      const tabTodas = document.querySelector('.zone-tab[data-zona="todas"]');
      if (tabTodas) tabTodas.classList.add('active');
    }
  } else {
    const tabTodas = document.querySelector('.zone-tab[data-zona="todas"]');
    if (tabTodas) tabTodas.classList.add('active');
  }
  actualizarBotonPisoSalon();
  renderSalón(estado.pisoActual === 2 ? 'segundo' : 'todas');
};

window.togglePisoActual = function() {
  window.cambiarPisoSalon(estado.pisoActual === 2 ? 1 : 2);
};

window.actualizarBotonPisoSalon = function() {
  const btn = document.getElementById('btnTogglePisoSalon');
  if (!btn) return;

  const otroPiso = (estado.pisoActual === 2 ? 1 : 2);
  const mesasOtroPiso = (estado.mesas || []).filter(m => {
    const mesaPiso = m.piso || (m.zona_id === 5 || (m.zonaNombre && m.zonaNombre.toLowerCase().includes('segundo')) ? 2 : 1);
    return mesaPiso === otroPiso;
  });

  const hayCuentaPedidaOtroPiso = mesasOtroPiso.some(m => m.estado === 'cuenta' || m.pidio_cuenta_qr === 1 || m.cuenta_pedida);

  let customStyles = null;
  if (estado.personalizacionPagina?.elementStyles) {
    for (const [k, val] of Object.entries(estado.personalizacionPagina.elementStyles)) {
      if (k === '#btnTogglePisoSalon' || k === 'btnTogglePisoSalon' || k.includes('btnTogglePisoSalon')) {
        customStyles = val;
        break;
      }
    }
  }
  let customTexto = customStyles?.text;
  if (!customTexto && estado.personalizacionPagina?.textos) {
    for (const [k, val] of Object.entries(estado.personalizacionPagina.textos)) {
      if (k === '#btnTogglePisoSalon' || k === 'btnTogglePisoSalon' || k.includes('btnTogglePisoSalon')) {
        customTexto = val.valor;
        break;
      }
    }
  }

  if (estado.pisoActual === 2) {
    btn.innerHTML = hayCuentaPedidaOtroPiso 
      ? '🚨 ¡Piso 1 Pide Cuenta! ↙' 
      : (customTexto && customTexto.includes('Primer') ? customTexto : '🏢 Ver Primer Piso ↙');
    btn.classList.add('piso-2-activo');
  } else {
    btn.innerHTML = hayCuentaPedidaOtroPiso 
      ? '🚨 ¡Piso 2 Pide Cuenta! ↗' 
      : (customTexto || '🏢 Ver Segundo Piso ↗');
    btn.classList.remove('piso-2-activo');
  }

  if (hayCuentaPedidaOtroPiso) {
    btn.classList.add('alerta-piso-cuenta');
  } else {
    btn.classList.remove('alerta-piso-cuenta');
  }

  // Re-aplicar estilos visuales personalizados si existen
  // Re-aplicar estilos visuales personalizados si existen con !important para sobreescribir gradientes
  if (customStyles) {
    if (customStyles.bgColor) btn.style.backgroundColor = customStyles.bgColor;
    if (customStyles.textColor) btn.style.color = customStyles.textColor;
    if (customStyles.fontSize) btn.style.fontSize = customStyles.fontSize;
    if (customStyles.borderRadius) btn.style.borderRadius = customStyles.borderRadius;
    if (customStyles.padding) btn.style.padding = customStyles.padding;
    if (customStyles.bgColor) {
      btn.style.setProperty('background', customStyles.bgColor, 'important');
      btn.style.setProperty('background-image', 'none', 'important');
    }
    if (customStyles.textColor) btn.style.setProperty('color', customStyles.textColor, 'important');
    if (customStyles.fontSize) btn.style.setProperty('font-size', customStyles.fontSize, 'important');
    if (customStyles.borderRadius) btn.style.setProperty('border-radius', customStyles.borderRadius, 'important');
    if (customStyles.padding) btn.style.setProperty('padding', customStyles.padding, 'important');
    if (customStyles.customCSS) btn.style.cssText += ';' + customStyles.customCSS;
  }
};

