window.forzarDesconectarSesionPrevia = async function() {
  const usuarioId = window._ultimoUsuarioIdBloqueado;
  const usuarioNombre = window._ultimoUsuarioNombreBloqueado || 'el usuario';
  if (!usuarioId) {
    alert('⚠️ No se identificó el usuario bloqueado.');
    return;
  }

  const pinAdmin = await window.solicitarPinAdmin({
    icono: '🔓',
    titulo: 'Liberar Sesión Activa',
    subtitulo: 'Autorización de Administrador',
    mensaje: `Ingresa el PIN de Administrador para cerrar la sesión previa de "${usuarioNombre}" en el otro dispositivo:`
  });
  if (!pinAdmin) return;

  try {
    const nid = estado.negocioActual?.id || (sessionStorage.getItem('pos_negocio') ? JSON.parse(sessionStorage.getItem('pos_negocio')).id : 1);
    const res = await fetch(`/api/admin/usuarios/${usuarioId}/liberar-sesion`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-negocio-id': String(nid)
      },
      body: JSON.stringify({ pinAdmin })
    });

    const data = await res.json();
    if (!res.ok) {
      alert('❌ Error: ' + (data.error || 'No se pudo liberar la sesión'));
      return;
    }

    cerrarAlertaSesionYaActiva();
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`✅ Sesión previa de "${usuarioNombre}" liberada. Ingresando...`, 'success');
    }

    // Reintentar login inmediatamente
    const btnLogin = document.getElementById('btnSubmitLogin') || document.getElementById('btnLogin');
    if (btnLogin) {
      btnLogin.click();
    } else if (typeof window.ejecutarLogin === 'function') {
      window.ejecutarLogin();
    }
  } catch (e) {
    alert('❌ Error: ' + e.message);
  }
};

window.guardarConfiguracionSeguridadRed = async function() {
  const btn = document.getElementById('btnGuardarSeguridadRed');
  const txtOriginal = btn ? btn.innerHTML : '';
  try {
    const chkIp = document.getElementById('chkAdminRestringirIP');
    const txtIps = document.getElementById('txtAdminIpsPermitidas');
    const chkDisp = document.getElementById('chkAdminRestringirDispositivos');
    const chkSesion = document.getElementById('chkAdminSesionUnica');

    const restringirIp = chkIp ? chkIp.checked : false;
    const ips = txtIps ? txtIps.value.trim() : '';
    const restringirDisp = chkDisp ? chkDisp.checked : false;
    const sesionUnica = chkSesion ? chkSesion.checked : true;

    if (restringirIp && !ips) {
      alert('⚠️ Si activas la restricción de red, debes ingresar al menos una IP pública autorizada.');
      return;
    }

    if (btn) {
      btn.disabled = true;
      btn.innerHTML = 'Guardando...';
    }

    const nid = estado.negocioActual?.id || 1;
    const res = await fetch('/api/admin/seguridad-red', {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'x-negocio-id': String(nid)
      },
      body: JSON.stringify({
        restringir_ip_operativos: restringirIp,
        ips_permitidas: ips,
        restringir_dispositivos: restringirDisp,
        sesion_unica_activa: sesionUnica,
        usuarioNombre: estado.usuarioActual?.nombre || 'Administrador'
      })
    });

    const data = await res.json();
    if (!res.ok) {
      alert('❌ Error al guardar seguridad: ' + (data.error || 'Error del servidor'));
      return;
    }

    cerrarModalSeguridadRed();
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('🛡️ Configuración de seguridad, red y terminales guardada exitosamente.', 'success');
    } else {
      alert('✅ ' + (data.message || 'Configuración guardada exitosamente'));
    }
  } catch (e) {
    alert('❌ Error al comunicar con el servidor: ' + e.message);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = txtOriginal;
    }
  }
};

