document.getElementById('btnAdminPersonal')?.addEventListener('click', () => {
  cargarEmpleadosAdmin();
  document.getElementById('modalAdminPersonal')?.classList.add('active');
});

document.getElementById('btnCloseAdminPersonal')?.addEventListener('click', () => {
  document.getElementById('modalAdminPersonal')?.classList.remove('active');
});

async function cargarEmpleadosAdmin() {
  try {
    const nid = estado.negocioActual ? estado.negocioActual.id : 1;
    const [resEmp, resCajas] = await Promise.all([
      fetch('/api/admin/empleados?negocio_id=' + nid),
      fetch('/api/cajas-fisicas?negocio_id=' + nid).catch(() => ({ ok: false }))
    ]);

    // Poblar selector de caja pre-asignada
    const selCajaDefecto = document.getElementById('staffCajaDefecto');
    if (selCajaDefecto && resCajas.ok) {
      const dataCajas = await resCajas.json();
      if (dataCajas && dataCajas.cajas_fisicas) {
        selCajaDefecto.innerHTML = '<option value="">-- Sin pre-asignación (Elegir al abrir) --</option>' +
          dataCajas.cajas_fisicas.map(c => `<option value="${c.id}">${c.icono || '💳'} ${escapeHtml(c.nombre)} (${escapeHtml(c.codigo || 'CAJA')})</option>`).join('');
      }
    }

    const tbody = document.getElementById('adminStaffTableBody');
    if (!tbody) return;

    if (!resEmp.ok) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:#ef4444; padding:20px;">Error al cargar lista de personal</td></tr>';
      return;
    }
    const empleados = await resEmp.json();
    if (!Array.isArray(empleados)) {
      tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; color:#ef4444; padding:20px;">${escapeHtml(empleados.error || 'Respuesta inválida')}</td></tr>`;
      return;
    }

    if (!empleados.length) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:#94a3b8; padding:20px;">No hay colaboradores registrados en este local.</td></tr>';
      return;
    }

    // Configurar visibilidad de roles en el dropdown según el rol del usuario conectado
    const userRolActual = (estado.usuarioActual?.rol || '').toLowerCase();
    const optAdmin = document.getElementById('optStaffRolAdmin');
    const optSuperadmin = document.getElementById('optStaffRolSuperadmin');
    const puedeCrearAdmin = userRolActual === 'superadmin' || userRolActual === 'developer';
    if (optAdmin) optAdmin.style.display = puedeCrearAdmin ? '' : 'none';
    if (optSuperadmin) optSuperadmin.style.display = userRolActual === 'developer' ? '' : 'none';

    tbody.innerHTML = empleados.map(e => {
      let badgeStyle = 'background:#1e293b; color:#38bdf8;';
      let rolBadge = escapeHtml(e.rolDisplay || e.rol);
      if (e.rol === 'superadmin') {
        badgeStyle = 'background: rgba(245, 158, 11, 0.2); color: #fbbf24; border: 1px solid #f59e0b; font-weight: 800;';
        rolBadge = '👑 Super Admin';
      } else if (e.rol === 'admin' || e.rol === 'administrador') {
        badgeStyle = 'background: rgba(56, 189, 248, 0.2); color: #38bdf8; border: 1px solid #0284c7; font-weight: 700;';
        rolBadge = '🛡️ Administrador';
      }

      const cajaBadge = e.caja_defecto_nombre 
        ? `<span class="badge-tag" style="background:rgba(16,185,129,0.15); color:#34d399; font-size:0.75rem; margin-left:4px;">💳 ${escapeHtml(e.caja_defecto_nombre)}</span>`
        : '';

      return `
      <tr>
        <td><strong>${escapeHtml(e.nombre_completo)}</strong></td>
        <td><code>${escapeHtml(e.usuario)}</code></td>
        <td><span class="badge-tag" style="${badgeStyle}">${rolBadge}</span></td>
        <td><span class="badge-tag" style="${badgeStyle}">${rolBadge}</span>${cajaBadge}</td>
        <td><code>${escapeHtml(e.pin || '1234')}</code></td>
        <td>
          ${e.rol === 'superadmin' && userRolActual !== 'developer' ? '<small style="color:#f59e0b; font-weight:700;">👑 Dueño</small>' : `
            <button class="btn-item-tool" style="color:#ef4444;" onclick="eliminarEmpleadoAdmin(${e.id})">🗑️ Despedir</button>
          `}
        </td>
      </tr>
      `;
    }).join('');
  } catch (e) {
    console.error('Error cargando empleados admin:', e);
  }
}

document.getElementById('btnGuardarEmpleado').addEventListener('click', async () => {
  const nombre_completo = document.getElementById('staffNombre').value.trim();
  const usuario = document.getElementById('staffUsuario').value.trim();
  const password = document.getElementById('staffPassword').value.trim();
  const rol = document.getElementById('staffRol').value;
  const genero = document.getElementById('staffGenero').value;
  const pin = document.getElementById('staffPin').value.trim() || '1234';
  const caja_defecto_id = document.getElementById('staffCajaDefecto')?.value || null;

  if (!nombre_completo || !usuario || !password) {
    alert('Por favor completa todos los campos del empleado.');
    return;
  }

  try {
    const res = await fetch('/api/admin/empleados', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        negocio_id: estado.negocioActual ? estado.negocioActual.id : 1,
        usuario,
        nombre_completo,
        password,
        rol,
        genero,
        pin,
        caja_defecto_id: caja_defecto_id ? Number(caja_defecto_id) : null
      })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);

    alert(`✅ Empleado registrado exitosamente con título: ${genero === 'F' ? 'Salonera' : 'Salonero'}`);
    document.getElementById('staffNombre').value = '';
    document.getElementById('staffUsuario').value = '';
    document.getElementById('staffPassword').value = '';
    if (document.getElementById('staffCajaDefecto')) document.getElementById('staffCajaDefecto').value = '';
    cargarEmpleadosAdmin();
  } catch (e) {
    alert('❌ ' + e.message);
  }
});

window.eliminarEmpleadoAdmin = async function(id) {
  const confirmado = await confirmarAccion({
    icono: '👥',
    titulo: '¿Eliminar colaborador?',
    subtitulo: 'Esta acción no se puede deshacer',
    mensaje: '¿Estás seguro de que deseas eliminar a este colaborador del equipo?',
    tipo: 'peligro',
    txtSi: '🗑️ Sí, eliminar',
    txtNo: 'Cancelar'
  });
  if (!confirmado) return;
  try {
    await fetch('/api/admin/empleados/' + id, { method: 'DELETE' });
    cargarEmpleadosAdmin();
  } catch (e) {}
};

// ============================================================================
// 4. PERSONALIZACIÓN VISUAL DE BOTONES CON FOTOS (ADMIN & DEV)
// ============================================================================
document.getElementById('btnPersonalizarFotos').addEventListener('click', () => {
  poblarSelectorProductosCustom();
  renderGaleriaPresets();
  cargarDatosProductoCustom();
  document.getElementById('modalPersonalizarBoton').classList.add('active');
});

document.getElementById('btnCloseCustomBoton').addEventListener('click', () => document.getElementById('modalPersonalizarBoton').classList.remove('active'));
document.getElementById('btnCancelarCustomBoton').addEventListener('click', () => document.getElementById('modalPersonalizarBoton').classList.remove('active'));

function poblarSelectorProductosCustom() {
  const sel = document.getElementById('custSelectProducto');
  sel.innerHTML = estado.productos.map(p => `
    <option value="${p.id}">${p.nombre} - ${formatCRC(p.precio)} (${p.destino.toUpperCase()})</option>
  `).join('');
}

function renderGaleriaPresets() {
  const grid = document.getElementById('galleryPresetsGrid');
  grid.innerHTML = estado.presetsFotos.map((f, idx) => `
    <img class="preset-photo-thumb" src="${f.url}" alt="${f.cat}" title="${f.cat}" onclick="seleccionarPresetFoto('${f.url}')" />
  `).join('');
}

window.seleccionarPresetFoto = function(url) {
  document.getElementById('custImagenUrl').value = url;
  actualizarPreviewBoton();
};

window.cargarDatosProductoCustom = function() {
  const prodId = Number(document.getElementById('custSelectProducto').value);
  const p = estado.productos.find(item => item.id === prodId);
  if (!p) return;

  document.getElementById('custImagenUrl').value = p.imagen_url || '';
  document.getElementById('previewNombre').textContent = p.nombre;
  document.getElementById('previewPrecio').textContent = formatCRC(p.precio);
  actualizarPreviewBoton();
};

window.actualizarPreviewBoton = function() {
  const url = document.getElementById('custImagenUrl').value.trim();
  const box = document.getElementById('previewImgBox');
  if (url) {
    box.innerHTML = `<img class="prod-card-thumb" src="${url}" alt="Foto" />`;
  } else {
    box.innerHTML = '<div class="prod-card-no-thumb">🍽️</div>';
  }
};

document.getElementById('btnGuardarFotoBoton').addEventListener('click', async () => {
  const prodId = Number(document.getElementById('custSelectProducto').value);
  const imagen_url = document.getElementById('custImagenUrl').value.trim();

  try {
    const res = await fetch(`/api/productos/${prodId}/visual`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ imagen_url })
    });
    const data = await res.json();
    alert('🎨 ¡Foto del platillo guardada exitosamente! El botón en pantalla táctil ahora muestra esta foto.');
    document.getElementById('modalPersonalizarBoton').classList.remove('active');
    cargarMenuDesdeBackend();
  } catch (e) {
    alert('Error al guardar foto del platillo.');
  }
});

// ============================================================================
// 5. CARGA Y RENDERIZADO DEL CATÁLOGO CON FOTOS
// ============================================================================
async function cargarMenuDesdeBackend() {
  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const res = await fetch(`/api/menu?negocio_id=${nid}`, {
      headers: { 'x-negocio-id': String(nid) }
    });
    const data = await res.json();
    estado.categorias = data.categorias || [];
    estado.productos = (data.productos || []).map(p => ({
      id: p.id,
      catId: Number(p.categoria_id),
      categoria_id: Number(p.categoria_id),
      codigo: p.codigo,
      cod: p.codigo,
      nombre: p.nombre,
      precio: p.precio,
      destino: p.destino,
      curso: p.curso || 2,
      total_vendidos: Number(p.total_vendidos) || 0,
      happyHour: Number(p.happy_hour) === 1 || p.happy_hour === true || p.happy_hour === '1',
      happy_hour: (Number(p.happy_hour) === 1 || p.happy_hour === true || p.happy_hour === '1') ? 1 : 0,
      agotado: Number(p.agotado) === 1 || p.agotado === true || p.agotado === '1',
      imagen_url: p.imagen_url,
      activo: (Number(p.activo) === 0 || p.activo === false || p.activo === '0') ? 0 : 1
    }));

    if (window.PosOfflineDB && estado.productos.length > 0) {
      window.PosOfflineDB.guardarCatalogo(estado.productos).catch(() => {});
    }

    renderCatalogoComandero();
  } catch (e) {
    if (window.PosOfflineDB) {
      try {
        const cached = await window.PosOfflineDB.obtenerCatalogo();
        if (cached && cached.length > 0) {
          estado.productos = cached;
          renderCatalogoComandero();
        }
      } catch (errDb) {}
    }
  }
}

window.categoriaActivaComandero = null; // null = Vista de Categorías Principal

function obtenerModoVistaMenuActual() {
  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const guardado = localStorage.getItem('pos_vista_menu_' + nid);
  if (guardado) return guardado;
  // Bistro y Grill La Terraza (negocio_id === 2) inicia en vista con fotos grandes ('large')
  return (Number(nid) === 2) ? 'large' : 'clasica';
}
window.obtenerModoVistaMenuActual = obtenerModoVistaMenuActual;

function cambiarModoVistaMenuComandero(modo) {
  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  localStorage.setItem('pos_vista_menu_' + nid, modo);

  const btnFotos = document.getElementById('btnMenuVistaFotos');
  const btnClasica = document.getElementById('btnMenuVistaClasica');
  if (btnFotos) btnFotos.classList.toggle('active', modo === 'large');
  if (btnClasica) btnClasica.classList.toggle('active', modo === 'clasica');

  filtrarProductosComandero();
}
window.cambiarModoVistaMenuComandero = cambiarModoVistaMenuComandero;

function renderCatalogoComandero() {
  const chipsContainer = document.getElementById('comCategoryChips');
  if (chipsContainer) {
    chipsContainer.innerHTML = `
      <button class="cat-chip ${window.categoriaActivaComandero === null ? 'active' : ''}" onclick="volverACategoriasComandero(this)">📂 Todas</button>
      ${(estado.categorias || []).map(c => `<button class="cat-chip ${window.categoriaActivaComandero === c.id ? 'active' : ''}" onclick="seleccionarCategoriaComandero(${c.id}, this)">${c.icono || '🍽️'} ${c.nombre}</button>`).join('')}
    `;
  }

  const modoVista = obtenerModoVistaMenuActual();
  const btnFotos = document.getElementById('btnMenuVistaFotos');
  const btnClasica = document.getElementById('btnMenuVistaClasica');
  if (btnFotos) btnFotos.classList.toggle('active', modoVista === 'large');
  if (btnClasica) btnClasica.classList.toggle('active', modoVista === 'clasica');

  const txtSearch = document.getElementById('txtBuscarProductoComandero');
  if (txtSearch) txtSearch.value = '';
  filtrarProductosComandero();
}

window.seleccionarCategoriaComandero = function(catId, elBtn) {
  window.categoriaActivaComandero = catId;
  document.querySelectorAll('.cat-chip').forEach(b => b.classList.remove('active'));
  if (elBtn) {
    elBtn.classList.add('active');
  } else {
    const chips = document.querySelectorAll('.cat-chip');
    chips.forEach(c => {
      if (c.getAttribute('onclick')?.includes(`seleccionarCategoriaComandero(${catId}`)) {
        c.classList.add('active');
      }
    });
  }
  const txtSearch = document.getElementById('txtBuscarProductoComandero');
  if (txtSearch) txtSearch.value = '';
  filtrarProductosComandero();
};

window.volverACategoriasComandero = function(elBtn) {
  window.categoriaActivaComandero = null;
  document.querySelectorAll('.cat-chip').forEach(b => b.classList.remove('active'));
  if (elBtn) {
    elBtn.classList.add('active');
  } else {
    const chips = document.querySelectorAll('.cat-chip');
    if (chips[0]) chips[0].classList.add('active');
  }
  const txtSearch = document.getElementById('txtBuscarProductoComandero');
  if (txtSearch) txtSearch.value = '';
  filtrarProductosComandero();
};

window.filtrarCatalogo = function(catId, elBtn) {
  if (catId === 'todos' || catId === 'categorias' || catId === null) {
    volverACategoriasComandero(elBtn);
  } else {
    seleccionarCategoriaComandero(catId, elBtn);
  }
};

window.filtrarProductosComandero = function() {
  const query = (document.getElementById('txtBuscarProductoComandero')?.value || '').toLowerCase().trim();
  const btnClear = document.getElementById('btnClearSearchComandero');
  if (btnClear) btnClear.style.display = query ? 'inline-block' : 'none';

  const modoVista = (typeof obtenerModoVistaMenuActual === 'function') ? obtenerModoVistaMenuActual() : 'clasica';

  // 1. Si hay búsqueda por texto libre: filtra sobre todo el menú
  if (query) {
    const palabras = query.split(/\s+/);
    const prods = (estado.productos || []).filter(p => {
      const matchTexto = `${p.nombre || ''} ${p.categoria || ''} ${p.codigo || ''} ${p.descripcion || ''}`.toLowerCase();
      return palabras.every(palabra => matchTexto.includes(palabra));
    });
    renderGridProductos(prods, true);
    return;
  }

  // 2. Si no hay búsqueda y no hay categoría seleccionada
  if (window.categoriaActivaComandero === null || window.categoriaActivaComandero === 'categorias') {
    if (modoVista === 'large') {
      // En vista de fotos grandes, mostrar todos los productos directamente con categorías arriba
      const prods = (estado.productos || []).slice().sort((a, b) => (Number(b.total_vendidos) || 0) - (Number(a.total_vendidos) || 0));
      renderGridProductos(prods, false, null);
      return;
    }
    renderGridCategorias();
    return;
  }

  // 3. Si hay categoría seleccionada -> Productos de esa categoría ordenados de más vendido a menos vendido
  const catId = window.categoriaActivaComandero;
  const prods = (estado.productos || [])
    .filter(p => p.catId === catId || p.categoria_id === catId)
    .sort((a, b) => (Number(b.total_vendidos) || 0) - (Number(a.total_vendidos) || 0));
  renderGridProductos(prods, false, catId);
};

window.limpiarBuscadorComandero = function() {
  const input = document.getElementById('txtBuscarProductoComandero');
  if (input) {
    input.value = '';
    input.focus();
  }
  filtrarProductosComandero();
};

function renderGridCategorias() {
  const grid = document.getElementById('comProductsGrid');
  if (!grid) return;
  grid.classList.remove('grid-view-large');
  grid.classList.add('categories-view');

  const cats = estado.categorias || [];
  const prods = estado.productos || [];
  const esAdminODev = estado.usuarioActual && (estado.usuarioActual.rol === 'admin' || estado.usuarioActual.rol === 'superadmin' || estado.usuarioActual.rol === 'developer' || estado.usuarioActual.rol === 'supervisor');

  const cardsHtml = cats.map(cat => {
    const totalEnCat = prods.filter(p => p.catId === cat.id || p.categoria_id === cat.id).length;
    const btnEditCat = esAdminODev
      ? `<button class="btn-cat-card-edit" onclick="event.stopPropagation(); abrirModalEditarCategoria(${cat.id});" title="Editar categoría ${escapeHtml(cat.nombre)}" style="background: rgba(56, 189, 248, 0.15); border: 1px solid #38bdf8; color: #38bdf8; width: 28px; height: 28px; border-radius: 6px; display: flex; align-items: center; justify-content: center; cursor: pointer; font-size: 0.8rem; margin-left: 6px; transition: all 0.15s;">✏️</button>`
      : '';
    const btnDelCat = esAdminODev
      ? `<button class="btn-cat-card-delete" onclick="event.stopPropagation(); confirmarEliminarCategoria(${cat.id});" title="Eliminar categoría ${escapeHtml(cat.nombre)}" style="background: rgba(239, 68, 68, 0.15); border: 1px solid #ef4444; color: #f87171; width: 28px; height: 28px; border-radius: 6px; display: flex; align-items: center; justify-content: center; cursor: pointer; font-size: 0.8rem; margin-left: 4px; transition: all 0.15s;">🗑️</button>`
      : '';
    return `
      <div class="com-cat-card" onclick="seleccionarCategoriaComandero(${cat.id})" title="Ver platillos de ${escapeHtml(cat.nombre)}" style="position: relative; display: flex; align-items: center; justify-content: space-between;">
        <div style="display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0;">
          <div class="com-cat-icon-badge">${cat.icono || '🍽️'}</div>
          <div class="com-cat-info" style="min-width: 0;">
            <h4 class="com-cat-title" style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${escapeHtml(cat.nombre)}</h4>
            <span class="com-cat-count">${totalEnCat} platillos / bebidas</span>
          </div>
        </div>
        <div style="display: flex; align-items: center; gap: 4px;">
          ${btnEditCat}
          ${btnDelCat}
          <span class="com-cat-arrow" style="margin-left: 4px;">➔</span>
        </div>
      </div>
    `;
  }).join('');

  const btnAddCatHtml = esAdminODev ? `
    <div class="com-cat-card com-cat-card-add" onclick="abrirModalNuevaCategoria()" title="Agregar nueva categoría al menú" style="border: 2px dashed rgba(56, 189, 248, 0.5); background: rgba(56, 189, 248, 0.08); cursor: pointer;">
      <div class="com-cat-icon-badge" style="background: rgba(56, 189, 248, 0.2); color: #38bdf8;">📂</div>
      <div class="com-cat-info">
        <h4 class="com-cat-title" style="color: #38bdf8;">+ Nueva Categoría</h4>
        <span class="com-cat-count">Crear sección del menú</span>
      </div>
    </div>
  ` : '';

  const btnAddHtml = esAdminODev ? `
    <div class="com-cat-card com-cat-card-add" onclick="abrirModalNuevoProducto()" title="Agregar nuevo producto y precio" style="border: 2px dashed rgba(16, 185, 129, 0.5); background: rgba(16, 185, 129, 0.08); cursor: pointer;">
      <div class="com-cat-icon-badge" style="background: rgba(16, 185, 129, 0.2); color: #10b981;">➕</div>
      <div class="com-cat-info">
        <h4 class="com-cat-title" style="color: #10b981;">+ Producto</h4>
        <span class="com-cat-count">Crear nuevo ítem y precio</span>
      </div>
    </div>
  ` : '';

  grid.innerHTML = cardsHtml + btnAddCatHtml + btnAddHtml;
}

function renderGridProductos(prods, isSearchMode = false, catId = null) {
  const grid = document.getElementById('comProductsGrid');
  if (!grid) return;
  grid.classList.remove('categories-view');

  const modoVista = (typeof obtenerModoVistaMenuActual === 'function') ? obtenerModoVistaMenuActual() : 'clasica';
  if (modoVista === 'large') {
    grid.classList.add('grid-view-large');
  } else {
    grid.classList.remove('grid-view-large');
  }

  const esAdminODev = estado.usuarioActual && (estado.usuarioActual.rol === 'admin' || estado.usuarioActual.rol === 'superadmin' || estado.usuarioActual.rol === 'developer' || estado.usuarioActual.rol === 'supervisor');

  let headerNavHtml = '';
  if (!isSearchMode && catId) {
    const cat = (estado.categorias || []).find(c => c.id === catId);
    const catNombre = cat ? `${cat.icono || '🍽️'} ${cat.nombre}` : 'Categoría';
    const btnDelCatHeader = esAdminODev
      ? `<button class="btn-eliminar-cat-nav" onclick="confirmarEliminarCategoria(${catId})" style="background: rgba(239, 68, 68, 0.18); border: 1px solid #ef4444; color: #fca5a5; padding: 4px 10px; border-radius: 8px; cursor: pointer; font-size: 0.8rem; font-weight: 700; display: flex; align-items: center; gap: 4px;" title="Eliminar esta categoría">🗑️ Eliminar Categoría</button>`
      : '';
    headerNavHtml = `
      <div class="com-cat-nav-bar" style="grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; background: #1e293b; padding: 6px 12px; border-radius: 10px; margin-bottom: 6px; border: 1px solid #334155; flex-wrap: wrap; gap: 8px;">
        <button class="btn-volver-categorias" onclick="volverACategoriasComandero()">
          ⬅️ Volver a Categorías
        </button>
        <strong style="color: #f8fafc; font-size: 0.92rem;">${escapeHtml(catNombre)} (${prods.length} productos)</strong>
        ${btnDelCatHeader}
      </div>
    `;
  } else if (isSearchMode) {
    headerNavHtml = `
      <div class="com-cat-nav-bar" style="grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; background: rgba(56, 189, 248, 0.12); padding: 6px 12px; border-radius: 10px; margin-bottom: 6px; border: 1px solid rgba(56, 189, 248, 0.3);">
        <span style="color: #38bdf8; font-size: 0.82rem; font-weight: 700;">🔍 Resultados de búsqueda (${prods.length} encontrados)</span>
        <button class="btn-volver-categorias" onclick="limpiarBuscadorComandero()" style="padding: 4px 10px; font-size: 0.8rem;">
          ✕ Limpiar búsqueda
        </button>
      </div>
    `;
  }

  let specialCardsHtml = '';
  let standardProds = [...prods];

  // Si estamos en Comidas Principales (catId === 1) y NO estamos en búsqueda libre:
  if (!isSearchMode && (catId === 1 || (catId && String(catId) === '1'))) {
    const casados = standardProds.filter(p => p.nombre.toLowerCase().includes('casado'));
    if (casados.length > 0) {
      specialCardsHtml += `
        <div class="prod-card-one-tap prod-card-special-group" onclick="abrirModalSeleccionCasado()" style="border: 2px solid #f59e0b; background: linear-gradient(145deg, #1e293b, #292524); position: relative;">
          <div class="prod-card-thumb-special" style="font-size: 2.2rem; margin-bottom: 6px; text-align: center;">🍽️</div>
          <div class="prod-card-content">
            <span class="prod-card-name" style="color: #fbbf24; font-weight: 800;">🍱 Casados Típicos</span>
            <span class="prod-card-price" style="color: #f59e0b;">${formatCRC(casados[0].precio)}</span>
            <small style="color: #94a3b8; font-size: 0.72rem; display: block; margin-top: 2px;">Elige tu carne favorita</small>
          </div>
        </div>
      `;
      standardProds = standardProds.filter(p => !p.nombre.toLowerCase().includes('casado'));
    }

    const arroces = standardProds.filter(p => p.nombre.toLowerCase().includes('arroz con') || p.nombre.toLowerCase().includes('arroz especial') || p.nombre.toLowerCase().includes('arroz cantones'));
    if (arroces.length > 0) {
      specialCardsHtml += `
        <div class="prod-card-one-tap prod-card-special-group" onclick="abrirModalSeleccionArroz()" style="border: 2px solid #38bdf8; background: linear-gradient(145deg, #1e293b, #172554); position: relative;">
          <div class="prod-card-thumb-special" style="font-size: 2.2rem; margin-bottom: 6px; text-align: center;">🍚</div>
          <div class="prod-card-content">
            <span class="prod-card-name" style="color: #38bdf8; font-weight: 800;">🍚 Arroces Especiales</span>
            <span class="prod-card-price" style="color: #60a5fa;">${formatCRC(arroces[0].precio)}</span>
            <small style="color: #94a3b8; font-size: 0.72rem; display: block; margin-top: 2px;">Elige tu especialidad</small>
          </div>
        </div>
      `;
      standardProds = standardProds.filter(p => !p.nombre.toLowerCase().includes('arroz con') && !p.nombre.toLowerCase().includes('arroz especial') && !p.nombre.toLowerCase().includes('arroz cantones'));
    }
  }

  const prodsHtml = standardProds.map(p => {
    const isAgotado = Number(p.agotado) === 1 || p.agotado === true || p.agotado === '1';
    const esCerveza = Boolean(Number(p.happyHour) === 1 || p.happyHour === true || Number(p.happy_hour) === 1 || p.happy_hour === true || p.catId === 4 || p.categoria_id === 4 || /imperial|pilsen|bavaria|corona|rock ice|cerveza/i.test(p.nombre || ''));
    const isPromo = estado.happyHourActivo && esCerveza;

    const cat = (estado.categorias || []).find(c => c.id === (p.catId || p.categoria_id));
    const catBadge = cat ? `${cat.icono || '🍽️'} ${cat.nombre}` : (p.categoria || 'Menú');

    let imgUrl = p.imagen_url;
    if (!imgUrl && estado.presetsFotos) {
      const matchPreset = estado.presetsFotos.find(pr => (p.nombre || '').toLowerCase().includes(pr.cat.toLowerCase()));
      if (matchPreset) imgUrl = matchPreset.url;
    }

    if (modoVista === 'large') {
      const imgLargeHtml = imgUrl 
        ? `<img class="prod-card-large-img" src="${imgUrl}" alt="${escapeHtml(p.nombre)}" loading="lazy" />`
        : `<div class="prod-card-large-no-img">${cat?.icono || '🍽️'}</div>`;

      const btnEditLargeHtml = esAdminODev
        ? `<button class="prod-card-large-edit" onclick="event.stopPropagation(); abrirModalEditarProducto(${p.id});" title="Editar producto y vincular al Kárdex">✏️</button>`
        : '';

      return `
        <div class="prod-card-large ${isAgotado ? 'agotado' : ''}" onclick="agregarAlTicketOneTap(${p.id})" title="${escapeHtml(p.nombre)} - ${formatCRC(p.precio)}">
          ${btnEditLargeHtml}
          <div class="prod-card-large-media">
            ${imgLargeHtml}
            
            <span class="prod-card-large-price">${formatCRC(p.precio)}</span>
            ${isPromo ? '<span class="prod-card-large-promo">🍸 2x1</span>' : ''}
          </div>
          <div class="prod-card-large-info">
            <h4 class="prod-card-large-name">${escapeHtml(p.nombre)}</h4>
          </div>
        </div>
      `;
    }

    // Modo clásico estándar
    const imgHtml = p.imagen_url 
      ? `<img class="prod-card-thumb" src="${p.imagen_url}" alt="${escapeHtml(p.nombre)}" loading="lazy" />`
      : `<div class="prod-card-no-thumb">${cat?.icono || '🍽️'}</div>`;

    const btnEditHtml = esAdminODev
      ? `<button class="btn-card-edit-prod" onclick="event.stopPropagation(); abrirModalEditarProducto(${p.id});" title="Editar producto y vincular al Kárdex">✏️</button>`
      : '';

    return `
      <div class="prod-card-one-tap ${isAgotado ? 'agotado' : ''}" onclick="agregarAlTicketOneTap(${p.id})" title="${escapeHtml(p.nombre)} - ${formatCRC(p.precio)}">
        ${btnEditHtml}
        ${imgHtml}
        ${isPromo ? '<span class="prod-badge-promo">🍸 2x1</span>' : ''}
        <div class="prod-card-content">
          <span class="prod-card-name">${escapeHtml(p.nombre)}</span>
          <span class="prod-card-price">${formatCRC(p.precio)}</span>
        </div>
      </div>
    `;
  }).join('');

  const btnAddHtml = esAdminODev ? (
    modoVista === 'large'
      ? `
        <div class="prod-card-large-add" onclick="abrirModalNuevoProducto()" title="Crear nuevo producto y precio">
          <span style="font-size: 2.5rem; color: #10b981; margin-bottom: 8px;">➕</span>
          <strong style="color: #f8fafc; font-size: 1.05rem;">Crear Producto</strong>
          <small style="color: #94a3b8; margin-top: 4px;">Nuevo ítem y precio</small>
        </div>
      `
      : `
        <div class="prod-card-one-tap" onclick="abrirModalNuevoProducto()" style="border: 2px dashed rgba(16, 185, 129, 0.45); background: rgba(16, 185, 129, 0.08); display: flex; flex-direction: column; align-items: center; justify-content: center; cursor: pointer; min-height: 100px; border-radius: 12px; transition: all 0.2s ease;" title="Agregar nuevo producto y precio">
          <span style="font-size: 1.6rem; margin-bottom: 4px;">➕</span>
          <span style="font-weight: 700; font-size: 0.85rem; color: #10b981; text-align: center;">+ Producto</span>
          <small style="color: #94a3b8; font-size: 0.72rem;">Nuevo precio</small>
        </div>
      `
  ) : '';

  grid.innerHTML = headerNavHtml + specialCardsHtml + prodsHtml + btnAddHtml;
}

