window.agregarNuevoComensal = async function() {
  if (!estado.comensalesMesa) estado.comensalesMesa = [];
  const num = estado.comensalesMesa.length + 1;
  const nombreDefault = `Persona ${num}`;
  const nombre = prompt('Ingresa el nombre de la persona / comensal:', nombreDefault);
  if (!nombre || !nombre.trim()) return;
  const nomLimpio = nombre.trim();
  if (!estado.comensalesMesa.includes(nomLimpio)) {
    estado.comensalesMesa.push(nomLimpio);
  }
  window.cambiarComensalActivo(nomLimpio);
};

window.cambiarComensalActivo = function(nombre) {
  estado.comensalActivo = nombre || 'General';
  window.renderComensalesTabs();
  if (estado.asistenteComensal && estado.asistenteComensal.activo) {
    const inp = document.getElementById('asistenteInputNombre');
    if (inp && nombre !== 'General') {
      inp.value = nombre;
      estado.asistenteComensal.comensalActual = nombre;
    }
  }
};

window.renderComensalesTabs = function() {
  const container = document.getElementById('comensalesTabsContainer');
  const banner = document.getElementById('bannerAsistenteComensal');
  if (!container) return;

  if (banner) {
    banner.style.display = (estado.asistenteComensal && estado.asistenteComensal.activo) ? 'block' : 'none';
  }

  // Recolectar todos los comensales presentes
  const comensalesSet = new Set();
  (estado.comensalesMesa || []).forEach(c => { if (c) comensalesSet.add(c); });
  if (estado.mesaActiva && estado.mesaActiva.items) {
    estado.mesaActiva.items.forEach(it => {
      if (it.comensal && it.comensal !== 'General') comensalesSet.add(it.comensal);
    });
  }
  if (estado.comensalActivo && estado.comensalActivo !== 'General') {
    comensalesSet.add(estado.comensalActivo);
  }

  const comensalesLista = Array.from(comensalesSet);
  const esMultiComensal = comensalesLista.length > 0 || (estado.asistenteComensal && estado.asistenteComensal.activo);

  if (!esMultiComensal) {
    container.style.display = 'none';
    container.innerHTML = '';
    return;
  }

  container.style.display = 'block';

  // Calcular subtotales por comensal
  const subtotales = {};
  if (estado.mesaActiva && estado.mesaActiva.items) {
    estado.mesaActiva.items.forEach(it => {
      const c = it.comensal || 'General';
      const tot = (it.precio || 0) * (it.cantidad || 1);
      subtotales[c] = (subtotales[c] || 0) + tot;
    });
  }

  const chipsHtml = [];

  // Chip General / Compartido
  const esGenActivo = (estado.comensalActivo === 'General' || !estado.comensalActivo);
  const actGen = esGenActivo ? 'active' : '';
  const subGenTxt = subtotales['General'] ? ` (${formatCRC(subtotales['General'])})` : '';
  const badgeGen = esGenActivo ? '<span class="chip-active-indicator">✓ SELECCIONADO</span>' : '';
  chipsHtml.push(`
    <button type="button" class="chip-comensal chip-general ${actGen}" onclick="cambiarComensalActivo('General')" title="Agregar pedidos para la cuenta compartida">
      👥 Compartido${subGenTxt} ${badgeGen}
    </button>
  `);

  // Chips individuales
  comensalesLista.forEach(nom => {
    const esActivo = (estado.comensalActivo === nom);
    const act = esActivo ? 'active' : '';
    const subTxt = subtotales[nom] ? ` (${formatCRC(subtotales[nom])})` : '';
    const safeNom = nom.replace(/'/g, "\\'");
    const badgeNom = esActivo ? '<span class="chip-active-indicator">✓ SELECCIONADO</span>' : '';
    const escNom = typeof escapeHtml === 'function' ? escapeHtml(nom) : nom;
    chipsHtml.push(`
      <button type="button" class="chip-comensal ${act}" onclick="cambiarComensalActivo('${safeNom}')" title="Agregar pedidos para ${escNom}">
        👤 ${escNom}${subTxt} ${badgeNom}
      </button>
    `);
  });

  // Botón + Agregar Persona
  chipsHtml.push(`
    <button type="button" class="chip-comensal chip-add" onclick="agregarNuevoComensal()" title="Añadir otra persona a la mesa">
      ➕ Agregar Persona
    </button>
  `);

  container.innerHTML = `
    <div class="comensales-tabs-bar">
      <div class="comensales-tabs-label">👤 Pedir para:</div>
      <div class="comensales-tabs-list">
        ${chipsHtml.join('')}
      </div>
    </div>
  `;
};

window.imprimirSubcuentaComensal = function(comensalNombre) {
  if (!estado.mesaActiva || !estado.mesaActiva.items) return;
  const mesa = estado.mesaActiva;
  const itemsComensal = mesa.items.filter(it => (it.comensal || 'General') === comensalNombre);
  
  if (itemsComensal.length === 0) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`No hay productos asignados a "${comensalNombre}"`, 'warning');
    } else {
      alert(`No hay productos asignados a "${comensalNombre}"`);
    }
    return;
  }

  const subtotal = itemsComensal.reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
  const tieneServicio10 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('servicio_10') : true;
  const tieneIVA13 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('desglose_iva_13') : true;
  const esParaLlevar = Boolean(mesa.es_para_llevar);
  const aplicaServicio = tieneServicio10 && !esParaLlevar;

  let base = subtotal, serv = 0, iva = 0, tot = subtotal;
  if (aplicaServicio && tieneIVA13) {
    base = Math.round(subtotal / 1.23);
    serv = Math.round(base * 0.10);
    iva = subtotal - base - serv;
  } else if (!aplicaServicio && tieneIVA13) {
    base = Math.round(subtotal / 1.13);
    serv = 0;
    iva = subtotal - base;
  } else if (aplicaServicio && !tieneIVA13) {
    base = Math.round(subtotal / 1.10);
    serv = subtotal - base;
    iva = 0;
  }

  const w = window.open('', '_blank', 'width=420,height=600');
  if (!w) {
    alert('Por favor habilita las ventanas emergentes (pop-ups) para imprimir la subcuenta.');
    return;
  }
  const negNom = estado.negocioActual?.nombre || 'GastroBar';
  const fecha = new Date().toLocaleString('es-CR');

  const itemsRows = itemsComensal.map(it => `
    <tr>
      <td style="text-align:left; padding:4px 0;">${it.cantidad}x ${it.nombre}</td>
      <td style="text-align:right; padding:4px 0;">${formatCRC(it.precio * it.cantidad)}</td>
    </tr>
  `).join('');

  w.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <title>Sub-cuenta - ${comensalNombre} - Mesa ${mesa.numero || mesa.id}</title>
      <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, monospace; font-size: 13px; margin: 15px; color: #111; }
        .center { text-align: center; }
        .bold { font-weight: bold; }
        .divider { border-top: 1px dashed #444; margin: 10px 0; }
        .double-divider { border-top: 2px solid #000; margin: 10px 0; }
        table { width: 100%; border-collapse: collapse; }
        .badge { display: inline-block; background: #e0e7ff; color: #3730a3; padding: 3px 8px; border-radius: 4px; font-weight: bold; }
      </style>
    </head>
    <body>
      <div class="center bold" style="font-size: 16px;">${negNom}</div>
      <div class="center" style="font-size:12px; color:#555;">*** PREFACTURA / SUB-CUENTA INDIVIDUAL ***</div>
      <div class="divider"></div>
      <div><strong>Mesa:</strong> ${mesa.numero || mesa.id}</div>
      <div><strong>Persona / Comensal:</strong> <span class="badge">👤 ${comensalNombre}</span></div>
      <div><strong>Fecha:</strong> ${fecha}</div>
      <div class="divider"></div>
      <table>
        <thead>
          <tr style="border-bottom: 1px solid #444;">
            <th style="text-align:left; padding-bottom:4px;">Cant / Platillo</th>
            <th style="text-align:right; padding-bottom:4px;">Monto</th>
          </tr>
        </thead>
        <tbody>
          ${itemsRows}
        </tbody>
      </table>
      <div class="divider"></div>
      <table>
        <tr><td>Subtotal Base:</td><td style="text-align:right;">${formatCRC(base)}</td></tr>
        ${serv > 0 ? `<tr><td>Servicio (10%):</td><td style="text-align:right;">${formatCRC(serv)}</td></tr>` : ''}
        ${iva > 0 ? `<tr><td>I.V.A (13%):</td><td style="text-align:right;">${formatCRC(iva)}</td></tr>` : ''}
      </table>
      <div class="double-divider"></div>
      <div style="font-size: 16px; font-weight: bold; display: flex; justify-content: space-between;">
        <span>TOTAL PERSONA:</span>
        <span>${formatCRC(tot)}</span>
      </div>
      <div class="divider"></div>
      <div class="center" style="font-size: 11px; color: #666;">
        Sub-cuenta individual de Mesa ${mesa.numero || mesa.id}<br>
        ¡Muchas gracias por su visita!
      </div>
      <script>
        window.onload = function() {
          window.print();
        };
      </script>
    </body>
    </html>
  `);
  w.document.close();
};

window.cobrarSubcuentaDirecta = function(comensalNombre) {
  if (!estado.mesaActiva || !estado.mesaActiva.items || !estado.mesaActiva.items.length) {
    mostrarNotificacionCentro('⚠️ No hay productos en la mesa activa para cobrar.', 'warning');
    return;
  }
  const mesa = estado.mesaActiva;
  const itemsComensal = mesa.items.filter(it => (it.comensal || 'General') === comensalNombre && !it.pagado);

  if (itemsComensal.length === 0) {
    mostrarNotificacionCentro(`⚠️ No hay productos pendientes de pago para "${comensalNombre}".`, 'warning');
    return;
  }

  const subtotal = itemsComensal.reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
  const tieneServicio10 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('servicio_10') : true;
  const tieneIVA13 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('desglose_iva_13') : true;
  const esParaLlevar = Boolean(mesa.es_para_llevar);
  const aplicaServicio = tieneServicio10 && !esParaLlevar;

  let base = subtotal, serv = 0, iva = 0, tot = subtotal;
  if (aplicaServicio && tieneIVA13) {
    base = Math.round(subtotal / 1.23);
    serv = Math.round(base * 0.10);
    iva = subtotal - base - serv;
  } else if (!aplicaServicio && tieneIVA13) {
    base = Math.round(subtotal / 1.13);
    serv = 0;
    iva = subtotal - base;
  } else if (aplicaServicio && !tieneIVA13) {
    base = Math.round(subtotal / 1.10);
    serv = subtotal - base;
    iva = 0;
  }

  if (typeof splitState === 'undefined' || !splitState) {
    window.splitState = { personas: [], itemsDisponibles: [], numPersonas: 1, personaActivaIndex: 0 };
  }

  // Detectar comensales con ítems pendientes
  const comensalesSet = new Set();
  (estado.comensalesMesa || []).forEach(c => { if (c) comensalesSet.add(c); });
  (mesa.items || []).forEach(it => {
    if (it.comensal && !it.pagado) comensalesSet.add(it.comensal);
  });
  if (!comensalesSet.has(comensalNombre)) comensalesSet.add(comensalNombre);
  const comensalesArray = Array.from(comensalesSet);

  splitState.personas = [];
  comensalesArray.forEach(nom => {
    const pItems = (mesa.items || []).filter(it => (it.comensal || 'General') === nom && !it.pagado);
    const pSub = pItems.reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
    let pBase = pSub, pServ = 0, pIva = 0, pTot = pSub;
    if (aplicaServicio && tieneIVA13) {
      pBase = Math.round(pSub / 1.23);
      pServ = Math.round(pBase * 0.10);
      pIva = pSub - pBase - pServ;
    } else if (!aplicaServicio && tieneIVA13) {
      pBase = Math.round(pSub / 1.13);
      pServ = 0;
      pIva = pSub - pBase;
    } else if (aplicaServicio && !tieneIVA13) {
      pBase = Math.round(pSub / 1.10);
      pServ = pSub - pBase;
      pIva = 0;
    }

    splitState.personas.push({
      id: nom,
      nombre: nom === 'General' ? 'Cuenta Compartida' : nom,
      items: pItems.map(it => ({ ...it })),
      subtotal: pBase,
      impuestos: pIva + pServ,
      total: pTot,
      guardada: true,
      pagada: false
    });
  });

  const targetIdx = splitState.personas.findIndex(p => p.id === comensalNombre || p.nombre === comensalNombre || (comensalNombre === 'General' && p.nombre === 'Cuenta Compartida'));
  estado.cobroSplitPersonaIndex = targetIdx !== -1 ? targetIdx : 0;
  estado.vinoDeSubcuentaDirecta = true;

  const lblTitulo = document.getElementById('lblTituloCobroModal');
  if (lblTitulo) lblTitulo.textContent = `💵 Cobro Factura - ${comensalNombre}`;
  const btnCobrar = document.getElementById('btnFinalizarCobro');
  if (btnCobrar) {
    btnCobrar.textContent = '✓ Cobrar y Emitir Factura';
    btnCobrar.className = 'btn-pri success';
    btnCobrar.onclick = window.ejecutarCobroFinal;
  }

  const mesaNom = mesa.numero || mesa.nombre || ('Mesa ' + mesa.id);
  const titEl = document.getElementById('cobroMesaTitulo');
  if (titEl) titEl.textContent = `${mesaNom} - 👤 ${comensalNombre}`;
  const dispEl = document.getElementById('cobroTotalDisplay');
  if (dispEl) dispEl.textContent = formatCRCSinDecimales(tot);
  const recEl = document.getElementById('txtEfectivoRecibido');
  if (recEl) recEl.value = '';
  const vuelEl = document.getElementById('cobroVueltoDisplay');
  if (vuelEl) vuelEl.textContent = '₡ 0';

  if (typeof inicializarPanelesCobroModal === 'function') {
    inicializarPanelesCobroModal(tot);
  }

  const mCobro = document.getElementById('modalCobro');
  if (mCobro) {
    mCobro.classList.add('active');
    mCobro.style.display = 'flex';
  }
};

function renderTicketItems() {
  const list = document.getElementById('comTicketItemsList');
  if (!estado.mesaActiva || !estado.mesaActiva.items || !estado.mesaActiva.items.length) {
    list.innerHTML = '<div style="text-align:center; color:#9ca3af; margin-top:40px;">Toca cualquier platillo con foto para agregarlo con 1 toque.</div>';
    recalcularTotalesTicket();
    actualizarBotonEnviarComanda();
    const mobCountEl = document.getElementById('mobTicketCount');
    if (mobCountEl) mobCountEl.textContent = 0;
    return;
  }

  // Detectar si hay comensales definidos o múltiples personas
  const comensalesSet = new Set();
  (estado.mesaActiva.items || []).forEach(it => {
    if (it.comensal) comensalesSet.add(it.comensal);
  });
  (estado.comensalesMesa || []).forEach(c => { if (c) comensalesSet.add(c); });

  const hayMultiplesComensales = comensalesSet.size > 1 || (comensalesSet.size === 1 && !comensalesSet.has('General')) || Boolean(estado.asistenteComensal && estado.asistenteComensal.activo);

  const cursoLabels = { 1: 'Bebida', 2: 'Entrada', 3: 'Plato Fuerte', 4: 'Postre', 5: 'Café', 6: 'Otros' };
  const cursoClasses = { 1: 'c-bebida', 2: 'c-entrada', 3: 'c-fuerte', 4: 'c-postre', 5: 'c-cafe', 6: 'c-otros' };

  const renderItemRow = (it, idx) => {
    const cursoBadge = `<span class="course-badge ${cursoClasses[it.curso] || 'c-fuerte'}">${cursoLabels[it.curso] || 'Fuerte'}</span>`;

    // Trazabilidad de mesa de origen para mesas unidas
    const origenBadge = (it.origen_mesa_numero && String(it.origen_mesa_numero) !== String(estado.mesaActiva.numero))
      ? `<span class="mesa-origin-badge" title="Producto originario de ${it.origen_mesa_numero}">[${it.origen_mesa_numero.toString().toLowerCase().includes('mesa') ? it.origen_mesa_numero : 'Mesa ' + it.origen_mesa_numero}]</span>`
      : '';

    const esCervezaPromo = Boolean(it.happyHour || it.categoria_id === 4 || it.catId === 4 || /imperial|pilsen|bavaria|corona|rock ice|cerveza/i.test(it.nombre || ''));
    const promoBadge = (Boolean(it.en_happy_hour) && esCervezaPromo)
      ? `<span class="hh-promo-badge">🍸 2x1</span>`
      : '';

    const estadoEnvioBadge = it.enviado 
      ? (it.offlinePendiente 
          ? '<small style="color:#f59e0b; font-weight:700; background:rgba(245,158,11,0.15); padding:1px 6px; border-radius:4px;">🟡 Guardado offline</small>' 
          : '<small style="color:#10b981;">✓ Enviado</small>')
      : '';

    const comensalTag = (it.comensal && it.comensal !== 'General' && !hayMultiplesComensales)
      ? `<span class="badge-comensal-tag">👤 ${it.comensal}</span>`
      : '';

    return `
      <div class="ticket-item-row">
        <div class="ticket-item-top">
          <span class="t-name">${origenBadge}${it.nombre} ${comensalTag} ${promoBadge} ${cursoBadge} ${estadoEnvioBadge}</span>
          <span class="t-price">${formatCRC(it.precio * it.cantidad)}</span>
        </div>
        ${it.notas ? `<div class="ticket-item-notes">⚠️ ${it.notas}</div>` : ''}
        <div class="ticket-item-actions">
          <div class="qty-pill">
            <button class="btn-qty" onclick="modificarCantidadTicket(${idx}, -1)">-</button>
            <strong style="min-width:24px; text-align:center;">${it.cantidad}</strong>
            <button class="btn-qty" onclick="modificarCantidadTicket(${idx}, 1)">+</button>
          </div>
          <div>
            <button class="btn-item-tool" onclick="abrirModalModificadores(${idx})">✏️ Notas/Tiempo</button>
            <button class="btn-item-tool" style="color:#ef4444;" onclick="solicitarAnulacionItem(${idx})">🗑️ Anular</button>
          </div>
        </div>
      </div>
    `;
  };

  if (!hayMultiplesComensales) {
    list.innerHTML = estado.mesaActiva.items.map((it, idx) => renderItemRow(it, idx)).join('');
  } else {
    // Agrupar items por comensal manteniendo indices reales en mesaActiva.items
    const grupos = {};
    estado.mesaActiva.items.forEach((it, idx) => {
      const c = it.comensal || 'General';
      if (!grupos[c]) grupos[c] = [];
      grupos[c].push({ it, idx });
    });

    const ordenComensales = [];
    (estado.comensalesMesa || []).forEach(c => {
      if (!ordenComensales.includes(c)) ordenComensales.push(c);
    });
    Object.keys(grupos).forEach(c => {
      if (!ordenComensales.includes(c)) ordenComensales.push(c);
    });

    let html = '';
    ordenComensales.forEach(comNom => {
      const itemsGrupo = grupos[comNom] || [];
      const subtotalGrupo = itemsGrupo.reduce((acc, obj) => acc + (obj.it.precio * obj.it.cantidad), 0);
      const tituloCom = (comNom === 'General') ? '👥 Compartido / General' : `👤 ${comNom}`;
      const comNomEscapado = comNom.replace(/'/g, "\\'");

      html += `
        <div class="ticket-comensal-grupo">
          <div class="ticket-comensal-header">
          <div class="ticket-comensal-header ${(comNom === 'General') ? 'compartido' : ''}">
            <div class="ticket-comensal-title">
              <span>${tituloCom}</span>
              <span class="comensal-title-name">${tituloCom}</span>
              <span class="badge-comensal-subtotal">${formatCRC(subtotalGrupo)}</span>
            </div>
            <div class="ticket-comensal-actions">
              <button type="button" class="btn-subcuenta-cobrar" onclick="imprimirSubcuentaComensal('${comNomEscapado}')" title="Prefactura / Sub-cuenta individual">🧾 Sub-cuenta</button>
              <button type="button" class="btn-subcuenta-pagar" onclick="cobrarSubcuentaDirecta('${comNomEscapado}')" title="Cobrar y liquidar directamente a esta persona">💵 Cobrar</button>
            </div>
          </div>
          <div class="ticket-comensal-items">
            ${itemsGrupo.length > 0 ? itemsGrupo.map(obj => renderItemRow(obj.it, obj.idx)).join('') : '<div style="font-size:12px; color:#9ca3af; padding:6px 10px;">Sin platillos aún para esta persona</div>'}
          </div>
        </div>
      `;
    });
    list.innerHTML = html;
  }

  recalcularTotalesTicket();
  actualizarBotonEnviarComanda();
  const mobCountEl = document.getElementById('mobTicketCount');
  const mobFloatCount = document.getElementById('mobFloatingCount');
  const mobFloatBar = document.getElementById('mobFloatingTicketBar');
  const totalQty = (estado.mesaActiva && estado.mesaActiva.items)
    ? estado.mesaActiva.items.reduce((acc, it) => acc + (it.cantidad || 1), 0)
    : 0;
  if (mobCountEl) mobCountEl.textContent = totalQty;
  if (mobFloatCount) mobFloatCount.textContent = totalQty;
  if (mobFloatBar) {
    const catCol = document.getElementById('comanderoCatalogCol');
    const isMenuVisible = !catCol || !catCol.classList.contains('mobile-hidden');
    mobFloatBar.style.display = (totalQty > 0 && isMenuVisible) ? 'flex' : 'none';
  }
}

window.modificarCantidadTicket = async function(idx, delta) {
  if (!estado.mesaActiva || !estado.mesaActiva.items) return;
  const item = estado.mesaActiva.items[idx];
  if (!item) return;
  const prodId = item.producto_id || item.id;

  if (delta > 0) {
    if (item.enviado) {
      // Si el producto ya fue guardado/enviado previamente, sumar 1 agrega una nueva unidad pendiente de guardar
      if (typeof window.agregarAlTicketOneTap === 'function' && prodId) {
        await window.agregarAlTicketOneTap(prodId);
        return;
      }
      // Fallback: agregar línea no enviada
      const nuevaLinea = {
        ...item,
        cantidad: delta,
        enviado: false,
        offlinePendiente: false,
        id_detalle_existente: null,
        creado_en: new Date().toISOString()
      };
      delete nuevaLinea.id_detalle;
      delete nuevaLinea.id_detalle_existente;
      estado.mesaActiva.items.push(nuevaLinea);
      renderTicketItems();
      actualizarBotonEnviarComanda();
      return;
    } else {
      item.cantidad += delta;
    }
  } else if (delta < 0) {
    if (item.enviado) {
      // Si ya está guardado/enviado, anular o reducir requiere PIN de supervisor
      solicitarAnulacionItem(idx);
      return;
    } else {
      item.cantidad += delta;
      if (item.cantidad <= 0) {
        estado.mesaActiva.items.splice(idx, 1);
      }
    }
  }

  renderTicketItems();
  actualizarBotonEnviarComanda();

  if (delta > 0 && typeof prodId === 'number') {
    await window.verificarOfertaBaldeCerveza(prodId, delta);
  }
};

function recalcularTotalesTicket() {
  if (!estado.mesaActiva || !estado.mesaActiva.items || !estado.mesaActiva.items.length) {
    document.getElementById('comSubtotal').textContent = '₡ 0.00';
    document.getElementById('comServicio').textContent = '₡ 0.00';
    document.getElementById('comIva').textContent = '₡ 0.00';
    document.getElementById('comTotal').textContent = '₡ 0.00';
    const hhRow = document.getElementById('comHappyHourRow');
    if (hhRow) hhRow.style.display = 'none';
    const cobroHH = document.getElementById('cobroHappyHourBadgeRow');
    if (cobroHH) cobroHH.style.display = 'none';
    const rowDescEsp = document.getElementById('rowDescuentoEspecial');
    if (rowDescEsp) rowDescEsp.style.display = 'none';
    return;
  }

  let sub = estado.mesaActiva.items.reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
  let descuentoHH = 0;
  const modoHH = estado.mesaActiva.modo_happy_hour || 'estricto';

  const grupos = {};
  let tieneBebidasPromo = false;

  estado.mesaActiva.items.forEach(it => {
    const esCervezaPromo = Boolean(
      it.happyHour ||
      it.en_happy_hour ||
      it.categoria_id === 4 ||
      it.catId === 4 ||
      /imperial|pilsen|bavaria|corona|rock ice|cerveza/i.test(it.nombre || '')
    );
    if (!esCervezaPromo) return;
    tieneBebidasPromo = true;

    const key = it.id || it.nombre;
    if (!grupos[key]) {
      grupos[key] = {
        precio: it.precio,
        cantHH: 0,
        cantNoHH: 0
      };
    }
    if (it.en_happy_hour) {
      grupos[key].cantHH += it.cantidad;
    } else {
      grupos[key].cantNoHH += it.cantidad;
    }
  });

  for (const key in grupos) {
    const g = grupos[key];
    if (modoHH === 'flexible') {
      const totalPares = Math.floor((g.cantHH + g.cantNoHH) / 2);
      const maxParesPosibles = Math.floor(g.cantHH / 2) + ((g.cantHH % 2 === 1 && g.cantNoHH > 0) ? 1 : 0);
      const pares = Math.min(totalPares, maxParesPosibles);
      descuentoHH += pares * g.precio;
    } else {
      const pares = Math.floor(g.cantHH / 2);
      descuentoHH += pares * g.precio;
    }
  }

  const descuentoEspecial = (estado.mesaActiva && estado.mesaActiva.descuento_monto) ? Number(estado.mesaActiva.descuento_monto) : 0;
  const rowDescEsp = document.getElementById('rowDescuentoEspecial');
  const lblDescEsp = document.getElementById('lblDescuentoEspecial');
  const comDescEsp = document.getElementById('comDescuentoEspecial');

  if (rowDescEsp) {
    if (descuentoEspecial > 0) {
      rowDescEsp.style.display = 'flex';
      if (lblDescEsp) {
        lblDescEsp.textContent = `🎁 Descuento Especial (${estado.mesaActiva.descuento_porcentaje || 0}%):`;
      }
      if (comDescEsp) {
        comDescEsp.textContent = '-' + formatCRC(descuentoEspecial);
      }
    } else {
      rowDescEsp.style.display = 'none';
    }
  }

  const totalBruto = sub;
  const esParaLlevar = Boolean(
    estado.mesaActiva && (
      estado.mesaActiva.es_para_llevar ||
      estado.mesaActiva.tipo_orden === 'para_llevar' ||
      String(estado.mesaActiva.id).startsWith('para_llevar') ||
      estado.mesaActiva.id === 'para_llevar'
    )
  );

  const tieneServicio10 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('servicio_10') : true;
  const tieneIVA13 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('desglose_iva_13') : true;
  const preciosConImpuestos = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('precios_con_impuestos') : true;

  const aplicaServicio = tieneServicio10 && !esParaLlevar;
  const aplicaIVA = tieneIVA13;

  let subtotalBase, servicio = 0, iva = 0, total = 0;

  if (preciosConImpuestos !== false) {
    // MODO A (Precios de menú con impuestos incluidos):
    // El total a pagar es directamente los productos menos descuentos
    total = Math.max(0, totalBruto - descuentoHH - descuentoEspecial);
    if (aplicaServicio && aplicaIVA) {
      subtotalBase = Math.round(total / 1.23);
      servicio = Math.round(subtotalBase * 0.10);
      iva = total - subtotalBase - servicio;
    } else if (!aplicaServicio && aplicaIVA) {
      subtotalBase = Math.round(total / 1.13);
      servicio = 0;
      iva = total - subtotalBase;
    } else if (aplicaServicio && !aplicaIVA) {
      subtotalBase = Math.round(total / 1.10);
      servicio = total - subtotalBase;
      iva = 0;
    } else {
      subtotalBase = Math.round(total);
      servicio = 0;
      iva = 0;
    }
  } else {
    // MODO B (Precios de menú sin impuestos: se suman al total):
    const baseNeta = Math.max(0, totalBruto - descuentoHH - descuentoEspecial);
    subtotalBase = baseNeta;
    servicio = aplicaServicio ? Math.round(baseNeta * 0.10) : 0;
    iva = aplicaIVA ? Math.round(baseNeta * 0.13) : 0;
    total = baseNeta + servicio + iva;
  }

  const rowServ = document.getElementById('rowComServicio');
  if (rowServ) {
    rowServ.style.display = (tieneServicio10 && !esParaLlevar) ? 'flex' : 'none';
  }
  const rowIva = document.getElementById('rowComIva');
  if (rowIva) {
    rowIva.style.display = tieneIVA13 ? 'flex' : 'none';
  }

  const lblServ = document.getElementById('lblComServicio');
  if (lblServ) {
    lblServ.textContent = 'Servicio Salón (10%):';
  }

  document.getElementById('comSubtotal').textContent = formatCRC(subtotalBase);

  const hhRow = document.getElementById('comHappyHourRow');
  const btnToggleHH = document.getElementById('btnToggleModoHHComandero');
  if (hhRow) {
    if (descuentoHH > 0 || tieneBebidasPromo) {
      hhRow.style.display = 'flex';
      document.getElementById('comHappyHourDesc').textContent = '-' + formatCRC(descuentoHH);
      if (btnToggleHH) {
        btnToggleHH.textContent = modoHH === 'flexible' ? '🤝 Flexible' : '🛡️ Estricto';
        btnToggleHH.title = `Modo 2x1 actual: ${modoHH}. Clic para alternar (Admin/Cajero).`;
      }
    } else {
      hhRow.style.display = 'none';
    }
  }

  // Sincronizar también con el modal de cobro si está activo
  const cobroBadgeRow = document.getElementById('cobroHappyHourBadgeRow');
  const cobroDescEl = document.getElementById('cobroHappyHourDesc');
  const btnCobroHH = document.getElementById('btnToggleModoHHCobro');
  if (cobroBadgeRow) {
    if (descuentoHH > 0 || tieneBebidasPromo) {
      cobroBadgeRow.style.display = 'flex';
      if (cobroDescEl) cobroDescEl.textContent = '-' + formatCRC(descuentoHH);
      if (btnCobroHH) btnCobroHH.textContent = modoHH === 'flexible' ? '🤝 Flexible' : '🛡️ Estricto';
    } else {
      cobroBadgeRow.style.display = 'none';
    }
  }

  document.getElementById('comServicio').textContent = formatCRC(servicio);
  document.getElementById('comIva').textContent = formatCRC(iva);
  document.getElementById('comTotal').textContent = formatCRC(total);
  const mobFloatTotal = document.getElementById('mobFloatingTotal');
  if (mobFloatTotal) mobFloatTotal.textContent = formatCRC(total);
}

window.toggleModoHappyHourActual = async function() {
  if (!estado.mesaActiva) return;
  const uAct = estado.usuarioActual || estado.usuario;
  const esAutorizado = Boolean(uAct && (uAct.rol === 'admin' || uAct.rol === 'developer' || uAct.rol === 'cajero'));
  if (!esAutorizado) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('🔒 Solo Administrador o Cajero pueden cambiar el modo Happy Hour', 'warning');
    } else {
      alert('🔒 Solo Administrador o Cajero pueden cambiar el modo Happy Hour');
    }
    return;
  }

  const actual = estado.mesaActiva.modo_happy_hour || 'estricto';
  const nuevoModo = actual === 'estricto' ? 'flexible' : 'estricto';
  estado.mesaActiva.modo_happy_hour = nuevoModo;

  if (estado.mesaActiva.orden_id) {
    try {
      const res = await fetch(`/api/ordenes/${estado.mesaActiva.orden_id}/modo-happy-hour`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'x-user-rol': uAct ? uAct.rol : 'admin'
        },
        body: JSON.stringify({ modo: nuevoModo })
      });
      const data = await res.json();
      if (!res.ok) {
        if (typeof mostrarNotificacionCentro === 'function') {
          mostrarNotificacionCentro('❌ ' + (data.error || 'Error al cambiar modo'), 'error');
        }
        estado.mesaActiva.modo_happy_hour = actual;
        return;
      }
    } catch (e) {
      console.warn('Error sincronizando modo Happy Hour con el servidor:', e);
    }
  }

  recalcularTotalesTicket();

  const elCobroTotal = document.getElementById('cobroTotalDisplay');
  const elComTotal = document.getElementById('comTotal');
  if (elCobroTotal && elComTotal) {
    elCobroTotal.textContent = elComTotal.textContent;
  }

  if (typeof mostrarNotificacionCentro === 'function') {
    mostrarNotificacionCentro(`🍸 Modo Happy Hour cambiado a: ${nuevoModo === 'flexible' ? 'Flexible 🤝 (Completa pares impares)' : 'Estricto 🛡️ (Solo horario HH)'}`, 'info');
  }
};

