// Solicitud y emisión de Pre-Factura / Pre-Cuenta
window.solicitarPreFacturaMesa = async function(mesaId = null, ordenId = null) {
  try {
    const mesaActiva = estado.mesaActiva;
    const mId = mesaId || (mesaActiva && mesaActiva.id);
    const oId = ordenId || (mesaActiva && (mesaActiva.orden_id || mesaActiva.ordenId || mesaActiva.orden_activa_id));

    const itemsMesa = (mesaActiva && mesaActiva.items && mesaActiva.items.length > 0)
      ? mesaActiva.items
      : ((estado.mesas || []).find(m => m.id === Number(mId))?.items || []);

    if (!mId && !oId && itemsMesa.length === 0) {
      if (typeof mostrarNotificacionCentro === 'function') {
        mostrarNotificacionCentro('⚠️ Por favor selecciona una mesa u orden activa para generar la pre-factura.', 'warning');
      } else {
        alert('Por favor selecciona una mesa u orden activa para generar la pre-factura.');
      }
      return;
    }

    if (itemsMesa.length === 0 && !oId) {
      if (typeof mostrarNotificacionCentro === 'function') {
        mostrarNotificacionCentro('⚠️ La mesa no tiene consumos registrados para generar pre-factura.', 'warning');
      } else {
        alert('La mesa no tiene consumos registrados para generar pre-factura.');
      }
      return;
    }

    const endpoint = oId ? `/api/ordenes/${oId}/prefactura` : (mId && !isNaN(Number(mId)) ? `/api/mesas/${mId}/prefactura` : null);
    const meseroActual = (estado.usuarioActual && estado.usuarioActual.nombre) || (estado.usuario && estado.usuario.nombre) || 'Personal de Turno';

    let ticketGenerado = null;

    if (endpoint) {
      try {
        const resp = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            mesero: meseroActual,
            items: itemsMesa
          })
        });
        const data = await resp.json().catch(() => null);
        if (resp.ok && data?.ok && data.ticket) {
          ticketGenerado = data.ticket;
        }
      } catch (errApi) {
        console.warn('Fallo al llamar endpoint de prefactura en backend, usando fallback local:', errApi);
      }
    }

    // Si no se obtuvo ticket desde backend o falló el endpoint, construir ticket fallback completo
    if (!ticketGenerado) {
      const subtotal = itemsMesa.reduce((acc, it) => acc + ((Number(it.precio || it.precio_unitario || 0)) * (Number(it.cantidad) || 1)), 0);
      const descHH = Number(mesaActiva?.descuento_happy_hour || 0);
      const descEsp = Number(mesaActiva?.descuento_monto || 0);
      const baseImp = Math.max(0, subtotal - descHH - descEsp);
      const tieneServ10 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('servicio_10') : true;
      const tieneIva13 = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('desglose_iva_13') : true;
      const iva = tieneIva13 ? Math.round(baseImp * 0.13) : 0;
      const servicio = tieneServ10 ? Math.round(baseImp * 0.10) : 0;
      const total = baseImp + iva + servicio;

      ticketGenerado = {
        tipo: 'prefactura',
        titulo: 'PRE-CUENTA / PRE-FACTURA',
        negocio: {
          nombre: estado.configuracion?.nombreComercio || 'GastroBar Fuego & Brasas',
          slogan: estado.configuracion?.slogan || 'Restaurante, Bar & Lounge',
          tel: estado.configuracion?.telefono || '2222-3344',
          dir: estado.configuracion?.direccion || 'San José, Costa Rica',
          cedula: estado.configuracion?.cedula || '3-101-789458'
        },
        ordenId: oId || mId || 1,
        numeroOrden: oId || mId || 1,
        mesa: (mesaActiva && mesaActiva.numero) ? (mesaActiva.numero.startsWith('Mesa') ? mesaActiva.numero : 'Mesa ' + mesaActiva.numero) : (mId ? ('Mesa ' + mId) : 'Mesa Principal'),
        mesero: meseroActual,
        cliente: (mesaActiva && (mesaActiva.cliente || mesaActiva.mesa_cliente)) || 'Cliente General',
        fechaHora: formatearFechaHoraCR(new Date()),
        items: itemsMesa.map(it => ({
          cantidad: Number(it.cantidad) || 1,
          nombre: it.nombre || it.nombre_producto || 'Producto',
          precioUnitario: Number(it.precio || it.precio_unitario || 0),
          totalLinea: Number(it.subtotal || it.totalLinea || ((it.precio || it.precio_unitario || 0) * (it.cantidad || 1))),
          notas: it.notas || ''
        })),
        subtotal,
        descuentoHH: descHH,
        descuentoMonto: descEsp,
        servicio,
        iva,
        total
      };
    }

    // SIEMPRE abrir el visor de ticket en pantalla Y despachar a impresión térmica
    if (typeof window.mostrarVisorTicketTermico === 'function') {
      window.mostrarVisorTicketTermico(ticketGenerado, true);
    } else if (typeof window.ejecutarImpresionDirectaTermica === 'function') {
      window.ejecutarImpresionDirectaTermica(ticketGenerado, false);
    }

    if (mId && typeof cargarMesasDesdeBackend === 'function') {
      cargarMesasDesdeBackend();
    }
  } catch (e) {
    console.error('Error al solicitar pre-factura:', e);
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('❌ Error al generar pre-factura: ' + e.message, 'error');
    }
  }
};

window.reimprimirComandaMesa = async function(mesaId = null) {
  try {
    const mesaActiva = estado.mesaActiva;
    const mId = mesaId || (mesaActiva && mesaActiva.id);
    if (!mId) {
      if (typeof mostrarNotificacionCentro === 'function') {
        mostrarNotificacionCentro('⚠️ Selecciona una mesa activa para reimprimir su comanda.', 'warning');
      }
      return;
    }
    const mesa = (estado.mesas || []).find(m => m.id === Number(mId)) || mesaActiva;
    const items = (mesa && mesa.items && mesa.items.length) ? mesa.items : (mesaActiva && mesaActiva.items);
    if (!items || !items.length) {
      if (typeof mostrarNotificacionCentro === 'function') {
        mostrarNotificacionCentro('⚠️ La mesa no tiene productos para imprimir comanda.', 'warning');
      }
      return;
    }
    // Separar items por destino para no imprimir comandas vacías ni mezclar barra y cocina
    const itemsCocina = items.filter(it => it.destino === 'cocina' || (!it.destino && it.categoria_id !== 4 && it.catId !== 4));
    const itemsBarra = items.filter(it => it.destino === 'barra' || it.categoria_id === 4 || it.catId === 4);

    let resFinal = null;
    if (itemsCocina.length > 0 && typeof window.ejecutarImpresionDirectaTermica === 'function') {
      const ticketCocina = {
        tipo: 'comanda',
        titulo: 'REIMPRESION COMANDA COCINA',
        destino: 'cocina',
        mesa: (mesa && mesa.numero) ? (mesa.numero.startsWith('Mesa') ? mesa.numero : 'Mesa ' + mesa.numero) : ('Mesa ' + mId),
        ordenId: (mesa && (mesa.orden_id || mesa.ordenId)) || 1,
        comandaNumero: 1,
        mesero: (estado.usuarioActual && estado.usuarioActual.nombre) || (mesa && mesa.mesero) || 'Personal de Turno',
        fechaHora: formatearFechaHoraCR(new Date()),
        items: itemsCocina.map(it => ({
          cantidad: it.cantidad || 1,
          nombre: it.nombre || it.nombre_producto || 'Producto',
          curso: it.curso || 2,
          destino: 'cocina',
          notas: it.notas || '',
          origenMesa: it.origen_mesa_numero || null
        }))
      };
      resFinal = await window.ejecutarImpresionDirectaTermica(ticketCocina, false);
    }

    if (itemsBarra.length > 0 && typeof window.ejecutarImpresionDirectaTermica === 'function') {
      const ticketBarra = {
        tipo: 'comanda',
        titulo: 'REIMPRESION COMANDA BARRA',
        destino: 'barra',
        mesa: (mesa && mesa.numero) ? (mesa.numero.startsWith('Mesa') ? mesa.numero : 'Mesa ' + mesa.numero) : ('Mesa ' + mId),
        ordenId: (mesa && (mesa.orden_id || mesa.ordenId)) || 1,
        comandaNumero: 1,
        mesero: (estado.usuarioActual && estado.usuarioActual.nombre) || (mesa && mesa.mesero) || 'Personal de Turno',
        fechaHora: formatearFechaHoraCR(new Date()),
        items: itemsBarra.map(it => ({
          cantidad: it.cantidad || 1,
          nombre: it.nombre || it.nombre_producto || 'Producto',
          curso: it.curso || 1,
          destino: 'barra',
          notas: it.notas || '',
          origenMesa: it.origen_mesa_numero || null
        }))
      };
      resFinal = await window.ejecutarImpresionDirectaTermica(ticketBarra, false);
    }
    return resFinal;
  } catch (e) {
    console.error('Error al reimprimir comanda:', e);
  }
};

