// Funciones para Pago Mixto
window.limpiarCamposMixto = function() {
  ['txtMixtoEfectivo', 'txtMixtoTarjeta', 'txtMixtoSinpe', 'txtMixtoUSD', 'txtMixtoTarjetaRef', 'txtMixtoSinpeRef'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const elUSDEquiv = document.getElementById('txtMixtoUSDEquiv');
  if (elUSDEquiv) elUSDEquiv.textContent = '₡ 0';
  calcularPagoMixto();
};

window.splitMixto5050 = function(tipo1, tipo2) {
  let totalCRC = parseCRC(document.getElementById('cobroTotalDisplay')?.textContent || '0');
  if (totalCRC <= 0 && estado.mesaActiva) {
    totalCRC = parseCRC(document.getElementById('comTotal')?.textContent || '0') || (estado.mesaActiva.total || estado.mesaActiva.orden_total || 0);
  }
  if (totalCRC <= 0) return;
  limpiarCamposMixto();
  const mitad1 = Math.ceil(totalCRC / 2);
  const mitad2 = totalCRC - mitad1;

  if (tipo1 === 'efectivo') {
    const el = document.getElementById('txtMixtoEfectivo');
    if (el) {
      el.value = mitad1;
      el.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }
  if (tipo2 === 'tarjeta') {
    const el = document.getElementById('txtMixtoTarjeta');
    if (el) {
      el.value = mitad2;
      el.dispatchEvent(new Event('input', { bubbles: true }));
    }
  } else if (tipo2 === 'sinpe') {
    const el = document.getElementById('txtMixtoSinpe');
    if (el) {
      el.value = mitad2;
      el.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }
  calcularPagoMixto();
};

function calcularPagoMixto() {
  let totalCRC = parseCRC(document.getElementById('cobroTotalDisplay')?.textContent || '0');
  if (totalCRC <= 0 && estado.mesaActiva) {
    totalCRC = parseCRC(document.getElementById('comTotal')?.textContent || '0') || (estado.mesaActiva.total || estado.mesaActiva.orden_total || 0);
  }

  const txtTC = document.getElementById('txtTipoCambioUSD');
  const tc = txtTC ? (parseFloat(txtTC.value) || 520) : 520;

  const mEfectivo = parseFloat(document.getElementById('txtMixtoEfectivo')?.value) || 0;
  const mTarjeta = parseFloat(document.getElementById('txtMixtoTarjeta')?.value) || 0;
  const mSinpe = parseFloat(document.getElementById('txtMixtoSinpe')?.value) || 0;
  const mUSD = (negocioAceptaDolares() && document.getElementById('txtMixtoUSD')) ? (parseFloat(document.getElementById('txtMixtoUSD').value) || 0) : 0;

  const mUSDEnCRC = Math.round(mUSD * tc);
  const elUSDEquiv = document.getElementById('txtMixtoUSDEquiv');
  if (elUSDEquiv) {
    elUSDEquiv.textContent = mUSD > 0 ? `Equiv: ${formatCRC(mUSDEnCRC)}` : '₡ 0';
  }

  const totalAsignado = mEfectivo + mTarjeta + mSinpe + mUSDEnCRC;
  const elAsig = document.getElementById('cobroMixtoAsignadoDisplay');
  if (elAsig) elAsig.textContent = formatCRC(totalAsignado);

  const elRestLbl = document.getElementById('cobroMixtoRestanteLabel');
  const elRestVal = document.getElementById('cobroMixtoRestanteDisplay');
  const badge = document.getElementById('cobroMixtoEstadoBadge');
  const hint = document.getElementById('cobroMixtoHint');

  const faltante = Math.max(0, totalCRC - totalAsignado);

  if (totalAsignado >= totalCRC && totalCRC > 0) {
    const vuelto = totalAsignado - totalCRC;
    if (vuelto > 0) {
      if (elRestLbl) elRestLbl.textContent = 'Vuelto / Cambio';
      if (elRestVal) {
        elRestVal.textContent = formatCRC(vuelto);
        elRestVal.style.color = '#34d399';
      }
      if (badge) {
        badge.textContent = `✅ Cubierto (Vuelto: ${formatCRC(vuelto)})`;
        badge.style.color = '#34d399';
      }
    } else {
      if (elRestLbl) elRestLbl.textContent = 'Restante';
      if (elRestVal) {
        elRestVal.textContent = '₡ 0';
        elRestVal.style.color = '#34d399';
      }
      if (badge) {
        badge.textContent = '✅ Total Cubierto';
        badge.style.color = '#34d399';
      }
    }
    if (hint) {
      hint.innerHTML = '🎉 <strong>¡Total completamente cubierto!</strong> Puedes presionar el botón verde <em>Liquidar, Imprimir & Liberar Mesa</em> abajo.';
      hint.style.color = '#34d399';
      hint.style.background = 'rgba(16,185,129,0.1)';
      hint.style.borderColor = 'rgba(16,185,129,0.3)';
    }
  } else {
    if (elRestLbl) elRestLbl.textContent = 'Falta por Cubrir';
    if (elRestVal) {
      elRestVal.textContent = formatCRC(faltante);
      elRestVal.style.color = totalAsignado > 0 ? '#f87171' : '#9ca3af';
    }
    if (badge) {
      if (totalAsignado > 0) {
        badge.textContent = `⚠️ Falta ${formatCRC(faltante)}`;
        badge.style.color = '#f87171';
      } else {
        badge.textContent = 'Pendiente';
        badge.style.color = '#fbbf24';
      }
    }
    if (hint) {
      if (totalAsignado > 0) {
        hint.innerHTML = `💡 Has asignado <strong>${formatCRC(totalAsignado)}</strong>. Falta <strong>${formatCRC(faltante)}</strong> por cubrir. Haz clic en <em>⚡ Cubrir Resto</em> en el método deseado.`;
        hint.style.color = '#fbbf24';
        hint.style.background = 'rgba(245,158,11,0.1)';
        hint.style.borderColor = 'rgba(245,158,11,0.3)';
      } else {
        hint.innerHTML = '💡 Digita el monto en un método o haz clic en <strong>⚡ Cubrir Resto</strong> para autoasignar el saldo.';
        hint.style.color = '#93c5fd';
        hint.style.background = 'rgba(59,130,246,0.1)';
        hint.style.borderColor = 'rgba(59,130,246,0.25)';
      }
    }
  }

  // Actualizar en tiempo real el texto y estilo de cada botón de cubrir
  actualizarBotonesFilasMixto(totalCRC, totalAsignado, faltante, tc);
}

function actualizarBotonesFilasMixto(totalCRC, totalAsignado, faltante, tc = 520) {
  const filas = [
    { id: 'txtMixtoEfectivo', btnId: 'btnCubrirMixtoEfectivo', tipo: 'efectivo', esUSD: false },
    { id: 'txtMixtoTarjeta', btnId: 'btnCubrirMixtoTarjeta', tipo: 'tarjeta', esUSD: false },
    { id: 'txtMixtoSinpe', btnId: 'btnCubrirMixtoSinpe', tipo: 'sinpe', esUSD: false }
  ];
  if (negocioAceptaDolares()) {
    filas.push({ id: 'txtMixtoUSD', btnId: 'btnCubrirMixtoUSD', tipo: 'usd', esUSD: true });
  }

  filas.forEach(f => {
    const inp = document.getElementById(f.id);
    const btn = document.getElementById(f.btnId);
    if (!btn || !inp) return;

    const val = parseFloat(inp.value) || 0;

    if (val > 0) {
      btn.innerHTML = `✓ ${f.esUSD ? '$ ' + val.toFixed(2) : formatCRC(val)}`;
      btn.title = `Monto asignado. Haz clic para limpiar este campo.`;
      btn.style.background = 'rgba(16,185,129,0.2)';
      btn.style.border = '1px solid #10b981';
      btn.style.color = '#34d399';
    } else {
      if (faltante > 0) {
        const textoFaltante = f.esUSD ? `$ ${(faltante / tc).toFixed(2)}` : formatCRC(faltante);
        btn.innerHTML = `⚡ Cubrir (${textoFaltante})`;
        btn.title = `Asignar los ${textoFaltante} restantes a este método`;
        btn.style.background = '#0284c7';
        btn.style.border = '1px solid #38bdf8';
        btn.style.color = '#ffffff';
      } else {
        btn.innerHTML = 'Cubrir';
        btn.title = 'Total ya cubierto';
        btn.style.background = '#1e293b';
        btn.style.border = '1px solid #475569';
        btn.style.color = '#94a3b8';
      }
    }
  });
}

['input', 'change', 'keyup'].forEach(ev => {
  document.querySelectorAll('.mixto-calc-trigger').forEach(inp => {
    inp.addEventListener(ev, calcularPagoMixto);
  });
});

window.autoAsignarRestanteMixto = function(tipo) {
  let totalCRC = parseCRC(document.getElementById('cobroTotalDisplay')?.textContent || '0');
  if (totalCRC <= 0 && estado.mesaActiva) {
    totalCRC = parseCRC(document.getElementById('comTotal')?.textContent || '0') || (estado.mesaActiva.total || estado.mesaActiva.orden_total || 0);
  }
  if (totalCRC <= 0) return;

  const txtTC = document.getElementById('txtTipoCambioUSD');
  const tc = txtTC ? (parseFloat(txtTC.value) || 520) : 520;

  const inputMap = {
    efectivo: document.getElementById('txtMixtoEfectivo'),
    tarjeta: document.getElementById('txtMixtoTarjeta'),
    sinpe: document.getElementById('txtMixtoSinpe'),
    usd: document.getElementById('txtMixtoUSD')
  };

  const targetInput = inputMap[tipo];
  if (!targetInput) return;

  const valActual = parseFloat(targetInput.value) || 0;

  // Si el usuario hace clic en un botón que YA tiene un valor asignado, lo limpia para permitir reescribir/reasignar
  if (valActual > 0) {
    targetInput.value = '';
    targetInput.dispatchEvent(new Event('input', { bubbles: true }));
    calcularPagoMixto();
    return;
  }

  // Calcular cuánto hay asignado en los OTROS campos
  const mEfec = tipo === 'efectivo' ? 0 : (parseFloat(inputMap.efectivo?.value) || 0);
  const mTarj = tipo === 'tarjeta' ? 0 : (parseFloat(inputMap.tarjeta?.value) || 0);
  const mSinpe = tipo === 'sinpe' ? 0 : (parseFloat(inputMap.sinpe?.value) || 0);
  const mUSD = tipo === 'usd' ? 0 : (parseFloat(inputMap.usd?.value) || 0);

  const yaAsignadoEnOtros = mEfec + mTarj + mSinpe + Math.round(mUSD * tc);
  const faltante = Math.max(0, totalCRC - yaAsignadoEnOtros);

  if (faltante > 0) {
    if (tipo === 'usd') {
      targetInput.value = +(faltante / tc).toFixed(2);
    } else {
      targetInput.value = faltante;
    }
    targetInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  calcularPagoMixto();
};

// Los botones de Pago Mixto utilizan handlers globales window.autoAsignarRestanteMixto, window.splitMixto5050 y window.limpiarCamposMixto

window.ejecutarCobroFinal = async function() {
  const btnFinalizar = document.getElementById('btnFinalizarCobro');
  if (!btnFinalizar || btnFinalizar.disabled) return;
  btnFinalizar.disabled = true;
  const textoOriginal = btnFinalizar.innerHTML;
  btnFinalizar.innerHTML = '⏳ Procesando Cobro...';

  try {
    const esCobroSplitPersona = (estado.cobroSplitPersonaIndex != null && splitState && splitState.personas && splitState.personas[estado.cobroSplitPersonaIndex]);
    let personaCobrada = null;
    let esLiquidacionFinal = true;

    let totalNum = 0;
    if (esCobroSplitPersona) {
      personaCobrada = splitState.personas[estado.cobroSplitPersonaIndex];
      personaCobrada.guardada = true;
      personaCobrada.pagada = true;
      totalNum = (personaCobrada.total && personaCobrada.total > 0)
        ? personaCobrada.total
        : parseCRC(document.getElementById('cobroTotalDisplay')?.textContent || '0');
    } else {
      totalNum = parseCRC(document.getElementById('cobroTotalDisplay')?.textContent || '0');
      if (totalNum <= 0 && estado.mesaActiva) {
        totalNum = parseCRC(document.getElementById('comTotal')?.textContent || '0') || (estado.mesaActiva.total || estado.mesaActiva.orden_total || 0);
      }
    }

    const metodoActivo = document.querySelector('.pay-method-tab.active');
    const metodoKey = metodoActivo ? (metodoActivo.dataset.method || 'Efectivo') : 'Efectivo';
    
    let metodoFinal = 'Efectivo';
    let recibido = totalNum;
    let cambio = 0;
    let referencia = null;
    let tipo_cambio = 1;
    let monto_usd = 0;
    let pagosArray = [];

    const txtTC = document.getElementById('txtTipoCambioUSD');
    const tcActual = txtTC ? (parseFloat(txtTC.value) || 520) : 520;

    if (metodoKey === 'Efectivo') {
      metodoFinal = 'Efectivo';
      const txtEf = document.getElementById('txtEfectivoRecibido')?.value;
      recibido = (txtEf && parseFloat(txtEf) > 0) ? parseFloat(txtEf) : totalNum;
      cambio = Math.max(0, recibido - totalNum);
    } else if (metodoKey === 'Tarjeta') {
      metodoFinal = 'Tarjeta';
      referencia = document.getElementById('txtTarjetaReferencia')?.value.trim() || null;
      recibido = totalNum;
      cambio = 0;
    } else if (metodoKey === 'SINPE') {
      metodoFinal = 'SINPE';
      referencia = document.getElementById('txtSinpeReferencia')?.value.trim() || null;
      recibido = totalNum;
      cambio = 0;
    } else if (metodoKey === 'Dolares') {
      metodoFinal = 'Dólares';
      tipo_cambio = tcActual;
      monto_usd = totalNum > 0 ? Number((totalNum / tcActual).toFixed(2)) : 0;
      const recUSD = parseFloat(document.getElementById('txtDolaresRecibidos')?.value) || monto_usd;
      recibido = Math.round(recUSD * tcActual);
      cambio = Math.max(0, recibido - totalNum);
    } else if (metodoKey === 'Mixto') {
      metodoFinal = 'Mixto';
      const mEfectivo = parseFloat(document.getElementById('txtMixtoEfectivo')?.value) || 0;
      const mTarjeta = parseFloat(document.getElementById('txtMixtoTarjeta')?.value) || 0;
      const mSinpe = parseFloat(document.getElementById('txtMixtoSinpe')?.value) || 0;
      const mUSD = parseFloat(document.getElementById('txtMixtoUSD')?.value) || 0;
      const refTarjeta = document.getElementById('txtMixtoTarjetaRef')?.value.trim() || null;
      const refSinpe = document.getElementById('txtMixtoSinpeRef')?.value.trim() || null;

      const mUSDEnCRC = Math.round(mUSD * tcActual);
      const totalAsignado = mEfectivo + mTarjeta + mSinpe + mUSDEnCRC;

      if (totalAsignado < totalNum && (totalNum - totalAsignado) > 1) {
        mostrarNotificacionCentro(`⚠️ El monto asignado (${formatCRC(totalAsignado)}) no cubre el total (${formatCRC(totalNum)}). Faltan: ${formatCRC(totalNum - totalAsignado)}`, 'warning');
        return;
      }

      if (mEfectivo > 0) pagosArray.push({ metodo: 'Efectivo', monto: mEfectivo });
      if (mTarjeta > 0) pagosArray.push({ metodo: 'Tarjeta', monto: mTarjeta, referencia: refTarjeta });
      if (mSinpe > 0) pagosArray.push({ metodo: 'SINPE', monto: mSinpe, referencia: refSinpe });
      if (mUSD > 0) pagosArray.push({ metodo: 'Dólares', monto: mUSDEnCRC, monto_usd: mUSD, tipo_cambio: tcActual });

      if (pagosArray.length === 0) {
        pagosArray.push({ metodo: 'Efectivo', monto: totalNum });
      }
      recibido = totalAsignado;
      cambio = Math.max(0, totalAsignado - totalNum);
    }

    const ordenId = estado.mesaActiva ? (estado.mesaActiva.orden_id || estado.mesaActiva.orden_activa_id) : null;
    const mesaNumero = estado.mesaActiva ? (estado.mesaActiva.numero || estado.mesaActiva.nombre || 'Mesa') : 'Mesa';

    if (esCobroSplitPersona) {
      personaCobrada.metodoPago = metodoFinal;
      personaCobrada.montoPagado = totalNum;
      personaCobrada.recibido = recibido;
      personaCobrada.cambio = cambio;
      personaCobrada.fechaPago = new Date().toISOString();

      if (!personaCobrada.items || personaCobrada.items.length === 0) {
        personaCobrada.items = [{
          nombre: `Cuota Equitativa (${personaCobrada.nombre})`,
          precio: Math.round(totalNum / 1.23),
          cantidad: 1,
          subtotal: Math.round(totalNum / 1.23)
        }];
      }

      // Descontar los productos pagados de estado.mesaActiva.items
      if (personaCobrada.items && estado.mesaActiva && estado.mesaActiva.items) {
        personaCobrada.items.forEach(pItem => {
          let restante = Number(pItem.cantidad) || 1;
          for (let i = 0; i < estado.mesaActiva.items.length; i++) {
            const mItem = estado.mesaActiva.items[i];
            const coincideComensal = !pItem.comensal || !mItem.comensal || mItem.comensal === pItem.comensal || mItem.comensal === personaCobrada.nombre;
            if (coincideComensal && (mItem.nombre === pItem.nombre || mItem.id === pItem.producto_id || mItem.producto_id === pItem.producto_id)) {
              if (mItem.cantidad <= restante) {
                restante -= mItem.cantidad;
                estado.mesaActiva.items.splice(i, 1);
                i--;
              } else {
                mItem.cantidad -= restante;
                mItem.subtotal = mItem.cantidad * mItem.precio;
                restante = 0;
              }
              if (restante <= 0) break;
            }
          }
        });

        // Asegurar que ningún ítem quede asignado al comensal pagado
        if (personaCobrada.nombre && personaCobrada.nombre !== 'General' && personaCobrada.nombre !== 'Cuenta Compartida') {
          estado.mesaActiva.items = (estado.mesaActiva.items || []).filter(it => it.comensal !== personaCobrada.nombre);
        }

        try {
          if (window.PosOfflineDB && estado.mesaActiva) {
            const remTot = estado.mesaActiva.items.reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
            if (typeof window.PosOfflineDB.guardarItemsMesa === 'function') {
              window.PosOfflineDB.guardarItemsMesa(estado.mesaActiva.id, estado.mesaActiva.items, remTot).catch(() => {});
            } else if (typeof window.PosOfflineDB.guardarOrdenMesa === 'function') {
              window.PosOfflineDB.guardarOrdenMesa(estado.mesaActiva.id, { total: remTot }, estado.mesaActiva.items).catch(() => {});
            }
          }
        } catch (_) {}
      }

      // Verificar si quedan productos o cuotas sin pagar en la mesa
      const quedanItemsEnMesaActiva = Boolean(estado.mesaActiva?.items && estado.mesaActiva.items.length > 0);
      const personasSinPagar = (splitState?.personas || []).filter(p => !p.pagada && ((p.items && p.items.length > 0) || (p.total && p.total > 0)));
      const itemsEnMesaSinAsignar = (splitState?.itemsDisponibles || []).filter(it => it.cantidad > 0);
      const hayPersonasSinPagar = (splitState?.personas || []).some(p => !p.pagada);

      esLiquidacionFinal = !quedanItemsEnMesaActiva && (personasSinPagar.length === 0 && itemsEnMesaSinAsignar.length === 0 && (!hayPersonasSinPagar || (estado.mesaActiva?.items?.length === 0)));
    }

    const mesaId = estado.mesaActiva ? estado.mesaActiva.id : null;
    const itemsMesa = (estado.mesaActiva && estado.mesaActiva.items) ? estado.mesaActiva.items : [];
    const idempotencyKey = 'pay_' + (mesaId || '0') + '_' + Date.now() + '_' + Math.floor(Math.random() * 10000);
    const esParaLlevarCobro = Boolean(
      estado.mesaActiva && (
        estado.mesaActiva.es_para_llevar ||
        estado.mesaActiva.tipo_orden === 'para_llevar' ||
        String(estado.mesaActiva.id).startsWith('para_llevar') ||
        estado.mesaActiva.id === 'para_llevar'
      )
    );

    const payloadCobro = {
      ordenId,
      mesaId,
      items: itemsMesa,
      metodo: metodoFinal,
      metodoPago: metodoFinal,
      monto: totalNum,
      recibido,
      cambio,
      referencia,
      tipo_cambio,
      monto_usd,
      pagos: pagosArray.length > 0 ? pagosArray : undefined,
      propina: Math.round(totalNum * 0.10),
      mesero: estado.usuarioActual ? estado.usuarioActual.nombre : (estado.usuario ? estado.usuario.nombre : 'Juan Jival'),
      liquidar_total: esLiquidacionFinal,
      items_pagados: personaCobrada ? personaCobrada.items : [],
      persona_nombre: personaCobrada ? personaCobrada.nombre : 'Cliente',
      happyHourActivo: Boolean(estado.happyHourActivo),
      enviar_cocina: Boolean(estado.enviarCocinaEnCobro),
      enviarCocina: Boolean(estado.enviarCocinaEnCobro),
      tipo_orden: esParaLlevarCobro ? 'para_llevar' : 'mesa',
      es_para_llevar: esParaLlevarCobro,
      idempotencyKey
    };

    const endpointCobro = ordenId ? `/api/ordenes/${ordenId}/cobrar` : '/api/ordenes/directo/cobrar';

    let cobroResData = null;
    try {
      if (window.PosOfflineSync) {
        const syncRes = await window.PosOfflineSync.ejecutarConRespaldo({
          tipo: 'COBRAR_ORDEN',
          endpoint: endpointCobro,
          metodo: 'POST',
          payload: payloadCobro,
          descripcion: `Cobro ${mesaNumero} (${formatCRC(totalNum)} - ${metodoFinal})`
        });
        cobroResData = (syncRes && syncRes.datos) ? syncRes.datos : syncRes;
      } else {
        const res = await fetch(endpointCobro, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payloadCobro)
        });
        if (res.ok) {
          cobroResData = await res.json().catch(() => null);
        }
      }
    } catch (errReq) {
      console.warn('Error al despachar petición de cobro:', errReq);
    }

    if (esCobroSplitPersona) {
      // 1. Construir e imprimir la Factura / Comprobante Individual de la persona
      const itemsFacturaPersona = (personaCobrada.items && personaCobrada.items.length > 0)
        ? personaCobrada.items.map(it => {
            const cant = Number(it.cantidad) || 1;
            const uPrice = Number(it.precio || it.precio_unitario || 0);
            const totalLinea = Number(it.subtotal || it.totalLinea || (uPrice * cant));
            return {
              cantidad: cant,
              nombre: it.nombre || it.nombre_producto || 'Consumo',
              precioUnitario: uPrice,
              totalLinea: totalLinea,
              notas: it.notas || ''
            };
          })
        : [{
            cantidad: 1,
            nombre: `Cuota Equitativa (${personaCobrada.nombre})`,
            precioUnitario: totalNum,
            totalLinea: totalNum,
            notas: ''
          }];

      const subPersona = esParaLlevarCobro ? Math.round(totalNum / 1.13) : Math.round(totalNum / 1.23);
      const servPersona = esParaLlevarCobro ? 0 : Math.round(subPersona * 0.10);
      const ivaPersona = totalNum - subPersona - servPersona;
      const saldoRestanteMesa = esLiquidacionFinal ? 0 : Math.max(0, (estado.mesaActiva?.items || []).reduce((a, b) => a + (b.precio * b.cantidad), 0));

      const ticketPersona = (cobroResData && cobroResData.ticket) ? cobroResData.ticket : {
        tipo: 'pago_parcial',
        titulo: `FACTURA / COMPROBANTE - ${personaCobrada.nombre.toUpperCase()}`,
        negocio: {
          nombre: estado.configuracion?.nombreComercio || 'GastroBar Fuego & Brasas',
          slogan: estado.configuracion?.slogan || 'Restaurante, Bar & Lounge',
          tel: estado.configuracion?.telefono || '2222-3344',
          dir: estado.configuracion?.direccion || 'San José, Costa Rica',
          cedula: estado.configuracion?.cedula || '3-101-789458'
        },
        numeroOrden: ordenId || 'ORD-1',
        ordenId: ordenId || 'ORD-1',
        mesa: mesaNumero,
        personaNombre: personaCobrada.nombre,
        cliente: personaCobrada.nombre,
        mesero: estado.usuarioActual ? estado.usuarioActual.nombre : (estado.usuario ? estado.usuario.nombre : 'General'),
        fechaHora: formatearFechaHoraCR(new Date()),
        items: itemsFacturaPersona,
        subtotal: subPersona,
        servicio: servPersona,
        iva: ivaPersona,
        impuestos: servPersona + ivaPersona,
        total: totalNum,
        metodoPago: metodoFinal,
        recibido: recibido,
        cambio: cambio,
        saldoRestanteMesa: saldoRestanteMesa
      };

      personaCobrada.ticket = ticketPersona;

      // Disparar despacho a impresora térmica ESC/POS
      if (cobroResData?.ok && cobroResData?.ticket) {
        if (typeof mostrarNotificacionCentro === 'function') {
          mostrarNotificacionCentro(`✅ 🖨️ ¡Comprobante de ${personaCobrada.nombre} impreso en impresora térmica (CAJA)!`, 'success');
        }
      } else if (typeof window.ejecutarImpresionDirectaTermica === 'function') {
        window.ejecutarImpresionDirectaTermica(ticketPersona, false);
      }

      // Cerrar modal de cobro de inmediato
      const mCobro = document.getElementById('modalCobro');
      if (mCobro) {
        mCobro.classList.remove('active');
        mCobro.style.display = 'none';
      }
      estado.cobroSplitPersonaIndex = null;

      if (esLiquidacionFinal) {
        // Todas las cuentas liquidadas: liberar mesa, limpiar comanda y volver al salón
        const mesaIdCerrada = estado.mesaActiva?.id;
        if (estado.mesaActiva) {
          try { if (window.PosOfflineDB && typeof window.PosOfflineDB.limpiarOrdenMesa === 'function' && estado.mesaActiva?.id) { window.PosOfflineDB.limpiarOrdenMesa(estado.mesaActiva.id).catch(() => {}); } } catch (_) {}
          estado.mesaActiva.estado = 'libre';
          estado.mesaActiva.cliente = null;
          estado.mesaActiva.mesa_cliente = null;
          estado.mesaActiva.items = [];
          estado.mesaActiva.platos_pendientes = [];
          estado.mesaActiva.items_pendientes = [];
          estado.mesaActiva.orden_id = null;
          estado.mesaActiva.orden_activa_id = null;
          estado.mesaActiva.orden_total = 0;
          estado.mesaActiva.pidio_cuenta_qr = 0;
          estado.mesaActiva.cuenta_pedida = false;
        }
        if (mesaIdCerrada) {
          const mesaEnLista = (estado.mesas || []).find(m => Number(m.id) === Number(mesaIdCerrada));
          if (mesaEnLista) {
            mesaEnLista.cliente = null;
            mesaEnLista.mesa_cliente = null;
            mesaEnLista.estado = 'libre';
            mesaEnLista.orden_total = 0;
            mesaEnLista.orden_activa_id = null;
            mesaEnLista.items = [];
            mesaEnLista.platos_pendientes = [];
            mesaEnLista.items_pendientes = [];
          }
        }

        // Limpiar comanda activa
        estado.mesaActiva = null;
        estado.comanda = [];
        estado.cobroSplitPersonaIndex = null;
        if (typeof splitState !== 'undefined') {
          splitState.personas = [];
          splitState.personaActivaIndex = 0;
        }
        const elNom = document.getElementById('comClienteNombre');
        if (elNom) elNom.textContent = 'General';
        const txtNotasComanda = document.getElementById('comandaNotasMesa');
        if (txtNotasComanda) txtNotasComanda.value = '';
        if (typeof renderTicketItems === 'function') renderTicketItems();
        if (typeof recalcularTotalesTicket === 'function') recalcularTotalesTicket();

        // Cerrar todos los modales (cobro, comandero, split)
        if (typeof window.cerrarTodosLosModales === 'function') {
          window.cerrarTodosLosModales();
        } else {
          document.querySelectorAll('.modal, .modal-backdrop').forEach(m => {
            m.classList.remove('active');
            m.style.display = 'none';
          });
        }

        // Navegar y activar la vista del Salón
        document.querySelectorAll('.nav-pill').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.pos-view').forEach(v => v.classList.remove('active'));
        const btnSalonNav = document.querySelector('.nav-pill[data-view="salon"]');
        if (btnSalonNav) btnSalonNav.classList.add('active');
        const viewSalonEl = document.getElementById('view-salon');
        if (viewSalonEl) viewSalonEl.classList.add('active');
        sessionStorage.setItem('pos_active_view', 'salon');
        localStorage.setItem('pos_active_view', 'salon');

        mostrarNotificacionCentro(`✅ ¡Cuenta de ${mesaNumero} liquidada con éxito! Mesa liberada.`, 'success');

        if (typeof cargarMesasDesdeBackend === 'function') await cargarMesasDesdeBackend();
        if (typeof cargarCajaDesdeBackend === 'function') cargarCajaDesdeBackend();
        if (typeof cargarKDSDesdeBackend === 'function') cargarKDSDesdeBackend();
      } else {
        // Quedan personas o productos pendientes
        const remMesaTot = (estado.mesaActiva?.items || []).reduce((acc, it) => acc + (it.precio * it.cantidad), 0);
        if (estado.mesaActiva) {
          estado.mesaActiva.total = remMesaTot;
          estado.mesaActiva.orden_total = remMesaTot;
          if (cobroResData?.saldo_restante !== undefined) {
            estado.mesaActiva.total = Number(cobroResData.saldo_restante);
            estado.mesaActiva.orden_total = Number(cobroResData.saldo_restante);
          }
        }

        // Actualizar comensales restantes que aún tengan ítems pendientes
        const comensalesRestantes = new Set((estado.mesaActiva?.items || []).map(it => it.comensal).filter(c => c && c !== 'General'));
        estado.comensalesMesa = Array.from(comensalesRestantes);
        if (estado.comensalActivo === personaCobrada.nombre || !comensalesRestantes.has(estado.comensalActivo)) {
          estado.comensalActivo = estado.comensalesMesa.length > 0 ? estado.comensalesMesa[0] : 'General';
        }

        // Actualizar mesa en lista de mesas del salón
        const mesaEnLista = (estado.mesas || []).find(m => Number(m.id) === Number(estado.mesaActiva?.id));
        if (mesaEnLista && estado.mesaActiva) {
          mesaEnLista.total = estado.mesaActiva.total;
          mesaEnLista.orden_total = estado.mesaActiva.orden_total;
          mesaEnLista.items = [...(estado.mesaActiva.items || [])];
        }

        // Si se usaba el modal de dividir cuenta, purgar a las personas pagadas
        if (typeof splitState !== 'undefined' && splitState && splitState.personas) {
          splitState.personas = splitState.personas.filter(p => !p.pagada);
          splitState.numPersonas = Math.max(1, splitState.personas.length);
          if (splitState.personaActivaIndex >= splitState.personas.length) {
            splitState.personaActivaIndex = Math.max(0, splitState.personas.length - 1);
          }
        }

        if (estado.vinoDeSubcuentaDirecta) {
          estado.vinoDeSubcuentaDirecta = false;
          if (typeof renderTicketItems === 'function') renderTicketItems();
          if (typeof recalcularTotalesTicket === 'function') recalcularTotalesTicket();
          if (typeof renderComensalesTabs === 'function') renderComensalesTabs();
          if (typeof renderSalón === 'function') renderSalón();
          if (typeof cargarMesasDesdeBackend === 'function') cargarMesasDesdeBackend();
          if (typeof cargarCajaDesdeBackend === 'function') cargarCajaDesdeBackend();

          const saldoTxt = estado.mesaActiva ? formatCRC(estado.mesaActiva.orden_total || estado.mesaActiva.total || 0) : '0';
          mostrarNotificacionCentro(`✅ ¡Sub-cuenta de ${personaCobrada.nombre} pagada con éxito! Mesa permanece abierta (Saldo restante: ${saldoTxt})`, 'success');
        } else {
          // Re-abrir split modal y refrescar la distribución de solo las personas pendientes
          if (typeof renderSplitDisponibles === 'function') renderSplitDisponibles();
          if (typeof renderSplitPersonaActiva === 'function') renderSplitPersonaActiva();
          if (typeof renderSplitColaPersonas === 'function') renderSplitColaPersonas();
          if (typeof calcularSplitIgual === 'function') calcularSplitIgual();
          if (typeof renderSalón === 'function') renderSalón();
          if (typeof cargarMesasDesdeBackend === 'function') cargarMesasDesdeBackend();

          const mSplit = document.getElementById('modalSplitBill');
          if (mSplit) {
            mSplit.classList.add('active');
            mSplit.style.display = 'flex';
          }
        }

        if (typeof renderComanda === 'function') {
          renderComanda();
        }
      }
    } else {
      // COBRO ESTÁNDAR COMPLETO DE MESA (NO SPLIT)
      const mesaIdCobrada = estado.mesaActiva?.id;
      if (estado.mesaActiva) {
        try { if (window.PosOfflineDB && typeof window.PosOfflineDB.limpiarOrdenMesa === 'function' && estado.mesaActiva?.id) { window.PosOfflineDB.limpiarOrdenMesa(estado.mesaActiva.id).catch(() => {}); } } catch (_) {}
        estado.mesaActiva.estado = 'libre';
        estado.mesaActiva.cliente = null;
        estado.mesaActiva.mesa_cliente = null;
        estado.mesaActiva.items = [];
        estado.mesaActiva.platos_pendientes = [];
        estado.mesaActiva.items_pendientes = [];
        estado.mesaActiva.orden_id = null;
        estado.mesaActiva.orden_activa_id = null;
        estado.mesaActiva.orden_total = 0;
        estado.mesaActiva.pidio_cuenta_qr = 0;
        estado.mesaActiva.cuenta_pedida = false;
      }
      if (mesaIdCobrada) {
        const mesaEnLista = (estado.mesas || []).find(m => Number(m.id) === Number(mesaIdCobrada));
        if (mesaEnLista) {
          mesaEnLista.cliente = null;
          mesaEnLista.mesa_cliente = null;
          mesaEnLista.estado = 'libre';
          mesaEnLista.orden_total = 0;
          mesaEnLista.orden_activa_id = null;
          mesaEnLista.items = [];
          mesaEnLista.platos_pendientes = [];
          mesaEnLista.items_pendientes = [];
        }
      }

      // Limpiar comanda activa
      estado.mesaActiva = null;
      estado.comanda = [];
      estado.cobroSplitPersonaIndex = null;
      if (typeof splitState !== 'undefined') {
        splitState.personas = [];
        splitState.personaActivaIndex = 0;
      }
      const elNom = document.getElementById('comClienteNombre');
      if (elNom) elNom.textContent = 'General';
      const txtNotasComanda = document.getElementById('comandaNotasMesa');
      if (txtNotasComanda) txtNotasComanda.value = '';
      if (typeof renderTicketItems === 'function') renderTicketItems();
      if (typeof recalcularTotalesTicket === 'function') recalcularTotalesTicket();

      // Cerrar todos los modales de cobro/comandero
      if (typeof window.cerrarTodosLosModales === 'function') {
        window.cerrarTodosLosModales();
      } else {
        document.querySelectorAll('.modal, .modal-backdrop').forEach(m => {
          m.classList.remove('active');
          m.style.display = 'none';
        });
      }

      // Navegar y activar la vista del Salón
      document.querySelectorAll('.nav-pill').forEach(b => b.classList.remove('active'));
      document.querySelectorAll('.pos-view').forEach(v => v.classList.remove('active'));
      const btnSalonNav = document.querySelector('.nav-pill[data-view="salon"]');
      if (btnSalonNav) btnSalonNav.classList.add('active');
      const viewSalonEl = document.getElementById('view-salon');
      if (viewSalonEl) viewSalonEl.classList.add('active');
      sessionStorage.setItem('pos_active_view', 'salon');
      localStorage.setItem('pos_active_view', 'salon');

      if (typeof cargarMesasDesdeBackend === 'function') {
        await cargarMesasDesdeBackend();
      }
      if (typeof cargarCajaDesdeBackend === 'function') {
        cargarCajaDesdeBackend();
      }
      if (typeof cargarKDSDesdeBackend === 'function') {
        cargarKDSDesdeBackend();
      }

      // Disparar automáticamente la impresión del tiquete final de cliente
      const tieneServ10Cobro = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('servicio_10') : true;
      const tieneIva13Cobro = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('desglose_iva_13') : true;
      const tienePreciosConImp = typeof negocioTieneCaracteristica === 'function' ? negocioTieneCaracteristica('precios_con_impuestos') : true;

      const aplicaServCobro = tieneServ10Cobro && !esParaLlevarCobro;
      const aplicaIvaCobro = tieneIva13Cobro;

      let subTicket, servTicket = 0, ivaTicket = 0;
      if (tienePreciosConImp !== false) {
        if (aplicaServCobro && aplicaIvaCobro) {
          subTicket = Math.round(totalNum / 1.23);
          servTicket = Math.round(subTicket * 0.10);
          ivaTicket = totalNum - subTicket - servTicket;
        } else if (!aplicaServCobro && aplicaIvaCobro) {
          subTicket = Math.round(totalNum / 1.13);
          servTicket = 0;
          ivaTicket = totalNum - subTicket;
        } else if (aplicaServCobro && !aplicaIvaCobro) {
          subTicket = Math.round(totalNum / 1.10);
          servTicket = totalNum - subTicket;
          ivaTicket = 0;
        } else {
          subTicket = totalNum;
          servTicket = 0;
          ivaTicket = 0;
        }
      } else {
        subTicket = Math.max(0, itemsMesa.reduce((acc, it) => acc + (Number(it.precio || it.precio_unitario || 0) * (Number(it.cantidad) || 1)), 0));
        servTicket = aplicaServCobro ? Math.round(subTicket * 0.10) : 0;
        ivaTicket = aplicaIvaCobro ? Math.round(subTicket * 0.13) : 0;
      }

      const txtDolInput = document.getElementById('txtDolaresRecibidos');
      const dolaresEntregados = (metodoFinal === 'Dolares' || metodoFinal === 'Dólares') ? (parseFloat(txtDolInput?.value) || 0) : 0;
      const tcParaTicket = parseFloat(localStorage.getItem('pos_tipo_cambio_usd')) || window._tipoCambioBCCR?.venta || estado.negocioActual?.tipo_cambio_usd || 520;
      const esDolaresCobro = Boolean(metodoFinal === 'Dolares' || metodoFinal === 'Dólares' || dolaresEntregados > 0);

      const ticketFinal = (cobroResData && cobroResData.ticket) ? cobroResData.ticket : {
        tipo: 'cuenta_total',
        titulo: 'COMPROBANTE DE PAGO / FACTURA',
        negocio: {
          nombre: estado.configuracion?.nombreComercio || 'GastroBar Fuego & Brasas',
          slogan: estado.configuracion?.slogan || 'Restaurante, Bar & Lounge',
          tel: estado.configuracion?.telefono || '2222-3344',
          dir: estado.configuracion?.direccion || 'San José, Costa Rica',
          cedula: estado.configuracion?.cedula || '3-101-789458'
        },
        numeroOrden: ordenId || 'ORD-1',
        ordenId: ordenId || 'ORD-1',
        mesa: mesaNumero,
        mesero: estado.usuarioActual ? estado.usuarioActual.nombre : (estado.usuario ? estado.usuario.nombre : 'General'),
        cliente: 'Cliente General',
        fechaHora: formatearFechaHoraCR(new Date()),
        items: itemsMesa.map(it => ({
          cantidad: Number(it.cantidad) || 1,
          nombre: it.nombre || it.nombre_producto || 'Producto',
          precioUnitario: Number(it.precio || it.precio_unitario) || 0,
          totalLinea: Number(it.subtotal || it.totalLinea || ((it.precio || it.precio_unitario || 0) * (it.cantidad || 1))),
          notas: it.notas || ''
        })),
        subtotal: subTicket,
        subtotalProductos: itemsMesa.reduce((acc, it) => acc + (Number(it.precio || it.precio_unitario || 0) * (Number(it.cantidad) || 1)), 0),
        descuento: (estado.mesaActiva && estado.mesaActiva.descuento_monto) ? Number(estado.mesaActiva.descuento_monto) : 0,
        descuentoMonto: (estado.mesaActiva && estado.mesaActiva.descuento_monto) ? Number(estado.mesaActiva.descuento_monto) : 0,
        descuentoPorcentaje: (estado.mesaActiva && estado.mesaActiva.descuento_porcentaje) ? Number(estado.mesaActiva.descuento_porcentaje) : 0,
        descuentoMotivo: (estado.mesaActiva && estado.mesaActiva.descuento_motivo) ? estado.mesaActiva.descuento_motivo : '',
        preciosConImpuestos: tienePreciosConImp,
        baseInformativa: (servTicket > 0 || ivaTicket > 0) ? Math.max(0, totalNum - servTicket - ivaTicket) : totalNum,
        servicio: servTicket,
        iva: ivaTicket,
        total: totalNum,
        metodoPago: esDolaresCobro ? 'Dólares' : metodoFinal,
        recibido: recibido,
        cambio: cambio,
        monto_usd: dolaresEntregados,
        tipo_cambio: tcParaTicket,
        esDolares: esDolaresCobro
      };

      if (esDolaresCobro && ticketFinal) {
        if (!ticketFinal.monto_usd && dolaresEntregados > 0) ticketFinal.monto_usd = dolaresEntregados;
        if (!ticketFinal.tipo_cambio) ticketFinal.tipo_cambio = tcParaTicket;
        ticketFinal.esDolares = true;
      }

      const tVisualFinal = (cobroResData && cobroResData.ticket) ? cobroResData.ticket : ticketFinal;
      if (tVisualFinal) {
        if (typeof window.mostrarVisorTicketTermico === 'function') {
          window.mostrarVisorTicketTermico(tVisualFinal, true);
        } else if (typeof window.ejecutarImpresionDirectaTermica === 'function') {
          window.ejecutarImpresionDirectaTermica(tVisualFinal, false);
        }
      }

      if (typeof mostrarNotificacionCentro === 'function') {
        mostrarNotificacionCentro(`✅ 🖨️ ¡Factura / Comprobante generado e impreso con éxito!`, 'success');
      }

      mostrarNotificacionCentro(`✅ ¡Cuenta de ${mesaNumero} liquidada con éxito! Mesa liberada.`, 'success');
    }

    await cargarMesasDesdeBackend();
    cargarCajaDesdeBackend();
  } catch (globalErr) {
    console.error('Error crítico en ejecución de cobro:', globalErr);
    mostrarNotificacionCentro('❌ Error al procesar el cobro: ' + globalErr.message, 'error');
  } finally {
    if (btnFinalizar) {
      btnFinalizar.disabled = false;
      btnFinalizar.innerHTML = textoOriginal;
    }
  }
};

const btnCobroElem = document.getElementById('btnFinalizarCobro');
if (btnCobroElem) {
  btnCobroElem.onclick = window.ejecutarCobroFinal;
}// Facturación Express
