window.cambiarSubTabInventario = function(tab) {
  window.subTabInventarioActiva = tab;
  try {
    sessionStorage.setItem('pos_inventario_subtab', tab);
    localStorage.setItem('pos_inventario_subtab', tab);
    sessionStorage.setItem('pos_active_view', 'inventario');
    localStorage.setItem('pos_active_view', 'inventario');
  } catch(e) {}
  document.querySelectorAll('.inv-subnav-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.inv-tab-panel').forEach(p => p.style.display = 'none');

  if (tab === 'existencias') {
    document.getElementById('tabBtnInvExistencias')?.classList.add('active');
    const panel = document.getElementById('invPanelExistencias');
    if (panel) panel.style.display = 'block';
  } else if (tab === 'recetas') {
    document.getElementById('tabBtnInvRecetas')?.classList.add('active');
    const panel = document.getElementById('invPanelRecetas');
    if (panel) panel.style.display = 'block';
    inicializarPanelRecetas();
  } else if (tab === 'kardex') {
    document.getElementById('tabBtnInvKardex')?.classList.add('active');
    const panel = document.getElementById('invPanelKardex');
    if (panel) panel.style.display = 'block';
    cargarKardexGeneral();
  } else if (tab === 'compras') {
    document.getElementById('tabBtnInvCompras')?.classList.add('active');
    const panel = document.getElementById('invPanelCompras');
    if (panel) panel.style.display = 'block';
    cargarSugerenciaCompras();
  } else if (tab === 'ventas') {
    document.getElementById('tabBtnInvVentas')?.classList.add('active');
    const panel = document.getElementById('invPanelVentas');
    if (panel) panel.style.display = 'block';
    inicializarModuloVentasInventario();
  }

  if (typeof window.actualizarVisibilidadBotonesPurgaDev === 'function') {
    window.actualizarVisibilidadBotonesPurgaDev();
  }
};

window.kardexMovimientosActuales = [];

window.cargarKardexGeneral = async function() {
  try {
    const rol = window.obtenerRolUsuarioActual ? window.obtenerRolUsuarioActual() : (estado.usuarioActual ? estado.usuarioActual.rol : 'admin');
    const insumoId = document.getElementById('selectFiltroKardexInsumo')?.value || 'todos';
    const tipo = document.getElementById('selectFiltroKardexTipo')?.value || 'todos';
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;

    // Mostrar / Ocultar botón de vaciar kardex para developer / superadmin
    const btnVaciar = document.getElementById('btnVaciarKardexDev');
    if (btnVaciar) {
      const esDev = (typeof window.esUsuarioDeveloperOSuperAdmin === 'function' && window.esUsuarioDeveloperOSuperAdmin()) ||
                    rol === 'developer' || rol === 'superadmin' || estado.usuarioActual?.es_developer;
      btnVaciar.style.display = esDev ? 'inline-flex' : 'none';
    }

    poblarSelectorKardexInsumos();

    const res = await fetch(`/api/admin/inventario/kardex/movimientos?insumo_id=${insumoId}&tipo=${tipo}&limit=250&negocio_id=${nid}`, {
      headers: {
        'x-user-rol': rol,
        'x-negocio-id': String(nid)
      }
    });
    if (!res.ok) throw new Error('Error al cargar historial Kárdex');
    const data = await res.json();
    window.kardexMovimientosActuales = data.movimientos || [];
    renderTablaKardexGeneral(window.kardexMovimientosActuales);
  } catch (e) {
    console.error('Error al cargar kardex general:', e);
    const tbody = document.getElementById('tbodyKardexGeneral');
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding:20px; color:#ef4444;">Error al cargar movimientos de Kárdex: ${escapeHtml(e.message)}</td></tr>`;
    }
  }
};

window.vaciarKardexCompletoDev = async function() {
  const u = estado.usuarioActual;
  const rol = window.obtenerRolUsuarioActual ? window.obtenerRolUsuarioActual() : (u ? u.rol : 'developer');
  const esDev = (typeof window.esUsuarioDeveloperOSuperAdmin === 'function' && window.esUsuarioDeveloperOSuperAdmin()) ||
                rol === 'developer' || rol === 'superadmin' || u?.es_developer;

  let pinSupervisor = '9999';
  if (!esDev) {
    const pin = await window.solicitarPinAdmin({
      icono: '🗑️',
      titulo: 'Vaciar Historial Kárdex (Developer)',
      subtitulo: 'Acción Destructiva de Auditoría',
      mensaje: 'Ingresa el PIN de Developer / Administrador para vaciar de forma irreversible todo el historial de Kárdex:'
    });
    if (!pin) return;
    pinSupervisor = pin;
  }

  const nombreNegocio = estado.negocioActual?.nombre || 'este comercio';
  const confirmar = confirm(`⚠️ ATENCIÓN DEVELOPER / SUPER ADMIN:\n\n¿Estás seguro de que deseas eliminar TODOS los movimientos del historial de Kárdex de "${nombreNegocio}"?\n\n• Se borrarán todos los registros de compras, ventas automáticas, mermas y ajustes.\n• Esta acción es irreversible.\n• El stock actual de los insumos en bodega se conservará intacto.\n\n¿Deseas continuar?`);
  if (!confirmar) return;

  const btnVaciar = document.getElementById('btnVaciarKardexDev');
  if (btnVaciar) {
    btnVaciar.disabled = true;
    btnVaciar.innerHTML = '<span>⏳</span> Vaciando Kárdex...';
  }

  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const res = await fetch(`/api/admin/inventario/kardex/vaciar?negocio_id=${nid}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-negocio-id': String(nid),
        'x-user-rol': rol,
        'x-supervisor-pin': pinSupervisor
      },
      body: JSON.stringify({
        negocio_id: nid,
        pin: pinSupervisor
      })
    });

    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Error al vaciar el historial de Kárdex');

    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`🗑️ ${data.mensaje || 'Historial de Kárdex vaciado exitosamente'}`, 'success');
    }

    await cargarKardexGeneral();
  } catch (e) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`❌ Error: ${e.message}`, 'error');
    }
  } finally {
    if (btnVaciar) {
      btnVaciar.disabled = false;
      btnVaciar.innerHTML = '<span>🗑️</span> Vaciar Historial (Dev)';
    }
  }
};

window.filtrarKardexGeneral = function() {
  cargarKardexGeneral();
};

function poblarSelectorKardexInsumos() {
  const sel = document.getElementById('selectFiltroKardexInsumo');
  if (!sel) return;
  const currentVal = sel.value || 'todos';
  const insumos = estado.inventario || [];
  sel.innerHTML = '<option value="todos">🔎 Todos los insumos y licores</option>' +
    insumos.map(i => `<option value="${i.id}">${escapeHtml(i.nombre)} (${escapeHtml(i.categoria || 'General')})</option>`).join('');
  sel.value = currentVal;
}

function renderTablaKardexGeneral(movimientos) {
  const tbody = document.getElementById('tbodyKardexGeneral');
  if (!tbody) return;
  tbody.innerHTML = '';

  if (!movimientos || !movimientos.length) {
    tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:28px; color:#9ca3af;">No se encontraron movimientos registrados en el Kárdex con los filtros seleccionados.</td></tr>';
    return;
  }

  movimientos.forEach(m => {
    const tr = document.createElement('tr');
    const badgeClass = m.tipo === 'venta' ? 'badge-kardex-venta' : m.tipo === 'entrada' ? 'badge-kardex-entrada' : m.tipo === 'merma' ? 'badge-kardex-merma' : 'badge-kardex-fijar';
    const tipoIcon = m.tipo === 'venta' ? '🛒 Venta' : m.tipo === 'entrada' ? '📥 Entrada' : m.tipo === 'merma' ? '⚠️ Merma' : '🔧 Ajuste';
    const signo = m.tipo === 'entrada' ? '+' : '-';
    const insNombre = m.insumo_nombre || `Insumo #${m.insumo_id}`;

    tr.innerHTML = `
      <td style="font-size:0.8rem; color:#94a3b8; white-space:nowrap;">${formatearFechaHoraCR(m.fecha_hora)}</td>
      <td>
        <strong>${escapeHtml(insNombre)}</strong>
        <small style="display:block; color:#9ca3af; font-size:0.75rem;">${escapeHtml(m.insumo_categoria || 'General')}</small>
      </td>
      <td><span class="${badgeClass}">${tipoIcon}</span></td>
      <td><strong>${signo}${m.cantidad}</strong> <small style="color:#94a3b8;">${escapeHtml(m.unidad_medida || '')}</small></td>
      <td><span style="color:#94a3b8;">${m.stock_previo ?? '-'}</span> → <strong style="color:#38bdf8;">${m.stock_nuevo ?? '-'}</strong></td>
      <td style="color:#34d399; font-weight:700;">${formatCRC(m.costo_total || 0)}</td>
      <td style="font-size:0.85rem;">${escapeHtml(m.motivo || '-')}</td>
      <td style="font-size:0.8rem; color:#9ca3af;">${escapeHtml(m.usuario_nombre || 'Sistema')}</td>
      <td style="text-align:center; white-space:nowrap;">
        <button class="btn-tool" style="padding:4px 9px; font-size:0.75rem; background:rgba(56,189,248,0.15); border:1px solid #38bdf8; color:#38bdf8; border-radius:6px; margin-right:4px; font-weight:600; cursor:pointer;" onclick="abrirModalEditarKardex(${m.id})" title="Modificar este movimiento">✏️ Editar</button>
        <button class="btn-tool" style="padding:4px 9px; font-size:0.75rem; background:rgba(239,68,68,0.15); border:1px solid #ef4444; color:#f87171; border-radius:6px; font-weight:600; cursor:pointer;" onclick="confirmarEliminarKardex(${m.id})" title="Eliminar este movimiento">🗑️</button>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

// --- GESTIÓN (EDITAR / ELIMINAR) KÁRDEX ---
window.kardexMovimientoAEliminar = null;

window.abrirModalEditarKardex = async function(movId) {
  const mov = (window.kardexMovimientosActuales || []).find(m => m.id === movId);
  if (!mov) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('⚠️ No se encontró la información del movimiento.', 'warning');
    }
    return;
  }

  // Verificar PIN si no es admin / supervisor
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'developer' || u.rol === 'supervisor');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '✏️',
      titulo: 'Modificar Kárdex',
      subtitulo: 'Autorización Requerida',
      mensaje: 'Ingresa el PIN de Administrador/Supervisor para modificar este movimiento:'
    });
    if (!pin) return;
    window._pinKardexActivo = pin;
  } else {
    window._pinKardexActivo = null;
  }

  document.getElementById('editKardexId').value = mov.id;
  document.getElementById('editKardexInsumoId').value = mov.insumo_id;
  const elInsumoNom = document.getElementById('editKardexInsumoNombre');
  if (elInsumoNom) {
    elInsumoNom.textContent = `${mov.insumo_nombre || `Insumo #${mov.insumo_id}`} • Categoría: ${mov.insumo_categoria || 'General'}`;
  }

  const selTipo = document.getElementById('editKardexTipo');
  if (selTipo) selTipo.value = mov.tipo || 'entrada';

  const inCant = document.getElementById('editKardexCantidad');
  if (inCant) inCant.value = mov.cantidad || 0;

  const inCosto = document.getElementById('editKardexCosto');
  if (inCosto) inCosto.value = mov.costo_total || 0;

  const inMotivo = document.getElementById('editKardexMotivo');
  if (inMotivo) inMotivo.value = mov.motivo || '';

  const inFecha = document.getElementById('editKardexFecha');
  if (inFecha) {
    if (mov.fecha_hora) {
      try {
        const d = new Date(mov.fecha_hora);
        const isoLocal = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
        inFecha.value = isoLocal;
      } catch (e) {
        inFecha.value = new Date().toISOString().slice(0, 16);
      }
    } else {
      inFecha.value = new Date().toISOString().slice(0, 16);
    }
  }

  const chkStock = document.getElementById('editKardexAjustarStock');
  if (chkStock) chkStock.checked = true;

  document.getElementById('modalEditarKardex')?.classList.add('active');
};

window.cerrarModalEditarKardex = function() {
  document.getElementById('modalEditarKardex')?.classList.remove('active');
};

window.guardarEdicionKardex = async function() {
  const movId = document.getElementById('editKardexId')?.value;
  if (!movId) return;

  const tipo = document.getElementById('editKardexTipo')?.value;
  const cantidad = parseFloat(document.getElementById('editKardexCantidad')?.value);
  const costo_total = parseFloat(document.getElementById('editKardexCosto')?.value) || 0;
  const motivo = document.getElementById('editKardexMotivo')?.value;
  const fecha_hora = document.getElementById('editKardexFecha')?.value;
  const ajustar_stock = document.getElementById('editKardexAjustarStock')?.checked;

  if (isNaN(cantidad) || cantidad < 0) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('⚠️ Ingrese una cantidad válida mayor o igual a 0.', 'warning');
    }
    return;
  }

  const userRol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
  const headers = {
    'Content-Type': 'application/json',
    'x-user-rol': userRol
  };
  if (window._pinKardexActivo) {
    headers['x-supervisor-pin'] = window._pinKardexActivo;
  }

  try {
    const res = await fetch(`/api/admin/inventario/kardex/movimientos/${movId}`, {
      method: 'PUT',
      headers,
      body: JSON.stringify({
        tipo,
        cantidad,
        costo_total,
        motivo,
        fecha_hora: fecha_hora ? new Date(fecha_hora).toISOString() : new Date().toISOString(),
        ajustar_stock
      })
    });

    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.error || 'Error al actualizar movimiento de Kárdex');
    }

    cerrarModalEditarKardex();
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('✅ Movimiento de Kárdex actualizado exitosamente.', 'success');
    }

    await cargarKardexGeneral();
    if (typeof cargarInventarioAdmin === 'function') {
      await cargarInventarioAdmin();
    }
  } catch (e) {
    console.error('Error al editar kardex:', e);
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`❌ ${e.message}`, 'error');
    }
  }
};

window.confirmarEliminarKardex = async function(movId) {
  const mov = (window.kardexMovimientosActuales || []).find(m => m.id === movId);
  if (!mov) return;

  // Verificar PIN si no es admin / supervisor
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'developer' || u.rol === 'supervisor');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '🗑️',
      titulo: 'Eliminar Registro Kárdex',
      subtitulo: 'Autorización Requerida',
      mensaje: 'Ingresa el PIN de Administrador/Supervisor para eliminar este movimiento de Kárdex:'
    });
    if (!pin) return;
    window._pinKardexActivo = pin;
  } else {
    window._pinKardexActivo = null;
  }

  window.kardexMovimientoAEliminar = mov;
  const elInfo = document.getElementById('deleteKardexInfo');
  if (elInfo) {
    const insNom = mov.insumo_nombre || `Insumo #${mov.insumo_id}`;
    elInfo.textContent = `${insNom} • ${mov.tipo.toUpperCase()} • Cantidad: ${mov.cantidad} ${mov.unidad_medida || ''}`;
  }

  document.getElementById('modalConfirmarEliminarKardex')?.classList.add('active');
};

window.cerrarModalEliminarKardex = function() {
  document.getElementById('modalConfirmarEliminarKardex')?.classList.remove('active');
  window.kardexMovimientoAEliminar = null;
};

window.ejecutarEliminarKardexConfirmado = async function(revertirStock) {
  if (!window.kardexMovimientoAEliminar) return;
  const movId = window.kardexMovimientoAEliminar.id;

  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const userRol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
  const headers = {
    'Content-Type': 'application/json',
    'x-user-rol': userRol,
    'x-negocio-id': String(nid)
  };
  if (window._pinKardexActivo) {
    headers['x-supervisor-pin'] = window._pinKardexActivo;
  }

  try {
    const res = await fetch(`/api/admin/inventario/kardex/movimientos/${movId}`, {
      method: 'DELETE',
      headers,
      body: JSON.stringify({ revertir_stock: revertirStock })
    });

    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.error || 'Error al eliminar movimiento de Kárdex');
    }

    cerrarModalEliminarKardex();
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(
        revertirStock
          ? '✅ Movimiento eliminado y stock en bodega revertido correctamente.'
          : '✅ Registro histórico de Kárdex eliminado.',
        'success'
      );
    }

    await cargarKardexGeneral();
    if (typeof cargarInventarioAdmin === 'function') {
      await cargarInventarioAdmin();
    }
  } catch (e) {
    console.error('Error al eliminar kardex:', e);
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`❌ ${e.message}`, 'error');
    }
  }
};

async function cargarInventarioAdmin() {
  try {
    const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const res = await fetch(`/api/admin/inventario?negocio_id=${nid}`, {
      headers: { 'x-user-rol': rol, 'x-negocio-id': String(nid) }
    });
    if (!res.ok) throw new Error('Error al consultar inventario');
    estado.inventario = await res.json();

    // Actualizar KPIs de Bodega
    let valorBodegaTotal = 0;
    let totalBajos = 0;
    let totalAgotados = 0;

    estado.inventario.forEach(i => {
      valorBodegaTotal += (i.stock_actual || 0) * (i.costo_unitario || 0);
      if (i.estado_stock === 'bajo') totalBajos++;
      if (i.estado_stock === 'agotado') totalAgotados++;
    });

    const elTotal = document.getElementById('kpiTotalInsumos');
    const elValor = document.getElementById('kpiValorBodega');
    const elBajo = document.getElementById('kpiStockBajo');
    const elAgotado = document.getElementById('kpiAgotados');

    if (elTotal) elTotal.textContent = estado.inventario.length;
    if (elValor) elValor.textContent = formatCRC(valorBodegaTotal);
    if (elBajo) elBajo.textContent = totalBajos;
    if (elAgotado) elAgotado.textContent = totalAgotados;

    // Llenar categorías en filtro
    const catSelect = document.getElementById('selectFiltroCatInventario');
    if (catSelect) {
      const categorias = [...new Set(estado.inventario.map(i => i.categoria))].filter(Boolean);
      catSelect.innerHTML = '<option value="todas">Todas las Categorías</option>';
      categorias.forEach(c => {
        catSelect.innerHTML += `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`;
      });
    }

    // Llenar select del modal de ajuste
    const ajusteSelect = document.getElementById('selectAjusteInsumo');
    if (ajusteSelect) {
      ajusteSelect.innerHTML = '';
      estado.inventario.forEach(i => {
        ajusteSelect.innerHTML += `<option value="${i.id}" data-unidad="${escapeHtml(i.unidad_medida)}">${escapeHtml(i.nombre)} (Stock: ${i.stock_actual} ${i.unidad_medida})</option>`;
      });
    }

    renderTablaInventario(estado.inventario);
    cargarSugerenciaComprasBadge();
  } catch (e) {
    console.error(e);
  }
}

function renderTablaInventario(items) {
  const tbody = document.getElementById('tbodyInventario');
  if (!tbody) return;
  tbody.innerHTML = '';

  if (!items.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:30px; color:#9ca3af;">No se encontraron insumos registrados.</td></tr>';
    return;
  }

  items.forEach(ins => {
    const tr = document.createElement('tr');
    const valorTotal = (ins.stock_actual || 0) * (ins.costo_unitario || 0);

    const iconoCat = typeof window.obtenerIconoCategoriaInsumo === 'function' ? window.obtenerIconoCategoriaInsumo(ins.categoria) : '📦';
    let nombreHtml = `<strong>${escapeHtml(ins.nombre)}</strong>`;
    let stockExtraHtml = '';
    let costoExtraHtml = '';

    const unidad = (ins.unidad_medida || 'unidades').toLowerCase();

    if (ins.es_licor) {
      if (unidad === 'kg' || unidad === 'kilogramos') {
        const pesoEmpaque = ins.capacidad_ml || 1000;
        const tamPorcion = ins.medida_shot_ml || 200;
        const rend = ins.rendimiento_shots || (tamPorcion > 0 ? Math.round((pesoEmpaque / tamPorcion) * 10) / 10 : 5);
        const totalPorciones = Math.round((ins.stock_actual || 0) * rend * 10) / 10;
        const costoPorcion = rend > 0 ? Math.round((ins.costo_unitario || 0) / rend) : 0;

        nombreHtml += ` <span class="licor-tag" style="background:#064e3b; border-color:#059669; color:#6ee7b7;">${iconoCat} ${pesoEmpaque}g (${rend} porc. de ${tamPorcion}g)</span>`;
        stockExtraHtml = `<span class="licor-shots-pill" style="background:#064e3b; border-color:#059669; color:#6ee7b7;">🍽️ ${totalPorciones} porciones</span>`;
        if (costoPorcion > 0) {
          costoExtraHtml = `<span style="display:block; font-size:0.75rem; color:#6ee7b7;">(${formatCRC(costoPorcion)}/porción)</span>`;
        }
      } else if (unidad === 'litros' || unidad === 'botellas' || (ins.categoria && ins.categoria.toLowerCase().includes('licor'))) {
        const cap = ins.capacidad_ml || 750;
        const rend = ins.rendimiento_shots || 25;
        nombreHtml += ` <span class="licor-tag">🍾 ${cap}ml (${rend} shots)</span>`;
        const enteras = ins.botellas_enteras !== null && ins.botellas_enteras !== undefined ? ins.botellas_enteras : Math.floor(ins.stock_actual || 0);
        const remanentes = ins.shots_remanentes !== null && ins.shots_remanentes !== undefined ? ins.shots_remanentes : Math.round(((ins.stock_actual || 0) - enteras) * rend);
        stockExtraHtml = `<span class="licor-shots-pill">🍸 ${enteras} bot. y ${remanentes} shots</span>`;
        if (ins.costo_por_shot || (rend > 0 && ins.costo_unitario)) {
          const cShot = ins.costo_por_shot || Math.round(ins.costo_unitario / rend);
          costoExtraHtml = `<span style="display:block; font-size:0.75rem; color:#a5b4fc;">(${formatCRC(cShot)}/shot)</span>`;
        }
      } else {
        const rend = ins.rendimiento_shots || 1;
        const totalPorc = Math.round((ins.stock_actual || 0) * rend * 10) / 10;
        const cPorc = rend > 0 ? Math.round((ins.costo_unitario || 0) / rend) : 0;
        nombreHtml += ` <span class="licor-tag" style="background:#1e1b4b; border-color:#4338ca; color:#c7d2fe;">🍽️ Rinde ${rend} porc./u</span>`;
        stockExtraHtml = `<span class="licor-shots-pill">🍽️ ${totalPorc} porciones</span>`;
        if (cPorc > 0) {
          costoExtraHtml = `<span style="display:block; font-size:0.75rem; color:#a5b4fc;">(${formatCRC(cPorc)}/porción)</span>`;
        }
      }
    }

    tr.innerHTML = `
      <td>${nombreHtml}</td>
      <td><span style="color:#e2e8f0; font-weight:500;">${iconoCat} ${escapeHtml(ins.categoria || 'General')}</span></td>
      <td>
        <strong>${ins.stock_actual}</strong> <small style="color:#9ca3af;">${escapeHtml(ins.unidad_medida)}</small>
        ${stockExtraHtml}
      </td>
      <td>${ins.stock_minimo} <small style="color:#9ca3af;">${escapeHtml(ins.unidad_medida)}</small></td>
      <td>
        ${formatCRC(ins.costo_unitario || 0)}
        ${costoExtraHtml}
      </td>
      <td style="color:#38bdf8; font-weight:700;">${formatCRC(valorTotal)}</td>
      <td>
        <span class="stock-pill ${ins.estado_stock}">
          ${ins.estado_stock === 'agotado' ? '⛔ Agotado' : ins.estado_stock === 'bajo' ? '⚠️ Bajo Stock' : ins.estado_stock === 'sin_stock' ? '⚪ Sin Stock' : '✅ Normal'}
        </span>
      </td>
      <td style="text-align:right; white-space:nowrap;">
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:#374151; border-color:#6b7280;" onclick="abrirModalEditarInsumo(${ins.id})" title="Editar Insumo">✏️</button>
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:#065f46; border-color:#10b981;" onclick="abrirModalAjusteRapido('entrada', ${ins.id})">+ Entrada</button>
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:#7f1d1d; border-color:#ef4444;" onclick="abrirModalAjusteRapido('merma', ${ins.id})">- Merma</button>
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:#1e293b; border-color:#475569;" onclick="abrirModalKardex(${ins.id})">📜 Kardex</button>
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:rgba(239,68,68,0.2); border-color:#ef4444; color:#f87171;" onclick="confirmarEliminarExistenciasBodega(${ins.id})" title="Vaciar / Eliminar existencias en bodega (Auditoría)">📦🗑️</button>
        <button class="btn-tool" style="padding:4px 8px; font-size:0.75rem; background:#991b1b; border-color:#ef4444;" onclick="confirmarEliminarInsumo(${ins.id})" title="Eliminar Insumo completo de Bodega">🗑️</button>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

function filtrarTablaInventario() {
  const q = (document.getElementById('txtBuscarInsumo')?.value || '').toLowerCase().trim();
  const cat = document.getElementById('selectFiltroCatInventario')?.value || 'todas';
  const est = document.getElementById('selectFiltroEstadoInventario')?.value || 'todos';

  const filtrados = (estado.inventario || []).filter(i => {
    const matchQ = !q || i.nombre.toLowerCase().includes(q) || (i.categoria && i.categoria.toLowerCase().includes(q));
    const matchCat = cat === 'todas' || i.categoria === cat;
    const matchEst = est === 'todos' || i.estado_stock === est;
    return matchQ && matchCat && matchEst;
  });

  renderTablaInventario(filtrados);
}
window.filtrarTablaInventario = filtrarTablaInventario;
window.abrirModuloInventario = function() {
  if (typeof window.abrirModuloAdmin === 'function') window.abrirModuloAdmin('inventario');
};

// Modales de Inventario
window.tipoAjusteActivo = 'entrada';

window.abrirModalAjusteRapido = async function(tipo = 'entrada', insumoId = null) {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'supervisor' || u.rol === 'developer');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '📦',
      titulo: 'Movimiento de Inventario',
      subtitulo: 'Acceso Restringido',
      mensaje: 'Ingresa el PIN de Administrador (1234) para realizar movimientos de stock:'
    });
    if (!pin) return;
    window._pinSupervisorActivo = pin;
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('👑 Movimiento de inventario autorizado con PIN', 'success');
    }
  }

  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const userRol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';

  // Asegurar inventario cargado en estado
  if (!estado.inventario || !estado.inventario.length) {
    try {
      const resInv = await fetch(`/api/admin/inventario?negocio_id=${nid}`, {
        headers: { 'x-user-rol': userRol, 'x-negocio-id': String(nid) }
      });
      if (resInv.ok) estado.inventario = await resInv.json();
    } catch(e) {}
  }

  // Limpiar buscador y asegurar que selectAjusteInsumo tenga opciones
  const txtSearch = document.getElementById('txtBuscarInsumoAjuste');
  if (txtSearch) txtSearch.value = '';
  const btnClear = document.getElementById('btnClearSearchAjuste');
  if (btnClear) btnClear.style.display = 'none';

  const ajusteSelect = document.getElementById('selectAjusteInsumo');
  if (ajusteSelect && estado.inventario && estado.inventario.length > 0) {
    ajusteSelect.innerHTML = estado.inventario.map(i => `
      <option value="${i.id}" data-unidad="${escapeHtml(i.unidad_medida)}" data-stock="${i.stock_actual}" data-cat="${escapeHtml(i.categoria || '')}">${escapeHtml(i.nombre)} (Stock: ${i.stock_actual} ${i.unidad_medida})</option>
    `).join('');
  }

  window.tipoAjusteActivo = tipo;
  window.seleccionarTipoAjuste(tipo);

  if (insumoId && ajusteSelect) {
    ajusteSelect.value = String(insumoId);
  }
  actualizarEtiquetaUnidadAjuste();

  const txtCant = document.getElementById('txtAjusteCantidad') || document.getElementById('txtCantidadAjuste');
  const txtMotivo = document.getElementById('txtAjusteMotivo') || document.getElementById('txtMotivoAjuste');
  if (txtCant) txtCant.value = '';
  if (txtMotivo) txtMotivo.value = '';

  const modal = document.getElementById('modalAjusteInventario');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
};

window.filtrarInsumosAjusteModal = function() {
  const input = document.getElementById('txtBuscarInsumoAjuste');
  const btnClear = document.getElementById('btnClearSearchAjuste');
  const sel = document.getElementById('selectAjusteInsumo');
  if (!sel) return;

  const q = (input?.value || '').toLowerCase().trim();
  if (btnClear) btnClear.style.display = q ? 'block' : 'none';

  const items = estado.inventario || [];
  const filtrados = items.filter(i => {
    if (!q) return true;
    const palabras = q.split(/\s+/);
    const texto = `${i.nombre || ''} ${i.categoria || ''} ${i.unidad_medida || ''}`.toLowerCase();
    return palabras.every(p => texto.includes(p));
  });

  if (filtrados.length > 0) {
    sel.innerHTML = filtrados.map(i => `
      <option value="${i.id}" data-unidad="${escapeHtml(i.unidad_medida)}" data-stock="${i.stock_actual}" data-cat="${escapeHtml(i.categoria || '')}">${escapeHtml(i.nombre)} (Stock: ${i.stock_actual} ${i.unidad_medida})</option>
    `).join('');
  } else {
    sel.innerHTML = '<option value="">⚠️ No se encontraron insumos coincidentes</option>';
  }

  actualizarEtiquetaUnidadAjuste();
};

window.limpiarBuscadorInsumoAjuste = function() {
  const input = document.getElementById('txtBuscarInsumoAjuste');
  if (input) {
    input.value = '';
    input.focus();
  }
  window.filtrarInsumosAjusteModal();
};

window.cerrarModalAjusteInventario = function() {
  const modal = document.getElementById('modalAjusteInventario');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
  window._pinSupervisorActivo = null;
};

window.seleccionarTipoAjuste = function(tipo) {
  window.tipoAjusteActivo = tipo;
  const btnEntrada = document.getElementById('btnAjusteTipoEntrada');
  const btnMerma = document.getElementById('btnAjusteTipoMerma');
  const lblCant = document.getElementById('lblAjusteCantidad');

  if (tipo === 'entrada') {
    if (btnEntrada) {
      btnEntrada.style.border = '1px solid #10b981';
      btnEntrada.style.background = 'rgba(16,185,129,0.2)';
      btnEntrada.style.color = '#34d399';
    }
    if (btnMerma) {
      btnMerma.style.border = '1px solid #374151';
      btnMerma.style.background = '#1f2937';
      btnMerma.style.color = '#9ca3af';
    }
    if (lblCant) lblCant.innerHTML = 'Cantidad a Ingresar (<span id="spanAjusteUnidad">unidades</span>):';
  } else {
    if (btnMerma) {
      btnMerma.style.border = '1px solid #ef4444';
      btnMerma.style.background = 'rgba(239,68,68,0.2)';
      btnMerma.style.color = '#f87171';
    }
    if (btnEntrada) {
      btnEntrada.style.border = '1px solid #374151';
      btnEntrada.style.background = '#1f2937';
      btnEntrada.style.color = '#9ca3af';
    }
    if (lblCant) lblCant.innerHTML = 'Cantidad a Descontar por Merma/Pérdida (<span id="spanAjusteUnidad">unidades</span>):';
  }
  actualizarEtiquetaUnidadAjuste();
};

function actualizarEtiquetaUnidadAjuste() {
  const sel = document.getElementById('selectAjusteInsumo');
  if (!sel || !sel.options || sel.selectedIndex < 0) return;
  const opt = sel.options[sel.selectedIndex];
  const u = opt ? opt.dataset.unidad || 'unidades' : 'unidades';
  const span = document.getElementById('spanAjusteUnidad');
  if (span) span.textContent = u;

  const stockInfo = document.getElementById('lblInsumoAjusteStockInfo');
  if (stockInfo) {
    const stock = opt ? opt.dataset.stock : null;
    const cat = opt ? opt.dataset.cat : null;
    if (stock !== null && stock !== undefined && opt.value) {
      stockInfo.textContent = `Stock actual: ${stock} ${u}${cat ? ` (${cat})` : ''}`;
    } else {
      stockInfo.textContent = '';
    }
  }
}
window.actualizarEtiquetaUnidadAjuste = actualizarEtiquetaUnidadAjuste;

document.getElementById('selectAjusteInsumo')?.addEventListener('change', actualizarEtiquetaUnidadAjuste);

window.guardarAjusteInventario = async function() {
  const selInsumo = document.getElementById('selectAjusteInsumo');
  const insumoId = selInsumo ? selInsumo.value : document.getElementById('txtInsumoAjusteId')?.value;
  const tipo = window.tipoAjusteActivo || 'entrada';
  const txtCant = document.getElementById('txtAjusteCantidad') || document.getElementById('txtCantidadAjuste');
  const cantidadStr = txtCant?.value?.trim();
  const cantidad = parseFloat(cantidadStr);
  const motivo = document.getElementById('txtAjusteMotivo')?.value?.trim() || 
                 document.getElementById('txtMotivoAjuste')?.value?.trim() || 
                 (tipo === 'entrada' ? 'Entrada de mercadería / compra' : 'Ajuste de merma / pérdida');
  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
  const usuarioNombre = estado.usuarioActual ? (estado.usuarioActual.nombre_completo || estado.usuarioActual.usuario || 'Administrador') : 'Administrador';

  if (!insumoId) {
    mostrarNotificacionCentro('⚠️ Por favor selecciona un insumo para ajustar', 'warning');
    return;
  }

  if (isNaN(cantidad) || cantidad <= 0) {
    if (txtCant) {
      txtCant.style.borderColor = '#ef4444';
      txtCant.style.boxShadow = '0 0 10px rgba(239, 68, 68, 0.5)';
      txtCant.focus();
      setTimeout(() => {
        txtCant.style.borderColor = '#374151';
        txtCant.style.boxShadow = 'none';
      }, 2500);
    }
    mostrarNotificacionCentro('⚠️ Ingresa una cantidad válida mayor a 0 para el ajuste', 'warning');
    return;
  }

  const btnConfirmar = document.getElementById('btnConfirmarAjusteInv');
  if (btnConfirmar) {
    btnConfirmar.disabled = true;
    btnConfirmar.innerHTML = '⏳ Aplicando...';
  }

  try {
    const headers = { 
      'Content-Type': 'application/json', 
      'x-user-rol': rol,
      'x-negocio-id': String(nid)
    };
    if (window._pinSupervisorActivo) {
      headers['x-supervisor-pin'] = window._pinSupervisorActivo;
    }

    const res = await fetch(`/api/admin/inventario/${insumoId}/ajuste`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ tipo, cantidad, motivo, usuarioNombre, negocio_id: nid })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Error al guardar ajuste');

    mostrarNotificacionCentro(`✅ Movimiento de inventario aplicado. Stock nuevo: ${data.nuevo_stock}`, 'success');
    if (typeof cerrarModalAjusteInventario === 'function') cerrarModalAjusteInventario();
    if (typeof cargarInventarioAdmin === 'function') await cargarInventarioAdmin();
    if (typeof cargarKardexGeneral === 'function') cargarKardexGeneral();
  } catch (e) {
    alert('❌ ' + e.message);
  } finally {
    if (btnConfirmar) {
      btnConfirmar.disabled = false;
      btnConfirmar.innerHTML = '💾 Aplicar Movimiento';
    }
  }
};

// MODAL NUEVO INSUMO
window.abrirModalNuevoInsumo = async function() {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'supervisor' || u.rol === 'developer');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '➕',
      titulo: 'Crear Insumo',
      subtitulo: 'Acceso Restringido',
      mensaje: 'Ingresa el PIN de Administrador (1234) para registrar un nuevo insumo:'
    });
    if (!pin) return;
    window._pinSupervisorActivo = pin;
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('👑 Registro de insumo autorizado con PIN', 'success');
    }
  }

  const txtNom = document.getElementById('txtNuevoInsumoNombre');
  const txtStock = document.getElementById('txtNuevoInsumoStock');
  const txtMin = document.getElementById('txtNuevoInsumoMin');
  const txtCosto = document.getElementById('txtNuevoInsumoCosto');
  const chkLicor = document.getElementById('chkNuevoInsumoEsLicor');
  const txtCatManual = document.getElementById('txtNuevoInsumoCatManual');
  const selCat = document.getElementById('selectNuevoInsumoCat');

  if (txtNom) txtNom.value = '';
  if (txtStock) txtStock.value = '10';
  if (txtMin) txtMin.value = '3';
  if (txtCosto) txtCosto.value = '1500';
  if (chkLicor) chkLicor.checked = false;
  if (txtCatManual) {
    txtCatManual.value = '';
    txtCatManual.style.display = 'none';
  }

  if (selCat) {
    const categorias = [...new Set((estado.inventario || []).map(i => i.categoria).filter(Boolean))];
    if (!categorias.includes('General')) categorias.unshift('General');
    if (!categorias.includes('Bebidas & Cervezas')) categorias.push('Bebidas & Cervezas');
    if (!categorias.includes('Licores & Destilados')) categorias.push('Licores & Destilados');
    if (!categorias.includes('Carnes')) categorias.push('Carnes');
    if (!categorias.includes('Abarrotes & Salsas')) categorias.push('Abarrotes & Salsas');

    selCat.innerHTML = categorias.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('') +
      '<option value="__otra__">➕ Otra categoría...</option>';
    selCat.value = 'General';
  }

  window.toggleConfigFraccionable('nuevo', false);
  window.onCambioUnidadInsumo('nuevo');

  const modal = document.getElementById('modalNuevoInsumo');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
};

window.cerrarModalNuevoInsumo = function() {
  const modal = document.getElementById('modalNuevoInsumo');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
  window._pinSupervisorActivo = null;
};

window.guardarNuevoInsumo = async function() {
  const nombre = document.getElementById('txtNuevoInsumoNombre')?.value?.trim();
  const selCat = document.getElementById('selectNuevoInsumoCat')?.value;
  const txtCatManual = document.getElementById('txtNuevoInsumoCatManual')?.value?.trim();
  const categoria = (selCat === '__otra__' ? txtCatManual : selCat) || 'General';
  let unidad_medida = document.getElementById('selectNuevoInsumoUnidad')?.value || 'unidades';
  const stock_actual = parseFloat(document.getElementById('txtNuevoInsumoStock')?.value) || 0;
  const stock_minimo = parseFloat(document.getElementById('txtNuevoInsumoMin')?.value) || 0;
  const costo_unitario = parseFloat(document.getElementById('txtNuevoInsumoCosto')?.value) || 0;
  let es_licor = document.getElementById('chkNuevoInsumoEsLicor')?.checked ? 1 : 0;

  if (!nombre) {
    mostrarNotificacionCentro('⚠️ Por favor ingresa el nombre del insumo', 'warning');
    const txtNom = document.getElementById('txtNuevoInsumoNombre');
    if (txtNom) txtNom.focus();
    return;
  }

  let capacidad_ml = null;
  let medida_shot_ml = null;

  if (unidad_medida === 'botellas_350') {
    unidad_medida = 'botellas';
    es_licor = 1;
    capacidad_ml = 355;
    medida_shot_ml = 355;
  } else if (unidad_medida === 'latas_350') {
    unidad_medida = 'unidades';
    es_licor = 1;
    capacidad_ml = 350;
    medida_shot_ml = 350;
  } else if (unidad_medida === 'latas_473') {
    unidad_medida = 'unidades';
    es_licor = 1;
    capacidad_ml = 473;
    medida_shot_ml = 473;
  } else if (unidad_medida === 'personalizada') {
    unidad_medida = 'unidades';
    es_licor = 1;
    capacidad_ml = 355;
    medida_shot_ml = 355;
  }

  if (es_licor) {
    const selCap = document.getElementById('selNuevoInsumoCapacidad')?.value;
    const txtCapCustom = parseFloat(document.getElementById('txtNuevoInsumoCapacidadCustom')?.value);
    if (selCap === 'custom') {
      capacidad_ml = txtCapCustom || capacidad_ml || 750;
    } else if (selCap) {
      capacidad_ml = parseFloat(selCap) || capacidad_ml || 750;
    }

    const selShot = document.getElementById('selNuevoInsumoMedidaShot')?.value;
    const txtShotCustom = parseFloat(document.getElementById('txtNuevoInsumoMedidaShotCustom')?.value);
    if (selShot === 'custom') {
      medida_shot_ml = txtShotCustom || medida_shot_ml || 30;
    } else if (selShot) {
      medida_shot_ml = parseFloat(selShot) || medida_shot_ml || 30;
    }
  }

  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
  const usuarioNombre = estado.usuarioActual ? (estado.usuarioActual.nombre_completo || estado.usuarioActual.usuario || 'Admin') : 'Admin';

  try {
    const headers = {
      'Content-Type': 'application/json',
      'x-user-rol': rol,
      'x-negocio-id': String(nid)
    };
    if (window._pinSupervisorActivo) {
      headers['x-supervisor-pin'] = window._pinSupervisorActivo;
    }

    const res = await fetch('/api/admin/inventario', {
      method: 'POST',
      headers,
      body: JSON.stringify({
        nombre,
        categoria,
        unidad_medida,
        stock_actual,
        stock_minimo,
        costo_unitario,
        es_licor,
        capacidad_ml,
        medida_shot_ml,
        negocio_id: nid,
        usuarioNombre
      })
    });

    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Error al crear insumo');

    mostrarNotificacionCentro(`✅ Insumo "${nombre}" registrado en bodega correctamente.`, 'success');
    window.cerrarModalNuevoInsumo();
    if (typeof cargarInventarioAdmin === 'function') await cargarInventarioAdmin();
  } catch (e) {
    alert('❌ ' + e.message);
  }
};

// MODAL EDITAR INSUMO
window.abrirModalEditarInsumo = async function(insumoId) {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'supervisor' || u.rol === 'developer');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '✏️',
      titulo: 'Editar Insumo',
      subtitulo: 'Acceso Restringido',
      mensaje: 'Ingresa el PIN de Administrador (1234) para editar el insumo:'
    });
    if (!pin) return;
    window._pinSupervisorActivo = pin;
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('👑 Edición de insumo autorizada con PIN', 'success');
    }
  }

  const ins = (estado.inventario || []).find(i => Number(i.id) === Number(insumoId));
  if (!ins) {
    mostrarNotificacionCentro('⚠️ Insumo no encontrado.', 'warning');
    return;
  }

  const elId = document.getElementById('txtEditarInsumoId');
  const elNom = document.getElementById('txtEditarInsumoNombre');
  const selCat = document.getElementById('selectEditarInsumoCat');
  const txtCatManual = document.getElementById('txtEditarInsumoCatManual');
  const selUni = document.getElementById('selectEditarInsumoUnidad');
  const elMin = document.getElementById('txtEditarInsumoMin');
  const elCos = document.getElementById('txtEditarInsumoCosto');
  const chkLicor = document.getElementById('chkEditarInsumoEsLicor');

  if (elId) elId.value = ins.id;
  if (elNom) elNom.value = ins.nombre || '';
  if (selUni) selUni.value = ins.unidad_medida || 'unidades';
  if (elMin) elMin.value = ins.stock_minimo !== undefined ? ins.stock_minimo : 5;
  if (elCos) elCos.value = ins.costo_unitario !== undefined ? ins.costo_unitario : 0;
  if (chkLicor) chkLicor.checked = Boolean(ins.es_licor);

  if (selCat) {
    const categorias = [...new Set((estado.inventario || []).map(i => i.categoria).filter(Boolean))];
    if (ins.categoria && !categorias.includes(ins.categoria)) categorias.unshift(ins.categoria);
    if (!categorias.includes('General')) categorias.unshift('General');
    selCat.innerHTML = categorias.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('') +
      '<option value="__otra__">➕ Otra categoría...</option>';
    selCat.value = ins.categoria || 'General';
  }
  if (txtCatManual) {
    txtCatManual.value = '';
    txtCatManual.style.display = 'none';
  }

  window.toggleConfigFraccionable('editar', Boolean(ins.es_licor));
  window.onCambioUnidadInsumo('editar');

  const modal = document.getElementById('modalEditarInsumo');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
};

window.cerrarModalEditarInsumo = function() {
  const modal = document.getElementById('modalEditarInsumo');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
  window._pinSupervisorActivo = null;
};

