// FRACCIONAMIENTO & CATEGORÍAS AUXILIARES
window.verificarCategoriaInsumoManual = function(modo) {
  const sel = document.getElementById(modo === 'nuevo' ? 'selectNuevoInsumoCat' : 'selectEditarInsumoCat');
  const txt = document.getElementById(modo === 'nuevo' ? 'txtNuevoInsumoCatManual' : 'txtEditarInsumoCatManual');
  if (!sel || !txt) return;
  if (sel.value === '__otra__') {
    txt.style.display = 'block';
    txt.focus();
  } else {
    txt.style.display = 'none';
  }
};

window.onCambioUnidadInsumo = function(modo) {
  const selUni = document.getElementById(modo === 'nuevo' ? 'selectNuevoInsumoUnidad' : 'selectEditarInsumoUnidad');
  const selCap = document.getElementById(modo === 'nuevo' ? 'selNuevoInsumoCapacidad' : 'selEditarInsumoCapacidad');
  const selShot = document.getElementById(modo === 'nuevo' ? 'selNuevoInsumoMedidaShot' : 'selEditarInsumoMedidaShot');
  const chkLicor = document.getElementById(modo === 'nuevo' ? 'chkNuevoInsumoEsLicor' : 'chkEditarInsumoEsLicor');
  if (!selUni || !selCap || !selShot) return;

  const u = selUni.value;
  if (u === 'botellas_350') {
    selCap.innerHTML = '<option value="355" selected>Botella Cerveza (355 ml / Estándar)</option><option value="350">Botella Cerveza (350 ml)</option><option value="330">Botella Cerveza (330 ml)</option><option value="custom">Personalizado (ml)</option>';
    selShot.innerHTML = '<option value="355" selected>1 Botella Completa (355 ml)</option><option value="350">1 Botella Completa (350 ml)</option><option value="177.5">1/2 Botella (Media)</option><option value="custom">Personalizado (ml)</option>';
    if (chkLicor && !chkLicor.checked) {
      chkLicor.checked = true;
      window.toggleConfigFraccionable(modo, true);
    }
  } else if (u === 'latas_350') {
    selCap.innerHTML = '<option value="350" selected>Lata Cerveza (350 ml)</option><option value="355">Lata Cerveza (355 ml)</option><option value="custom">Personalizado (ml)</option>';
    selShot.innerHTML = '<option value="350" selected>1 Lata Completa (350 ml)</option><option value="175">1/2 Lata (Media)</option><option value="custom">Personalizado (ml)</option>';
    if (chkLicor && !chkLicor.checked) {
      chkLicor.checked = true;
      window.toggleConfigFraccionable(modo, true);
    }
  } else if (u === 'latas_473') {
    selCap.innerHTML = '<option value="473" selected>Lata Grande (473 ml / 16 oz)</option><option value="500">Lata Medio Litro (500 ml)</option><option value="custom">Personalizado (ml)</option>';
    selShot.innerHTML = '<option value="473" selected>1 Lata Completa (473 ml)</option><option value="236.5">1/2 Lata (Media)</option><option value="custom">Personalizado (ml)</option>';
    if (chkLicor && !chkLicor.checked) {
      chkLicor.checked = true;
      window.toggleConfigFraccionable(modo, true);
    }
  } else if (u === 'personalizada') {
    selCap.innerHTML = '<option value="custom" selected>Personalizado (ml / oz / g)</option><option value="355">355 ml</option><option value="350">350 ml</option><option value="473">473 ml</option><option value="750">750 ml</option><option value="1000">1000 ml / 1 Kg</option>';
    selShot.innerHTML = '<option value="custom" selected>Personalizado</option><option value="355">355 ml (1 Unidad)</option><option value="350">350 ml</option><option value="473">473 ml</option><option value="30">30 ml (1 oz)</option>';
    if (chkLicor && !chkLicor.checked) {
      chkLicor.checked = true;
      window.toggleConfigFraccionable(modo, true);
    }
  } else if (u === 'kg') {
    selCap.innerHTML = '<option value="1000">1 Kg (1000 g)</option><option value="500">500 g (1/2 Kg)</option><option value="2000">2 Kg (2000 g)</option><option value="custom">Personalizado (g)</option>';
    selShot.innerHTML = '<option value="100">100 g (Porción)</option><option value="150">150 g (Carne/Pescado)</option><option value="200">200 g (Plato Fuerte)</option><option value="50">50 g (Guarnición)</option><option value="custom">Personalizado (g)</option>';
  } else if (u === 'litros') {
    selCap.innerHTML = '<option value="1000">1 Litro (1000 ml)</option><option value="2000">2 Litros</option><option value="3000">3 Litros</option><option value="custom">Personalizado (ml)</option>';
    selShot.innerHTML = '<option value="250">250 ml (1 Vaso)</option><option value="350">350 ml (Lata)</option><option value="500">500 ml (Medio Litro)</option><option value="50">50 ml (Chupito)</option><option value="custom">Personalizado (ml)</option>';
  } else {
    selCap.innerHTML = '<option value="750">Botella Estándar (750 ml)</option><option value="1000">Botella Litro (1000 ml)</option><option value="350">Media Botella (350 ml)</option><option value="1750">Magnum (1750 ml)</option><option value="custom">Personalizado (ml)</option>';
    selShot.innerHTML = '<option value="30">1 Shot Estándar (30 ml / 1 oz)</option><option value="45">1.5 oz (45 ml / Trago)</option><option value="60">2 oz (60 ml / Doble)</option><option value="custom">Personalizado (ml)</option>';
  }

  window.actualizarCalculoFraccionable(modo);
};

window.toggleConfigFraccionable = function(modo, activo) {
  const seccion = document.getElementById(modo === 'nuevo' ? 'seccionConfigLicorNuevo' : 'seccionConfigLicorEditar');
  if (seccion) {
    seccion.style.display = activo ? 'block' : 'none';
  }
  window.actualizarCalculoFraccionable(modo);
};

window.actualizarCalculoFraccionable = function(modo) {
  const prefijo = modo === 'nuevo' ? 'Nuevo' : 'Editar';
  const chk = document.getElementById(`chk${prefijo}InsumoEsLicor`);
  if (!chk || !chk.checked) return;

  const selCap = document.getElementById(`sel${prefijo}InsumoCapacidad`);
  const txtCapCustom = document.getElementById(`txt${prefijo}InsumoCapacidadCustom`);
  const selShot = document.getElementById(`sel${prefijo}InsumoMedidaShot`);
  const txtShotCustom = document.getElementById(`txt${prefijo}InsumoMedidaShotCustom`);
  const txtCosto = document.getElementById(`txt${prefijo}InsumoCosto`);

  if (selCap && txtCapCustom) {
    txtCapCustom.style.display = (selCap.value === 'custom') ? 'block' : 'none';
  }
  if (selShot && txtShotCustom) {
    txtShotCustom.style.display = (selShot.value === 'custom') ? 'block' : 'none';
  }

  const cap = (selCap?.value === 'custom' ? parseFloat(txtCapCustom?.value) : parseFloat(selCap?.value)) || 750;
  const shot = (selShot?.value === 'custom' ? parseFloat(txtShotCustom?.value) : parseFloat(selShot?.value)) || 30;
  const costo = parseFloat(txtCosto?.value) || 0;

  const rend = shot > 0 ? Math.round((cap / shot) * 10) / 10 : 0;
  const costoPorcion = rend > 0 ? Math.round(costo / rend) : 0;

  const lblRend = document.getElementById(`lblRendimientoShots${prefijo}`);
  const lblCosto = document.getElementById(`lblCostoPorShot${prefijo}`);
  if (lblRend) lblRend.textContent = rend;
  if (lblCosto) lblCosto.textContent = typeof formatCRC === 'function' ? formatCRC(costoPorcion) : `₡${costoPorcion}`;
};

// ELIMINACIÓN DE INSUMO DE BODEGA
window.confirmarEliminarInsumo = async function(insumoId) {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'supervisor' || u.rol === 'developer');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '🗑️',
      titulo: 'Eliminar Insumo de Bodega',
      subtitulo: 'Acceso Restringido',
      mensaje: 'Ingresa el PIN de Administrador (1234) para autorizar la eliminación del insumo:'
    });
    if (!pin) return;
    window._pinSupervisorActivo = pin;
  } else {
    window._pinSupervisorActivo = null;
  }

  const insumo = (estado.inventario || []).find(i => Number(i.id) === Number(insumoId)) || 
                (estado.inventario || []).find(i => String(i.id) === String(insumoId));
  if (!insumo) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('⚠️ Insumo no encontrado en inventario.', 'warning');
    } else {
      alert('Insumo no encontrado');
    }
    return;
  }

  const elId = document.getElementById('txtEliminarInsumoId');
  const elNom = document.getElementById('lblEliminarInsumoNombre');
  const elCat = document.getElementById('lblEliminarInsumoCat');
  const elStock = document.getElementById('lblEliminarInsumoStock');
  const elCos = document.getElementById('lblEliminarInsumoCosto');

  if (elId) elId.value = insumo.id;
  if (elNom) elNom.textContent = insumo.nombre;
  const iconoCat = typeof window.obtenerIconoCategoriaInsumo === 'function' ? window.obtenerIconoCategoriaInsumo(insumo.categoria) : '📦';
  if (elCat) elCat.textContent = `${iconoCat} ${insumo.categoria || 'General'}`;
  if (elStock) elStock.textContent = `${insumo.stock_actual || 0} ${insumo.unidad_medida || 'unidades'}`;
  if (elCos) elCos.textContent = typeof formatCRC === 'function' ? formatCRC(insumo.costo_unitario || 0) : `₡ ${insumo.costo_unitario || 0}`;

  const modal = document.getElementById('modalConfirmarEliminarInsumo');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
};

window.cerrarModalEliminarInsumo = function() {
  const modal = document.getElementById('modalConfirmarEliminarInsumo');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
  window._pinSupervisorActivo = null;
};

window.ejecutarEliminarInsumoConfirmado = async function() {
  const id = document.getElementById('txtEliminarInsumoId')?.value;
  if (!id) return;

  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
    const usuarioNombre = estado.usuarioActual ? (estado.usuarioActual.nombre_completo || estado.usuarioActual.usuario || 'Admin') : 'Admin';
    const headers = {
      'Content-Type': 'application/json',
      'x-user-rol': rol,
      'x-negocio-id': String(nid)
    };
    if (window._pinSupervisorActivo) {
      headers['x-supervisor-pin'] = window._pinSupervisorActivo;
    }

    const res = await fetch(`/api/admin/inventario/${id}`, {
      method: 'DELETE',
      headers,
      body: JSON.stringify({ usuarioNombre, negocio_id: nid })
    });

    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'No se pudo eliminar el insumo');

    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`🗑️ ${data.message || 'Insumo eliminado correctamente de bodega'}`, 'success');
    }
    window.cerrarModalEliminarInsumo();

    if (Array.isArray(estado.inventario)) {
      estado.inventario = estado.inventario.filter(i => i.id !== Number(id) && String(i.id) !== String(id));
    }

    if (typeof cargarInventarioAdmin === 'function') {
      await cargarInventarioAdmin();
    }
    if (typeof poblarSelectorKardexInsumos === 'function') {
      poblarSelectorKardexInsumos();
    }
  } catch (e) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro(`❌ ${e.message}`, 'error');
    } else {
      alert('❌ ' + e.message);
    }
  }
};

// -------------------------------------------------------------
// FICHAS TÉCNICAS & ESCANDALLOS
// -------------------------------------------------------------
window.productosRecetaDisponibles = [];

window.renderOpcionesProductosReceta = function(lista, valorSeleccionado = null) {
  const selectProd = document.getElementById('selectProductoEscandallo');
  const badgeConteo = document.getElementById('badgeConteoRecetas');
  if (!selectProd) return;

  if (!lista || lista.length === 0) {
    selectProd.innerHTML = '<option value="">⚠️ No se encontraron platillos o bebidas</option>';
    if (badgeConteo) badgeConteo.textContent = '(0 encontrados)';
    return;
  }

  // Ordenar lista alfabéticamente de la A a la Z
  const listaOrdenada = [...lista].sort((a, b) => {
    const nomA = (a.producto_nombre || a.nombre || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const nomB = (b.producto_nombre || b.nombre || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    return nomA.localeCompare(nomB, 'es', { sensitivity: 'base' });
  });

  selectProd.innerHTML = listaOrdenada.map(r => {
    const pid = r.producto_id || r.id;
    const pnom = r.producto_nombre || r.nombre || 'Platillo';
    const pvp = Number(r.precio_venta || r.precio || 0);
    const count = Number(r.total_ingredientes || 0);
    const countTxt = count > 0 ? ` (${count} ingrediente${count > 1 ? 's' : ''})` : ' (Sin receta)';
    return `<option value="${pid}">${escapeHtml(pnom)} - PVP: ${formatCRC(pvp)}${countTxt}</option>`;
  }).join('');

  if (badgeConteo) {
    badgeConteo.textContent = `(${listaOrdenada.length} platillos)`;
  }

  if (valorSeleccionado && listaOrdenada.some(r => String(r.producto_id || r.id) === String(valorSeleccionado))) {
    selectProd.value = String(valorSeleccionado);
  } else if (listaOrdenada.length > 0) {
    selectProd.value = String(listaOrdenada[0].producto_id || listaOrdenada[0].id);
  }
};

window.filtrarProductosReceta = function() {
  const q = (document.getElementById('txtBuscarPlatilloReceta')?.value || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
  const selectProd = document.getElementById('selectProductoEscandallo');
  if (!window.productosRecetaDisponibles || window.productosRecetaDisponibles.length === 0) return;

  if (!q) {
    window.renderOpcionesProductosReceta(window.productosRecetaDisponibles);
    if (selectProd && selectProd.value) {
      window.cargarFichaTecnica(selectProd.value);
    }
    return;
  }

  const filtrados = window.productosRecetaDisponibles.filter(r => {
    const nom = (r.producto_nombre || r.nombre || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    return nom.includes(q);
  });

  window.renderOpcionesProductosReceta(filtrados);

  if (filtrados.length > 0 && selectProd) {
    window.cargarFichaTecnica(filtrados[0].producto_id || filtrados[0].id);
  }
};

window.limpiarBuscadorRecetas = function() {
  const inp = document.getElementById('txtBuscarPlatilloReceta');
  if (inp) inp.value = '';
  window.filtrarProductosReceta();
};

window.inicializarPanelRecetas = async function() {
  const selectProd = document.getElementById('selectProductoEscandallo');
  const selectInsumo = document.getElementById('selectNuevoIngredienteInsumo');
  if (!selectProd) return;

  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;

  if (!estado.inventario || !estado.inventario.length) {
    try {
      await cargarInventarioAdmin();
    } catch(e) {
      console.warn('Error cargando inventario para recetas:', e);
    }
  }

  // Llenar selector de insumos disponibles en bodega con soporte de búsqueda inteligente
  if (selectInsumo && estado.inventario && estado.inventario.length) {
    window.renderOpcionesInsumosReceta(estado.inventario);
  }

  // Cargar lista resumida de productos con ficha
  try {
    const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
    const res = await fetch(`/api/admin/recetas/resumen?negocio_id=${nid}`, { 
      headers: { 
        'x-user-rol': rol, 
        'x-negocio-id': String(nid) 
      } 
    });

    if (res.ok) {
      const recetas = await res.json();
      if (Array.isArray(recetas) && recetas.length > 0) {
        window.productosRecetaDisponibles = recetas;
        const currentSearch = document.getElementById('txtBuscarPlatilloReceta')?.value?.trim();
        if (currentSearch) {
          window.filtrarProductosReceta();
        } else {
          window.renderOpcionesProductosReceta(recetas);
          const pid = selectProd.value || recetas[0].producto_id || recetas[0].id;
          window.cargarFichaTecnica(pid);
        }
        return;
      }
    }

    // Fallback a productos locales
    if (estado.productos && estado.productos.length) {
      const adaptados = estado.productos.map(p => ({
        id: p.id,
        producto_id: p.id,
        nombre: p.nombre,
        producto_nombre: p.nombre,
        precio_venta: p.precio,
        precio: p.precio,
        total_ingredientes: 0,
        costo_receta: 0
      }));
      window.productosRecetaDisponibles = adaptados;
      window.renderOpcionesProductosReceta(adaptados);
      window.cargarFichaTecnica(adaptados[0].producto_id);
    }
  } catch (e) {
    console.error('Error al inicializar recetas:', e);
    // Fallback secundario de seguridad
    if (estado.productos && estado.productos.length) {
      const adaptados = estado.productos.map(p => ({
        id: p.id,
        producto_id: p.id,
        nombre: p.nombre,
        producto_nombre: p.nombre,
        precio_venta: p.precio,
        precio: p.precio,
        total_ingredientes: 0,
        costo_receta: 0
      }));
      window.productosRecetaDisponibles = adaptados;
      window.renderOpcionesProductosReceta(adaptados);
      if (selectProd && selectProd.value) {
        window.cargarFichaTecnica(selectProd.value);
      }
    }
  }
};

window.cargarFichaTecnica = async function(productoId) {
  if (!productoId) return;
  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
    const res = await fetch(`/api/admin/recetas/${productoId}?negocio_id=${nid}`, {
      headers: { 
        'x-user-rol': rol,
        'x-negocio-id': String(nid)
      }
    });
    if (!res.ok) throw new Error('Error al consultar ficha técnica');
    const data = await res.json();

    const elCosto = document.getElementById('rkCostoReceta');
    const elFoodCost = document.getElementById('rkFoodCostPorc');
    const elPrecio = document.getElementById('rkPrecioVenta');
    const elMargenBruto = document.getElementById('rkMargenBruto');
    const elMargenPorc = document.getElementById('rkMargenPorc');
    const elPorciones = document.getElementById('rkPorcionesDisponibles');
    const elCount = document.getElementById('recetaItemsCount');

    if (elCosto) elCosto.textContent = formatCRC(data.costo_receta || 0);
    if (elFoodCost) elFoodCost.textContent = `${data.food_cost_porc || 0}% del PVP`;
    if (elPrecio) elPrecio.textContent = formatCRC(data.precio_venta || 0);
    if (elMargenBruto) elMargenBruto.textContent = formatCRC(data.margen_bruto || 0);
    if (elMargenPorc) elMargenPorc.textContent = `${data.margen_porc || 0}% margen bruto`;
    if (elPorciones) elPorciones.textContent = `${data.porciones_disponibles || 0} platos`;
    if (elCount) elCount.textContent = `${(data.ingredientes || []).length} ingrediente${(data.ingredientes || []).length === 1 ? '' : 's'} vinculado${(data.ingredientes || []).length === 1 ? '' : 's'}`;

    const tbody = document.getElementById('tbodyIngredientesReceta');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!data.ingredientes || !data.ingredientes.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align:center; padding:24px; color:#9ca3af;">Este platillo aún no tiene ingredientes vinculados en su escandallo. Agrega insumos abajo.</td></tr>';
      return;
    }

    data.ingredientes.forEach(ing => {
      const tr = document.createElement('tr');
      const cantidadMostrar = ing.medida_amigable ? escapeHtml(ing.medida_amigable) : ing.cantidad_bruta;
      tr.innerHTML = `
        <td><strong>${escapeHtml(ing.insumo_nombre)}</strong></td>
        <td><span style="color:#9ca3af;">${escapeHtml(ing.categoria || ing.insumo_categoria || 'General')}</span></td>
        <td><strong style="color:#38bdf8;">${cantidadMostrar}</strong></td>
        <td><small style="color:#9ca3af;">${escapeHtml(ing.unidad_medida)}</small></td>
        <td>${formatCRC(ing.costo_unitario || 0)}</td>
        <td>${ing.merma_porcentaje ? ing.merma_porcentaje + '%' : '0%'}</td>
        <td style="color:#38bdf8; font-weight:700;">${formatCRC(ing.subtotal_costo || 0)}</td>
        <td><span class="stock-pill ${ing.rendimiento_porciones <= 5 ? 'bajo' : 'normal'}">${ing.rendimiento_porciones} platos (Stock: ${ing.stock_actual})</span></td>
        <td style="text-align:right;">
          <button class="btn-tool" style="background:#7f1d1d; border-color:#ef4444; padding:3px 8px; font-size:0.75rem;" onclick="eliminarIngredienteReceta(${data.producto_id}, ${ing.insumo_id})">🗑️</button>
        </td>
      `;
      tbody.appendChild(tr);
    });
  } catch (e) {
    console.error('Error en cargarFichaTecnica:', e);
  }
};

window.recargarFichaTecnicaActual = function() {
  const pid = document.getElementById('selectProductoEscandallo')?.value;
  if (pid) window.cargarFichaTecnica(pid);
};

window.renderOpcionesInsumosReceta = function(lista, idSeleccionado = null) {
  const selInsumo = document.getElementById('selectNuevoIngredienteInsumo');
  const badgeConteo = document.getElementById('badgeConteoInsumosReceta');
  if (!selInsumo) return;

  if (!lista || lista.length === 0) {
    selInsumo.innerHTML = '<option value="">⚠️ No se encontraron insumos</option>';
    if (badgeConteo) badgeConteo.textContent = '(0 encontrados)';
    window.recalcularCostoPreviewReceta();
    return;
  }

  selInsumo.innerHTML = lista.map(i => {
    const licorTag = i.es_licor ? '🍾 ' : '';
    const stockTxt = i.stock_actual !== undefined ? ` [Stock: ${i.stock_actual}]` : '';
    return `<option value="${i.id}">${licorTag}${escapeHtml(i.nombre)} (${escapeHtml(i.unidad_medida)} - Costo: ${formatCRC(i.costo_unitario)}${stockTxt})</option>`;
  }).join('');

  if (badgeConteo) {
    badgeConteo.textContent = `(${lista.length} disponibles)`;
  }

  if (idSeleccionado && lista.some(i => String(i.id) === String(idSeleccionado))) {
    selInsumo.value = String(idSeleccionado);
  } else {
    selInsumo.value = String(lista[0].id);
  }

  window.alCambiarInsumoReceta();
};

window.filtrarInsumosRecetaInteligente = function() {
  const inp = document.getElementById('txtBuscarInsumoReceta');
  const q = (inp?.value || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
  const todos = estado.inventario || [];

  if (!q) {
    window.renderOpcionesInsumosReceta(todos);
    return;
  }

  // Búsqueda inteligente por múltiples palabras clave
  const palabras = q.split(/\s+/).filter(Boolean);
  const filtrados = todos.filter(i => {
    const textoCompleto = `${i.nombre || ''} ${i.categoria || ''} ${i.unidad_medida || ''}`
      .toLowerCase()
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '');
    return palabras.every(p => textoCompleto.includes(p));
  });

  window.renderOpcionesInsumosReceta(filtrados);
};

window.limpiarBuscadorInsumosReceta = function() {
  const inp = document.getElementById('txtBuscarInsumoReceta');
  if (inp) {
    inp.value = '';
    inp.focus();
  }
  window.filtrarInsumosRecetaInteligente();
};

window.onKeydownBuscadorInsumoReceta = function(e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    const txtCant = document.getElementById('txtNuevoIngredienteCant');
    if (txtCant) {
      txtCant.focus();
      txtCant.select();
    }
  }
};

window.mostrarToastReceta = function(mensaje, tipo = 'success') {
  let container = document.getElementById('toastContainerRecetas');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toastContainerRecetas';
    container.style.cssText = 'position:fixed; top:24px; right:24px; z-index:999999; display:flex; flex-direction:column; gap:10px; pointer-events:none;';
    document.body.appendChild(container);
  }
  const toast = document.createElement('div');
  const borderColor = tipo === 'warning' ? '#f59e0b' : (tipo === 'error' ? '#ef4444' : '#10b981');
  const bgColor = tipo === 'warning' ? '#78350f' : (tipo === 'error' ? '#7f1d1d' : '#064e3b');
  toast.style.cssText = `background:${bgColor}; color:#fff; border:1px solid ${borderColor}; border-radius:10px; padding:12px 18px; font-size:0.9rem; font-weight:700; box-shadow:0 8px 20px rgba(0,0,0,0.6); pointer-events:auto; display:flex; align-items:center; gap:10px; transition:all 0.3s ease;`;
  toast.innerHTML = mensaje;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-12px)';
    setTimeout(() => toast.remove(), 300);
  }, 3200);
};

window.alCambiarInsumoReceta = function() {
  const selInsumo = document.getElementById('selectNuevoIngredienteInsumo');
  const selTipo = document.getElementById('selNuevoIngredienteUnidadTipo');
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  if (!selInsumo || !selTipo) return;

  const insId = parseInt(selInsumo.value);
  const ins = (estado.inventario || []).find(i => Number(i.id) === insId);

  // Si es licor, cambiamos por defecto a Onzas (oz)
  if (ins && ins.es_licor) {
    if (selTipo.value === 'estandar') {
      selTipo.value = 'oz';
    }
  } else {
    // Si no es licor y estaba en oz o shots, volver a estandar
    if (selTipo.value === 'oz' || selTipo.value === 'shots') {
      selTipo.value = 'estandar';
    }
  }

  // Pre-llenar cantidad con 1 por defecto si está vacía
  if (txtCant && (!txtCant.value || parseFloat(txtCant.value) <= 0)) {
    txtCant.value = '1';
  }

  window.actualizarPlaceholderCantidadReceta();
  window.recalcularCostoPreviewReceta();
};

window.actualizarPlaceholderCantidadReceta = function() {
  const selInsumo = document.getElementById('selectNuevoIngredienteInsumo');
  const selTipo = document.getElementById('selNuevoIngredienteUnidadTipo');
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  if (!selInsumo || !selTipo || !txtCant) return;

  const insId = parseInt(selInsumo.value);
  const ins = (estado.inventario || []).find(i => Number(i.id) === insId);
  const tipo = selTipo.value;

  if (tipo === 'botella_350') {
    txtCant.placeholder = 'Ej: 1 botella (350ml / 355ml)';
  } else if (tipo === 'lata_350') {
    txtCant.placeholder = 'Ej: 1 lata (350ml)';
  } else if (tipo === 'lata_473') {
    txtCant.placeholder = 'Ej: 1 lata grande (473ml / 16oz)';
  } else if (tipo === 'oz') {
    txtCant.placeholder = 'Ej: 1, 1.5, 2 o 0.25 oz';
  } else if (tipo === 'shots') {
    if (ins && ins.es_licor && ins.rendimiento_shots > 0) {
      txtCant.placeholder = `Ej: 1 shot (~${ins.medida_shot_ml || 30}ml = ${(1 / ins.rendimiento_shots).toFixed(4)} bot.)`;
    } else {
      txtCant.placeholder = 'Ej: 1 shot / trago';
    }
  } else if (tipo === 'fraccion') {
    txtCant.placeholder = 'Ej: 0.25 (cuarta), 0.5 (media) o 1';
  } else {
    txtCant.placeholder = ins ? `Ej: 0.5 (${ins.unidad_medida})` : 'Ej: 1';
  }
};

window.seleccionarMedidaRapidaReceta = function(tipo, valor, btnElement) {
  const selTipo = document.getElementById('selNuevoIngredienteUnidadTipo');
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  const boxChips = document.getElementById('boxMedidasRapidasReceta');

  if (selTipo) selTipo.value = tipo;
  if (txtCant) {
    txtCant.value = valor;
    txtCant.focus();
  }

  if (boxChips) {
    const chips = boxChips.querySelectorAll('.chip-medida');
    chips.forEach(c => c.classList.remove('active'));
    if (btnElement) btnElement.classList.add('active');
  }

  window.actualizarPlaceholderCantidadReceta();
  window.recalcularCostoPreviewReceta();
};

window.activarModoManualReceta = function(btnElement) {
  const boxChips = document.getElementById('boxMedidasRapidasReceta');
  if (boxChips) {
    const chips = boxChips.querySelectorAll('.chip-medida');
    chips.forEach(c => c.classList.remove('active'));
    if (btnElement) btnElement.classList.add('active');
  }
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  if (txtCant) {
    txtCant.focus();
    txtCant.select();
  }
  window.recalcularCostoPreviewReceta();
};

window.onInputCantidadManualReceta = function() {
  const boxChips = document.getElementById('boxMedidasRapidasReceta');
  const chipManual = document.getElementById('chipMedidaManual');
  if (boxChips && chipManual) {
    const chips = boxChips.querySelectorAll('.chip-medida');
    chips.forEach(c => c.classList.remove('active'));
    chipManual.classList.add('active');
  }
  window.recalcularCostoPreviewReceta();
};

window.recalcularCostoPreviewReceta = function() {
  const selInsumo = document.getElementById('selectNuevoIngredienteInsumo');
  const selTipo = document.getElementById('selNuevoIngredienteUnidadTipo');
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  const txtMerma = document.getElementById('txtNuevoIngredienteMerma');
  const lblPreview = document.getElementById('lblPreviewRecetaCalculo');

  if (!selInsumo || !selTipo || !txtCant || !lblPreview) return;

  const insId = parseInt(selInsumo.value);
  const ins = (estado.inventario || []).find(i => Number(i.id) === insId);
  const cantidad = parseFloat(txtCant.value);
  const merma = parseFloat(txtMerma ? txtMerma.value : 0) || 0;
  const tipo = selTipo.value;

  if (!ins || isNaN(cantidad) || cantidad <= 0) {
    lblPreview.style.display = 'none';
    lblPreview.innerHTML = '';
    return;
  }

  lblPreview.style.display = 'block';

  let fraccionBotella = cantidad;
  let mlDeducidos = null;
  const costoUnit = parseFloat(ins.costo_unitario || 0);
  const mermaFactor = 1 + (merma / 100);

  if (ins.es_licor) {
    const capMl = ins.capacidad_ml || 750;
    if (tipo === 'botella_350') {
      mlDeducidos = Math.round(cantidad * 355 * 10) / 10;
      fraccionBotella = (cantidad * 355) / capMl;
    } else if (tipo === 'lata_350') {
      mlDeducidos = Math.round(cantidad * 350 * 10) / 10;
      fraccionBotella = (cantidad * 350) / capMl;
    } else if (tipo === 'lata_473') {
      mlDeducidos = Math.round(cantidad * 473 * 10) / 10;
      fraccionBotella = (cantidad * 473) / capMl;
    } else if (tipo === 'oz') {
      mlDeducidos = Math.round(cantidad * 30 * 10) / 10;
      fraccionBotella = (cantidad * 30) / capMl;
    } else if (tipo === 'shots') {
      const shotMl = ins.medida_shot_ml || 30;
      mlDeducidos = Math.round(cantidad * shotMl * 10) / 10;
      const rend = ins.rendimiento_shots > 0 ? ins.rendimiento_shots : (capMl / shotMl);
      fraccionBotella = cantidad / rend;
    } else if (tipo === 'fraccion') {
      fraccionBotella = cantidad;
      mlDeducidos = Math.round(cantidad * capMl * 10) / 10;
    } else {
      fraccionBotella = cantidad;
      mlDeducidos = Math.round(cantidad * capMl * 10) / 10;
    }

    const subtotalCosto = Math.round(fraccionBotella * costoUnit * mermaFactor * 100) / 100;
    const porcionesStock = fraccionBotella > 0 ? Math.floor(parseFloat(ins.stock_actual || 0) / fraccionBotella) : 0;
    const porcBotella = Math.round(fraccionBotella * 1000) / 10;

    lblPreview.innerHTML = `
      🥃 <strong>Descuento calculado:</strong> ${mlDeducidos} ml (${porcBotella}% de botella) &nbsp;|&nbsp;
      💰 <strong>Costo estimado:</strong> <span style="color:#4ade80; font-weight:700;">${formatCRC(subtotalCosto)}</span> &nbsp;|&nbsp;
      📊 <strong>Rendimiento:</strong> rinde aprox. <strong>${porcionesStock} porciones</strong> con stock actual (${ins.stock_actual} bot.)
    `;
  } else {
    fraccionBotella = cantidad;
    const subtotalCosto = Math.round(fraccionBotella * costoUnit * mermaFactor * 100) / 100;
    const porcionesStock = fraccionBotella > 0 ? Math.floor(parseFloat(ins.stock_actual || 0) / fraccionBotella) : 0;

    lblPreview.innerHTML = `
      📦 <strong>Descuento calculado:</strong> ${cantidad} ${ins.unidad_medida || 'unidades'} &nbsp;|&nbsp;
      💰 <strong>Costo estimado:</strong> <span style="color:#4ade80; font-weight:700;">${formatCRC(subtotalCosto)}</span> &nbsp;|&nbsp;
      📊 <strong>Rendimiento:</strong> rinde aprox. <strong>${porcionesStock} porciones</strong> con stock actual (${ins.stock_actual})
    `;
  }
};

window.guardarIngredienteReceta = async function() {
  const btnGuardar = document.getElementById('btnVincularIngrediente');
  const productoId = document.getElementById('selectProductoEscandallo')?.value;
  const insumoId = document.getElementById('selectNuevoIngredienteInsumo')?.value;
  const txtCant = document.getElementById('txtNuevoIngredienteCant');
  let cantidad = parseFloat(txtCant?.value);
  const merma = parseFloat(document.getElementById('txtNuevoIngredienteMerma')?.value) || 0;
  const unidadTipo = document.getElementById('selNuevoIngredienteUnidadTipo')?.value || 'estandar';

  // 1. Validar producto seleccionado
  if (!productoId) {
    if (typeof window.mostrarToastReceta === 'function') {
      window.mostrarToastReceta('⚠️ Selecciona primero un platillo o bebida en la parte superior.', 'warning');
    } else {
      alert('⚠️ Selecciona un platillo o bebida.');
    }
    const selProd = document.getElementById('selectProductoEscandallo');
    if (selProd) selProd.focus();
    return;
  }

  // 2. Validar insumo seleccionado
  if (!insumoId) {
    if (typeof window.mostrarToastReceta === 'function') {
      window.mostrarToastReceta('⚠️ Selecciona un insumo de bodega para vincular a la receta.', 'warning');
    } else {
      alert('⚠️ Selecciona un insumo de bodega.');
    }
    const inpBusq = document.getElementById('txtBuscarInsumoReceta');
    if (inpBusq) inpBusq.focus();
    return;
  }

  // 3. Validar cantidad mayor a 0 con retroalimentación visual amigable
  if (isNaN(cantidad) || cantidad <= 0) {
    if (txtCant) {
      txtCant.style.borderColor = '#ef4444';
      txtCant.style.boxShadow = '0 0 10px rgba(239, 68, 68, 0.5)';
      txtCant.focus();
      setTimeout(() => {
        txtCant.style.borderColor = '#374151';
        txtCant.style.boxShadow = 'none';
      }, 2500);
    }
    if (typeof window.mostrarToastReceta === 'function') {
      window.mostrarToastReceta('⚠️ Por favor ingresa una cantidad válida mayor a 0.', 'warning');
    } else {
      alert('⚠️ Ingresa una cantidad válida mayor a 0.');
    }
    return;
  }

  const insumo = (estado.inventario || []).find(i => Number(i.id) === parseInt(insumoId));
  let cantidadDeducir = cantidad;

  if (insumo && insumo.es_licor) {
    const capMl = insumo.capacidad_ml || 750;
    if (unidadTipo === 'botella_350') {
      cantidadDeducir = parseFloat(((cantidad * 355) / capMl).toFixed(4));
    } else if (unidadTipo === 'lata_350') {
      cantidadDeducir = parseFloat(((cantidad * 350) / capMl).toFixed(4));
    } else if (unidadTipo === 'lata_473') {
      cantidadDeducir = parseFloat(((cantidad * 473) / capMl).toFixed(4));
    } else if (unidadTipo === 'oz') {
      // 1 oz = 30ml -> Fracción = (cantidad * 30) / capMl
      cantidadDeducir = parseFloat(((cantidad * 30) / capMl).toFixed(4));
    } else if (unidadTipo === 'shots') {
      const rend = insumo.rendimiento_shots > 0 ? insumo.rendimiento_shots : (capMl / (insumo.medida_shot_ml || 30));
      cantidadDeducir = parseFloat((cantidad / rend).toFixed(4));
    } else if (unidadTipo === 'fraccion' || unidadTipo === 'estandar') {
      cantidadDeducir = parseFloat(cantidad.toFixed(4));
    }
  } else {
    cantidadDeducir = parseFloat(cantidad.toFixed(4));
  }

  if (btnGuardar) {
    btnGuardar.disabled = true;
    btnGuardar.innerHTML = '<span>⏳</span> Guardando...';
  }

  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const rol = (estado.usuarioActual && estado.usuarioActual.rol) ? estado.usuarioActual.rol : 'admin';
    const headers = {
      'Content-Type': 'application/json',
      'x-user-rol': rol,
      'x-negocio-id': String(nid)
    };
    if (window._pinSupervisorActivo) {
      headers['x-supervisor-pin'] = window._pinSupervisorActivo;
    }

    const res = await fetch(`/api/admin/recetas/${productoId}/ingredientes`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        insumo_id: insumoId,
        cantidad: cantidadDeducir,
        merma_porcentaje: merma,
        negocio_id: nid,
        usuarioNombre: estado.usuarioActual?.nombre || 'Administrador'
      })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Error al vincular ingrediente');

    // Notificación no intrusiva de éxito
    window.mostrarToastReceta(`✅ <strong>${insumo ? insumo.nombre : 'Ingrediente'}</strong> añadido al escandallo.`, 'success');

    // Mantener listo el formulario para seguir añadiendo más ingredientes sin fricción
    if (txtCant) txtCant.value = '1';
    const txtM = document.getElementById('txtNuevoIngredienteMerma');
    if (txtM) txtM.value = '0';

    // Limpiar buscador inteligente de insumo y enfocarlo para el siguiente ingrediente
    const txtBusq = document.getElementById('txtBuscarInsumoReceta');
    if (txtBusq) {
      txtBusq.value = '';
      window.filtrarInsumosRecetaInteligente();
      txtBusq.focus();
    }

    // Resetear chips al modo manual
    window.activarModoManualReceta(document.getElementById('chipMedidaManual'));

    // Recargar la tabla de la receta
    await window.cargarFichaTecnica(productoId);

    // Actualizar conteo en el selector de productos
    try {
      const resSum = await fetch(`/api/admin/recetas/resumen?negocio_id=${nid}`, { 
        headers: { 'x-user-rol': rol, 'x-negocio-id': String(nid) } 
      });
      if (resSum.ok) {
        const list = await resSum.json();
        if (Array.isArray(list) && list.length > 0) {
          window.productosRecetaDisponibles = list;
          window.renderOpcionesProductosReceta(list, productoId);
        }
      }
    } catch(_) {}

    // Resaltar suavemente la fila del ingrediente recién guardado
    const tbody = document.getElementById('tbodyIngredientesReceta');
    if (tbody && tbody.lastElementChild) {
      tbody.lastElementChild.style.transition = 'background 0.4s ease';
      tbody.lastElementChild.style.background = 'rgba(56, 189, 248, 0.25)';
      setTimeout(() => {
        if (tbody.lastElementChild) tbody.lastElementChild.style.background = '';
      }, 1500);
    }
  } catch (e) {
    if (typeof window.mostrarToastReceta === 'function') {
      window.mostrarToastReceta('❌ ' + e.message, 'error');
    } else {
      alert('❌ ' + e.message);
    }
  } finally {
    if (btnGuardar) {
      btnGuardar.disabled = false;
      btnGuardar.innerHTML = '<span>💾</span> Vincular Ingrediente';
    }
  }
};

window.eliminarIngredienteReceta = async function(productoId, insumoId) {
  if (!confirm('¿Deseas desvincular este insumo de la ficha técnica?')) return;
  try {
    const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
    const rol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
    const res = await fetch(`/api/admin/recetas/${productoId}/ingredientes/${insumoId}`, {
      method: 'DELETE',
      headers: { 'x-user-rol': rol, 'x-negocio-id': String(nid) }
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);

    mostrarNotificacionCentro('✅ Ingrediente removido de la ficha técnica.', 'success');
    await window.cargarFichaTecnica(productoId);

    // Actualizar conteo en el selector de productos
    try {
      const resSum = await fetch(`/api/admin/recetas/resumen?negocio_id=${nid}`, { 
        headers: { 'x-user-rol': rol, 'x-negocio-id': String(nid) } 
      });
      if (resSum.ok) {
        const list = await resSum.json();
        if (Array.isArray(list) && list.length > 0) {
          window.productosRecetaDisponibles = list;
          window.renderOpcionesProductosReceta(list, productoId);
        }
      }
    } catch(_) {}
  } catch (e) {
    alert('❌ ' + e.message);
  }
};

// -------------------------------------------------------------
// HISTORIAL KARDEX
// -------------------------------------------------------------
window.abrirModalKardex = async function(insumoId) {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'developer');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '📜',
      titulo: 'Historial Kárdex',
      subtitulo: 'Acceso Restringido',
      mensaje: 'Ingresa el PIN de Administrador (1234) para consultar el Kárdex:'
    });
    if (!pin) return;
    window._pinSupervisorActivo = pin;
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('👑 Consulta de Kárdex autorizada con PIN', 'success');
    }
  }

  try {
    const res = await fetch(`/api/admin/inventario/${insumoId}/kardex`, {
      headers: obtenerHeadersAuthAdmin()
    });
    if (!res.ok) throw new Error('Error al consultar Kardex');
    const data = await res.json();

    const insumo = data.insumo || {};
    const elTitulo = document.getElementById('lblTituloKardex');
    const elSub = document.getElementById('lblSubtituloKardex');
    const elStock = document.getElementById('kardexChipStock');
    const elCosto = document.getElementById('kardexChipCosto');
    const elMovs = document.getElementById('kardexChipTotalMovs');
    const chipLicor = document.getElementById('kardexChipLicorInfo');
    const detalleLicor = document.getElementById('kardexChipLicorDetalle');

    if (elTitulo) elTitulo.textContent = `📜 Historial Kardex: ${insumo.nombre || 'Insumo'}`;
    if (elSub) elSub.textContent = `Categoría: ${insumo.categoria || 'General'} | Unidad: ${insumo.unidad_medida || 'unidades'}`;
    if (elStock) elStock.textContent = `${insumo.stock_actual} ${insumo.unidad_medida || ''}`;
    if (elCosto) elCosto.textContent = formatCRC(insumo.costo_unitario || 0);
    if (elMovs) elMovs.textContent = (data.movimientos || []).length;

    if (chipLicor && detalleLicor) {
      if (insumo.es_licor) {
        chipLicor.style.display = 'block';
        const enteras = insumo.botellas_enteras !== null && insumo.botellas_enteras !== undefined ? insumo.botellas_enteras : Math.floor(insumo.stock_actual || 0);
        const remanentes = insumo.shots_remanentes !== null && insumo.shots_remanentes !== undefined ? insumo.shots_remanentes : Math.round(((insumo.stock_actual || 0) - enteras) * (insumo.rendimiento_shots || 25));
        const totalShots = insumo.total_shots_actual !== null && insumo.total_shots_actual !== undefined ? insumo.total_shots_actual : Math.round((insumo.stock_actual || 0) * (insumo.rendimiento_shots || 25));
        detalleLicor.innerHTML = `<strong>${enteras}</strong> bot. y <strong>${remanentes}</strong> shots <small style="color:#a5b4fc;">(${totalShots} shots tot.)</small>`;
      } else {
        chipLicor.style.display = 'none';
      }
    }

    const tbody = document.getElementById('tbodyKardexMovimientos');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!data.movimientos || !data.movimientos.length) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align:center; padding:24px; color:#9ca3af;">No hay movimientos registrados aún en el Kardex para este insumo.</td></tr>';
    } else {
      data.movimientos.forEach(m => {
        const tr = document.createElement('tr');
        const badgeClass = m.tipo === 'venta' ? 'badge-kardex-venta' : m.tipo === 'entrada' ? 'badge-kardex-entrada' : m.tipo === 'merma' ? 'badge-kardex-merma' : 'badge-kardex-fijar';
        const tipoIcon = m.tipo === 'venta' ? '🛒 Venta' : m.tipo === 'entrada' ? '📥 Entrada' : m.tipo === 'merma' ? '⚠️ Merma' : '🔧 Ajuste';
        const signo = m.tipo === 'entrada' ? '+' : '-';

        tr.innerHTML = `
          <td style="font-size:0.8rem; color:#94a3b8;">${formatearFechaHoraCR(m.fecha_hora)}</td>
          <td><span class="${badgeClass}">${tipoIcon}</span></td>
          <td><strong>${signo}${m.cantidad}</strong></td>
          <td><span style="color:#94a3b8;">${m.stock_previo}</span> → <strong style="color:#38bdf8;">${m.stock_nuevo}</strong></td>
          <td style="color:#34d399; font-weight:700;">${formatCRC(m.costo_total || 0)}</td>
          <td style="font-size:0.85rem;">${escapeHtml(m.motivo || '-')}</td>
          <td style="font-size:0.8rem; color:#9ca3af;">${escapeHtml(m.usuario_nombre || 'Sistema')}</td>
        `;
        tbody.appendChild(tr);
      });
    }

    document.getElementById('modalKardexInsumo')?.classList.add('active');
  } catch (e) {
    alert('❌ ' + e.message);
  }
};

window.cerrarModalKardex = function() {
  document.getElementById('modalKardexInsumo')?.classList.remove('active');
};

