window.insumoAEliminarExistenciaId = null;

window.confirmarEliminarExistenciasBodega = async function(insumoId) {
  const u = estado.usuarioActual;
  const esAdmin = u && (u.rol === 'admin' || u.rol === 'superadmin' || u.rol === 'developer' || u.rol === 'supervisor');
  if (!esAdmin) {
    const pin = await window.solicitarPinAdmin({
      icono: '📦',
      titulo: 'Vaciar Existencias en Bodega',
      subtitulo: 'Autorización Requerida',
      mensaje: 'Ingresa el PIN de Administrador/Supervisor (1234) para eliminar las existencias:'
    });
    if (!pin) return;
    window._pinBodegaActivo = pin;
  } else {
    window._pinBodegaActivo = null;
  }

  const insumo = (estado.inventario || []).find(i => i.id === insumoId);
  if (!insumo) {
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('⚠️ Insumo no encontrado en inventario.', 'warning');
    }
    return;
  }

  window.insumoAEliminarExistenciaId = insumoId;
  const elNom = document.getElementById('eliminarExistenciaInsumoNombre');
  const elStock = document.getElementById('eliminarExistenciaStockActual');
  const inMotivo = document.getElementById('txtMotivoEliminarExistencias');

  if (elNom) elNom.textContent = `${insumo.nombre} (${insumo.categoria || 'General'})`;
  if (elStock) elStock.textContent = `${insumo.stock_actual || 0} ${insumo.unidad_medida || 'unidades'}`;
  if (inMotivo) inMotivo.value = 'Eliminación manual de existencias en bodega';

  const modal = document.getElementById('modalConfirmarEliminarExistencias');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
};

window.cerrarModalEliminarExistenciasBodega = function() {
  const modal = document.getElementById('modalConfirmarEliminarExistencias');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
  window.insumoAEliminarExistenciaId = null;
};

window.ejecutarEliminarExistenciasBodegaConfirmado = async function() {
  if (!window.insumoAEliminarExistenciaId) return;
  const insumoId = window.insumoAEliminarExistenciaId;
  const motivo = document.getElementById('txtMotivoEliminarExistencias')?.value?.trim() || 'Eliminación manual de existencias en bodega';

  const nid = estado.negocioActual?.id || (JSON.parse(sessionStorage.getItem('pos_negocio') || '{}').id) || 1;
  const userRol = estado.usuarioActual ? estado.usuarioActual.rol : 'admin';
  const usuarioNombre = estado.usuarioActual ? estado.usuarioActual.nombre_completo || estado.usuarioActual.usuario : 'Administrador';
  const headers = {
    'Content-Type': 'application/json',
    'x-user-rol': userRol,
    'x-negocio-id': String(nid)
  };
  if (window._pinBodegaActivo) {
    headers['x-supervisor-pin'] = window._pinBodegaActivo;
  }

  try {
    const res = await fetch(`/api/admin/inventario/${insumoId}/eliminar-existencias`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ motivo, usuarioNombre, negocio_id: nid })
    });

    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Error al eliminar existencias');

    cerrarModalEliminarExistenciasBodega();
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('✅ Existencias eliminadas y registradas en auditoría.', 'success');
    }

    if (typeof cargarInventarioAdmin === 'function') {
      await cargarInventarioAdmin();
    }
  } catch (e) {
    console.error('Error al eliminar existencias:', e);
    if (typeof mostrarNotificacionCentro === 'function') {
      mostrarNotificacionCentro('❌ ' + e.message, 'error');
    }
  }
};


